              }
    
              const isOwner =
                g.owner_id == currentUser.id ||
                (currentUser && currentUser.status === "super_admin");
              const controls = document.getElementById("group-owner-controls");
              if (isOwner) {
                controls.classList.remove("d-none");
                document.getElementById("group-btn-edit").onclick = async () => {
                  document.getElementById("group-manage-title").innerHTML =
                    '<i class="bi bi-pencil-square text-warning me-2"></i>Edit Group';
                  document.getElementById("group-manage-id").value = g.id;
                  document.getElementById("group-manage-name").value = g.name;
                  document.getElementById("group-manage-desc").value =
                    g.description || "";
    
                  const previewImg = document.getElementById(
                    "group-manage-image-preview",
                  );
                  previewImg.src = `?action=get_group_image&id=${g.id}&t=${Date.now()}`;
                  previewImg.style.display = "block";
                  if (groupCropper) {
                    groupCropper.destroy();
                    groupCropper = null;
                  }
                  if (document.getElementById("group-manage-image"))
                    document.getElementById("group-manage-image").value = "";
    
                  document.getElementById("group-manage-submit").textContent =
                    "Save Changes";
                  document.getElementById("group-manage-submit").className =
                    "btn btn-warning text-dark fw-bold w-100";
                  bootstrap.Modal.getOrCreateInstance(
                    document.getElementById("group-info-modal"),
                  ).hide();
                  bootstrap.Modal.getOrCreateInstance(
                    document.getElementById("group-manage-modal"),
                  ).show();
                };
                document.getElementById("group-btn-delete").onclick = async () => {
                  if (confirm("Permanently delete this group?")) {
                    await fetchData("?action=delete_chat_group", {
                      method: "POST",
                      body: JSON.stringify({
                        id: g.id,
                      }),
                    });
                    bootstrap.Modal.getInstance(
                      document.getElementById("group-info-modal"),
                    ).hide();
                    loadView(currentView);
                  }
                };
                document.getElementById("group-btn-invite").onclick = async () => {
                  const exp = document.getElementById("group-invite-expire").value;
                  const iRes = await fetchData("?action=generate_group_invite", {
                    method: "POST",
                    body: JSON.stringify({
                      id: g.id,
                      expire: exp === "forever" ? null : exp,
