                    const sId =
                      realSongs && realSongs.length > 0 ? realSongs[0].id : "1";
                    const uId =
                      realSongs && realSongs.length > 0 ? realSongs[0].user_id : "1";
                    const pId =
                      realPlaylists && realPlaylists.length > 0
                        ? realPlaylists[0].public_id
                        : "1";
    
                    testUrl = testUrl
                      .replace("SONG_ID", sId)
                      .replace("USER_ID", uId)
                      .replace("PLAYLIST_ID", pId)
                      .replace("YOUR_QUERY", "a");
