            const targetId = this.value;
            const targetElement = document.getElementById(targetId);
            const scrollContainer = document.querySelector(".api-content"); // The scrollable right column
    
            if (targetElement && scrollContainer) {
              // Calculate relative scroll position
              const topPos = targetElement.offsetTop;
              scrollContainer.scrollTo({
                top: topPos - 20, // Add slight padding so it's perfectly visible below the sticky header
                behavior: "smooth",
              });
            }
          });
        }
    
        const playerTrackInfoMobile = document.querySelector(
          ".player-bar .track-info.d-md-none",
        );
        const playerModalEl = document.getElementById("player-modal");
        const playerModal = playerModalEl ? new bootstrap.Modal(playerModalEl) : null;
    
        const profilePictureHeaderDesktop = document.getElementById(
          "profile-picture-header-desktop",
        );
        const profilePictureHeaderMobile = document.getElementById(
          "profile-picture-header-mobile",
        );
        const profilePicturePreview = document.getElementById(
          "profile-picture-preview",
        );
    
        const mmpPlayer = document.getElementById("main-mini-player");
        const mmpCover = document.getElementById("mmp-cover");
        const mmpTitle = document.getElementById("mmp-title");
        const mmpArtist = document.getElementById("mmp-artist");
        const mmpCurTime = document.getElementById("mmp-cur-time");
        const mmpTimeLeft = document.getElementById("mmp-time-left");
        const mmpProgress = document.getElementById("mmp-progress");
        const mmpProgressContainer = document.getElementById("mmp-progress-container");
        const mmpPlayPause = document.getElementById("mmp-play-pause");
        const mmpPlayIcon = document.getElementById("mmp-play-icon");
        const mmpPrev = document.getElementById("mmp-prev");
        const mmpNext = document.getElementById("mmp-next");
        const mmpClose = document.getElementById("mmp-close");

        window.toggleMainMiniPlayer = (forceShow = null) => {
          if (!mmpPlayer) return;
          if (forceShow === true && typeof currentSong !== 'undefined' && currentSong) {
            mmpPlayer.classList.remove('d-none');
            mmpPlayer.style.display = 'flex';
          } else if (forceShow === false) {
            mmpPlayer.classList.add('d-none');
            mmpPlayer.style.display = 'none';
          } else if (forceShow === null && typeof currentSong !== 'undefined' && currentSong) {
            if (mmpPlayer.classList.contains('d-none')) {
              mmpPlayer.classList.remove('d-none');
              mmpPlayer.style.display = 'flex';
            } else {
              mmpPlayer.classList.add('d-none');
              mmpPlayer.style.display = 'none';
            }
          }
        };

        if (mmpClose) mmpClose.addEventListener("click", () => toggleMainMiniPlayer(false));

        const mmpPip = document.getElementById("mmp-pip");
        if (mmpPip) {
          mmpPip.addEventListener("click", (e) => {
            e.stopPropagation();
            if (typeof handlePipAction === "function") {
              handlePipAction();
            } else if (pipBtnDesktop) {
              pipBtnDesktop.click();
            }
          });
        }

        const mmpSeek = document.getElementById("mmp-seek");
        if (mmpSeek) {
          mmpSeek.addEventListener("input", (e) => {
            if (!audio.duration || !isFinite(audio.duration)) return;
            const pct = e.target.value;
            if (mmpProgress) mmpProgress.style.width = `${pct}%`;
          });
          mmpSeek.addEventListener("change", (e) => {
            if (audio.duration && isFinite(audio.duration)) {
              audio.currentTime = (e.target.value / 100) * audio.duration;
            }
          });
        }

        if (mmpPlayer) {
          const mmpHeader = document.getElementById("mmp-header");
          let isDraggingMmp = false, mmpStartX = 0, mmpStartY = 0, mmpInitialLeft = 0, mmpInitialTop = 0;

          const startDragMmp = (e) => {
            if (e.target.closest("button")) return;
            isDraggingMmp = true;
            const clientX = e.touches ? e.touches[0].clientX : e.clientX;
            const clientY = e.touches ? e.touches[0].clientY : e.clientY;
            const rect = mmpPlayer.getBoundingClientRect();
            mmpStartX = clientX;
            mmpStartY = clientY;
            mmpInitialLeft = rect.left;
            mmpInitialTop = rect.top;
            mmpPlayer.style.bottom = "auto";
            mmpPlayer.style.right = "auto";
            mmpPlayer.style.left = mmpInitialLeft + "px";
            mmpPlayer.style.top = mmpInitialTop + "px";
            mmpPlayer.style.transition = "none";
            e.preventDefault();
          };

          const moveDragMmp = (e) => {
            if (!isDraggingMmp) return;
            const clientX = e.touches ? e.touches[0].clientX : e.clientX;
            const clientY = e.touches ? e.touches[0].clientY : e.clientY;
            
            let newLeft = mmpInitialLeft + (clientX - mmpStartX);
            let newTop = mmpInitialTop + (clientY - mmpStartY);

            const maxX = window.innerWidth - mmpPlayer.offsetWidth;
            const maxY = window.innerHeight - mmpPlayer.offsetHeight;
            
            newLeft = Math.max(0, Math.min(newLeft, maxX));
            newTop = Math.max(0, Math.min(newTop, maxY));

            mmpPlayer.style.left = newLeft + "px";
            mmpPlayer.style.top = newTop + "px";
          };

          const stopDragMmp = () => {
            if (isDraggingMmp) isDraggingMmp = false;
          };

          mmpHeader.addEventListener("mousedown", startDragMmp);
          mmpHeader.addEventListener("touchstart", startDragMmp, { passive: false });
          document.addEventListener("mousemove", moveDragMmp);
          document.addEventListener("touchmove", moveDragMmp, { passive: false });
          document.addEventListener("mouseup", stopDragMmp);
          document.addEventListener("touchend", stopDragMmp);
        }

        const playerElements = {
          art: [
            document.getElementById("player-art-desktop"),
            document.getElementById("player-art-mobile"),
            document.getElementById("player-modal-art"),
            document.getElementById("desktop-player-modal-art"),
            mmpCover
          ].filter(Boolean),
          title: [
            document.getElementById("player-title-desktop"),
            document.getElementById("player-title-mobile"),
            document.getElementById("player-modal-title"),
            document.getElementById("desktop-player-modal-title"),
            mmpTitle
          ].filter(Boolean),
          artist: [
            document.getElementById("player-artist-desktop"),
            document.getElementById("player-artist-mobile"),
            document.getElementById("player-modal-artist"),
            document.getElementById("desktop-player-modal-artist"),
            mmpArtist
          ].filter(Boolean),
          currentTime: [
            document.getElementById("current-time"),
            document.getElementById("player-modal-current-time"),
            document.getElementById("desktop-player-modal-current-time"),
            mmpCurTime
          ].filter(Boolean),
          timeLeft: [
            document.getElementById("time-left"),
            document.getElementById("player-modal-time-left"),
            document.getElementById("desktop-player-modal-time-left"),
            mmpTimeLeft
          ].filter(Boolean),
          progress: [
            document.getElementById("progress-bar"),
            document.getElementById("player-modal-progress-bar"),
            document.getElementById("desktop-player-modal-progress-bar"),
            mmpProgress
          ].filter(Boolean),
          progressContainer: [
            document.getElementById("progress-container"),
            document.getElementById("player-modal-progress-container"),
            document.getElementById("desktop-player-modal-progress-container"),
            mmpProgressContainer
          ].filter(Boolean),
          playPauseBtn: [
            document.getElementById("play-pause-btn-desktop"),
            document.getElementById("play-pause-btn-mobile"),
            document.getElementById("player-modal-play-pause-btn"),
            document.getElementById("desktop-player-modal-play-pause-btn"),
            mmpPlayPause
          ].filter(Boolean),
          prevBtn: [
            document.getElementById("prev-btn-desktop"),
            document.getElementById("prev-btn-mobile"),
            document.getElementById("player-modal-prev-btn"),
            document.getElementById("desktop-player-modal-prev-btn"),
            mmpPrev
          ].filter(Boolean),
          nextBtn: [
            document.getElementById("next-btn-desktop"),
            document.getElementById("next-btn-mobile"),
            document.getElementById("player-modal-next-btn"),
            document.getElementById("desktop-player-modal-next-btn"),
            mmpNext
          ].filter(Boolean),
          shuffleBtn: [
            document.getElementById("shuffle-btn-desktop"),
            document.getElementById("shuffle-btn-mobile"),
            document.getElementById("player-modal-shuffle-btn"),
            document.getElementById("desktop-player-modal-shuffle-btn"),
          ],
          repeatBtn: [
            document.getElementById("repeat-btn-desktop"),
            document.getElementById("repeat-btn-mobile"),
            document.getElementById("player-modal-repeat-btn"),
            document.getElementById("desktop-player-modal-repeat-btn"),
          ],
          moreBtn: [
            document.getElementById("player-more-btn-desktop"),
            document.getElementById("player-more-btn-mobile"),
            document.getElementById("player-modal-more-btn"),
            document.getElementById("desktop-player-modal-more-btn"),
          ],
          volumeBtn: document.getElementById("volume-btn"),
          volumeSlider: document.getElementById("volume-slider"),
        };
    
        const dpImmersiveBtn = document.getElementById("dp-immersive-btn");
        const dpModalContent = document.getElementById("dp-modal-content-wrapper");

        if (dpImmersiveBtn && dpModalContent) {
          dpImmersiveBtn.addEventListener("click", () => {
            if (!document.fullscreenElement) {
              document.documentElement.requestFullscreen().then(() => {
                dpModalContent.classList.add("immersive-active");
                dpImmersiveBtn.innerHTML = '<i class="bi bi-fullscreen-exit fs-5"></i>';
              }).catch(err => {
                dpModalContent.classList.add("immersive-active");
                dpImmersiveBtn.innerHTML = '<i class="bi bi-fullscreen-exit fs-5"></i>';
              });
            } else {
              if (document.exitFullscreen) document.exitFullscreen();
            }
          });

          document.addEventListener("fullscreenchange", () => {
            if (!document.fullscreenElement) {
              dpModalContent.classList.remove("immersive-active");
              if (dpImmersiveBtn) dpImmersiveBtn.innerHTML = '<i class="bi bi-arrows-fullscreen fs-5"></i>';
            }
          });
        }

        const desktopPlayerModalEl = document.getElementById("desktop-player-modal");
        const desktopPlayerModal = desktopPlayerModalEl
          ? new bootstrap.Modal(desktopPlayerModalEl)
          : null;
    
        if (playerModalEl) {
          playerModalEl.addEventListener("shown.bs.modal", () => {
            window.enforceScrollToActive(
              "mp-queue-pane",
              "mobile-player-queue-list",
              false,
            );
          });
    
          const mpQueueTabBtn = document.querySelector(
            'button[data-bs-target="#mp-queue-pane"]',
          );
          if (mpQueueTabBtn) {
            mpQueueTabBtn.addEventListener("shown.bs.tab", () => {
              window.enforceScrollToActive(
                "mp-queue-pane",
                "mobile-player-queue-list",
                false,
              );
            });
          }
        }
    
        if (desktopPlayerModalEl) {
          desktopPlayerModalEl.addEventListener("shown.bs.modal", () => {
            window.enforceScrollToActive(
              "dp-queue-pane",
              "desktop-player-queue-list",
              false,
            );
          });
    
          const dpQueueTabBtn = document.querySelector(
            'button[data-bs-target="#dp-queue-pane"]',
          );
          if (dpQueueTabBtn) {
            dpQueueTabBtn.addEventListener("shown.bs.tab", () => {
              window.enforceScrollToActive(
                "dp-queue-pane",
                "desktop-player-queue-list",
                false,
              );
            });
          }
        }
    
        const renderDesktopLyrics = () => {
          const lyricsContainer = document.getElementById("desktop-synced-lyrics");
          const lyricsParent = document.getElementById(
            "desktop-player-modal-lyrics-container",
          );
          if (!lyricsContainer || !currentSong) return;
    
          if (currentSong.lyrics && currentSong.lyrics.trim() !== "") {
            if (lyricsParent) lyricsParent.style.height = "100%";
            lyricsContainer.style.height = "100%";
            const lrcData = parseLRC(currentSong.lyrics);
            if (lrcData.length > 0) {
              currentLrcData = lrcData;
              currentLrcSongId = currentSong.id;
              currentLyricIndex = -1;
              lyricsContainer.style.padding = "35vh 2rem 50vh 2rem";
              lyricsContainer.style.display = "block";
              lyricsContainer.innerHTML = lrcData
                .map(
                  (line, idx) =>
                    `<div class="lyric-line" data-index="${idx}" data-time="${line.time}">${escapeHTML(line.text)}</div>`,
                )
                .join("");
            } else {
              currentLrcData = null;
              currentLrcSongId = null;
              lyricsContainer.style.padding = "2rem";
              lyricsContainer.style.display = "block";
              lyricsContainer.innerHTML = `<div class="desktop-plain-lyrics">${escapeHTML(currentSong.lyrics)}</div>`;
            }
          } else {
            currentLrcData = null;
            currentLrcSongId = null;
            if (lyricsParent) lyricsParent.style.height = "100%";
            lyricsContainer.style.height = "100%";
            lyricsContainer.style.padding = "0";
            lyricsContainer.style.display = "flex";
            lyricsContainer.innerHTML = `
                    <div class="d-flex flex-column align-items-center justify-content-center text-center h-100 w-100 p-4 text-secondary opacity-50">
                      <i class="bi bi-music-note-list mb-3" style="font-size: 3.5rem;"></i>
                      <h5 class="fw-bold text-white mb-1">No Lyrics Available</h5>
                      <p class="small mb-0">Lyrics haven't been added for this track yet.</p>
                    </div>`;
          }
        };
    
        window.renderQueue = async (reset = false, direction = "down") => {
          const queueContainerDesktop = document.getElementById(
            "desktop-player-queue-list",
          );
          const queueContainerMobile = document.getElementById(
            "mobile-player-queue-list",
          );
    
          if (isQueueLoading) return;
          isQueueLoading = true;
    
          if (reset) {
            // Render a chunk specifically around the active song to save DOM memory!
            renderedQueueStart = Math.max(
              0,
              (typeof queueIndex !== "undefined" && queueIndex > -1
                ? queueIndex
                : 0) - 25,
            );
            renderedQueueEnd = Math.min(queue.length, renderedQueueStart + 50);
    
            const listHtml =
              '<div class="text-center py-2 d-none" id="queue-load-prev"><button class="btn btn-sm btn-outline-secondary rounded-pill px-4" onclick="window.renderQueue(false, \'up\')"><i class="bi bi-arrow-up"></i> Load Previous</button></div><div class="song-list"></div><div class="text-center py-3 d-none" id="queue-load-next"><div class="spinner-border spinner-border-sm text-secondary"></div></div>';
    
            if (queueContainerDesktop) queueContainerDesktop.innerHTML = listHtml;
            if (queueContainerMobile) queueContainerMobile.innerHTML = listHtml;
          } else {
            if (direction === "down") {
              if (renderedQueueEnd >= queue.length) {
                isQueueLoading = false;
                return;
              }
            } else if (direction === "up") {
              if (renderedQueueStart <= 0) {
                isQueueLoading = false;
                return;
              }
            }
          }
    
          let chunkStart = 0;
          let chunkEnd = 0;
    
          if (reset) {
            chunkStart = renderedQueueStart;
            chunkEnd = renderedQueueEnd;
          } else if (direction === "down") {
            chunkStart = renderedQueueEnd;
            chunkEnd = Math.min(queue.length, renderedQueueEnd + 25);
          } else if (direction === "up") {
            chunkEnd = renderedQueueStart;
            chunkStart = Math.max(0, renderedQueueStart - 25);
          }
    
          const nextChunkIds = queue.slice(chunkStart, chunkEnd);
          const missingIds = nextChunkIds.filter((id) => !globalSongCache[id]);
    
          // Fetch any data that isn't cached yet
          if (missingIds.length > 0) {
            const fetchedData = await fetchData(
              "?action=get_queue_songs",
              {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  ids: missingIds,
                }),
              },
              true,
            );
            if (fetchedData) {
              fetchedData.forEach((song) => (globalSongCache[song.id] = song));
            }
          }
    
          let html = "";
          const escapeAttr = (str) =>
            str ? String(str).replace(/'/g, "&apos;").replace(/"/g, "&quot;") : "";
    
          nextChunkIds.forEach((songId) => {
            const song = globalSongCache[songId];
            if (!song) return;
            const isNowPlaying = currentSong && songId === currentSong.id;
            const coverSvg = getSvgPlaceholder(song.title || "Unknown");
    
            html += `
                    <div class="song-item py-md-3 ${isNowPlaying ? "now-playing" : ""}"
                      data-song-id="${song.id}"
                      data-is-favorite="${song.is_favorite == 1 ? "1" : "0"}"
                      data-is-collaborative="${song.is_collaborative == 1 ? "1" : "0"}"
                      data-song-title="${escapeAttr(song.title)}"
                      data-song-artist="${escapeAttr(song.artist)}"
                      data-song-album="${escapeAttr(song.album)}"
                      data-song-genre="${escapeAttr(song.genre)}"
                      data-song-user-id="${song.user_id}">
                      <div class="song-indicator-wrapper d-flex align-items-center justify-content-center">
                        <img src="?action=get_image&id=${song.id}&v=${song.last_modified || 0}&size=small" onerror="this.onerror=null; this.src='${coverSvg}';" class="song-thumb" loading="lazy" alt="${escapeAttr(song.title)}">
                        <i class="bi bi-soundwave playing-icon"></i>
                      </div>
                      <div class="song-title-wrapper text-truncate"><div class="song-title text-truncate">${song.is_private == 1 ? '<i class="bi bi-lock-fill text-warning me-1" title="Private Song"></i>' : ""}${song.title}</div></div>
                      <div class="song-artist text-truncate" data-userid="${song.user_id}">
                        <div class="text-truncate">${formatArtistsHTML(song.artist, song.user_id, song.is_collaborative)}</div>
                        <div class="text-secondary d-md-none" style="font-size: 0.8rem; margin-top: 2px;" title="Play Count"><i class="bi bi-eye"></i> ${formatSongCount(song.play_count || 0)}</div>
                      </div>
                      <div class="song-album text-truncate" data-album="${encodeURIComponent(song.album)}" data-userid="${song.user_id}">${song.album}</div>
                      <div class="song-views d-none d-md-block text-truncate" title="${song.play_count || 0} views">${formatSongCount(song.play_count || 0)}</div>
                      <div class="song-duration d-none d-md-block">${formatTime(song.duration)}</div>
                      <div class="song-more"><button class="more-btn" data-song-id="${song.id}"><i class="bi bi-three-dots-vertical"></i></button></div>
                      <div class="song-artist-mobile w-100 flex-column align-items-start">
                        <div class="d-flex justify-content-between align-items-center w-100">
                           <span class="song-artist-name text-truncate flex-grow-1" style="min-width: 0;">${formatArtistsHTML(song.artist, song.user_id, song.is_collaborative)}</span>
                           <span class="song-duration-mobile flex-shrink-0">${formatTime(song.duration)}</span>
                        </div>
                        <div class="text-secondary text-start" style="font-size: 0.8rem; margin-top: 2px;"><i class="bi bi-eye"></i> ${formatSongCount(song.play_count || 0)}</div>
                      </div>
                    </div>`;
          });
    
          const appendHtmlToQueues = (action) => {
            [queueContainerDesktop, queueContainerMobile].forEach((container) => {
              if (container) {
                const lst = container.querySelector(".song-list");
                if (lst) {
                  let oldScrollHeight = 0;
                  const pane = container.closest(".overflow-auto");
                  if (pane) oldScrollHeight = pane.scrollHeight;
    
                  if (action === "append") lst.insertAdjacentHTML("beforeend", html);
                  else lst.insertAdjacentHTML("afterbegin", html);
    
                  lst.querySelectorAll(".song-item:not(.v-obs)").forEach((el) => {
                    el.classList.add("v-obs");
                    virtualObserver.observe(el);
                  });
    
                  if (action === "prepend" && pane) {
                    pane.scrollTop += pane.scrollHeight - oldScrollHeight;
                  }
                }
              }
            });
          };
    
          if (reset || direction === "down") {
            appendHtmlToQueues("append");
            renderedQueueEnd = chunkEnd;
            if (reset) renderedQueueStart = chunkStart;
          } else if (direction === "up") {
            appendHtmlToQueues("prepend");
            renderedQueueStart = chunkStart;
          }
    
          // Update load prev/next buttons safely
          [queueContainerDesktop, queueContainerMobile].forEach((container) => {
            if (container) {
              const loadPrev = container.querySelector("#queue-load-prev");
              const loadNext = container.querySelector("#queue-load-next");
              if (loadPrev) {
                if (renderedQueueStart > 0) loadPrev.classList.remove("d-none");
                else loadPrev.classList.add("d-none");
              }
              if (loadNext) {
                if (renderedQueueEnd < queue.length)
                  loadNext.classList.remove("d-none");
                else loadNext.classList.add("d-none");
              }
            }
          });
    
          isQueueLoading = false;
    
          // Dynamically indicate offline availability for ALL queue items
          caches.open("php-music-offline").then((cache) => {
            const addedItems = document.querySelectorAll(
              "#desktop-player-queue-list .song-item:not(.queue-cache-checked), #mobile-player-queue-list .song-item:not(.queue-cache-checked)",
            );
            addedItems.forEach(async (item) => {
              item.classList.add("queue-cache-checked");
              const sid = item.dataset.songId;
              
              let isCached = false;
              try {
                if (navigator.storage && navigator.storage.getDirectory) {
                  const root = await navigator.storage.getDirectory();
                  const dir = await root.getDirectoryHandle("offline_music_cache");
                  await dir.getFileHandle(`song_${sid}`);
                  isCached = true;
                }
              } catch(e) {}

              if (!isCached) {
                const req = await cache.match(`?action=get_stream&id=${sid}`, {
                  ignoreSearch: false,
                  ignoreVary: true,
                });
                if (req) isCached = true;
              }

              const titleWrapper = item.querySelector(".song-title-wrapper");
    
              if (!isCached) {
                item.classList.add("offline-missing");
                if (!navigator.onLine) {
                  item.style.transition = "opacity 0.3s ease";
                  item.style.opacity = "0.85";
                }
                if (
                  titleWrapper &&
                  !titleWrapper.querySelector(".offline-status-icon")
                ) {
                  titleWrapper.insertAdjacentHTML(
                    "beforeend",
                    ' <i class="bi bi-cloud-slash text-warning offline-status-icon ms-1" title="Not saved offline" style="font-size: 0.85rem;"></i>',
                  );
                }
              } else {
                item.classList.remove("offline-missing");
                item.style.opacity = "1";
                if (
                  titleWrapper &&
                  !titleWrapper.querySelector(".offline-status-icon")
                ) {
                  titleWrapper.insertAdjacentHTML(
                    "beforeend",
                    ' <i class="bi bi-cloud-check-fill text-success offline-status-icon ms-1" title="Available offline" style="font-size: 0.85rem;"></i>',
                  );
                }
              }
            });
          });
    
          // Focus the playing song if it was a total reset
          if (reset && currentSong) {
            if (typeof window.enforceScrollToActive === "function") {
              window.enforceScrollToActive(
                "dp-queue-pane",
                "desktop-player-queue-list",
                true,
              );
              window.enforceScrollToActive(
                "mp-queue-pane",
                "mobile-player-queue-list",
                true,
              );
            }
          }
        };
        // Safely alias it into the global scope
        const renderQueue = window.renderQueue;
    
        const playerArtDesktop = document.getElementById("player-art-desktop");
        if (playerArtDesktop) {
          playerArtDesktop.addEventListener("click", () => {
            if (currentSong && desktopPlayerModal) {
              renderDesktopLyrics();
              renderQueue();
              desktopPlayerModal.show();
            }
          });
        }
    
        // Attach click events to BOTH desktop and mobile Up Next queues
        ["desktop-player-queue-list", "mobile-player-queue-list"].forEach((qId) => {
          const queueList = document.getElementById(qId);
          if (queueList) {
            queueList.addEventListener("click", (e) => {
              const moreBtn = e.target.closest(".more-btn");
              if (moreBtn) {
                e.preventDefault();
                e.stopPropagation();
                showSongItemContextMenu(moreBtn);
                return;
              }
    
              const songArtistEl = e.target.closest(
                ".artist-link, .song-artist, .song-artist-name",
              );
              if (songArtistEl) {
                e.stopPropagation();
    
                const songItem = e.target.closest(".song-item");
                const artistRaw = songItem
                  ? songItem.getAttribute("data-song-artist")
                  : songArtistEl.dataset.artist
                    ? decodeURIComponent(songArtistEl.dataset.artist)
                    : songArtistEl.textContent.trim();
                const userId =
                  songArtistEl.dataset.userid ||
                  (songItem ? songItem.getAttribute("data-song-user-id") : "") ||
                  "";
    
                const artistsList = artistRaw
                  .split(
                    /\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i,
                  )
                  .filter((a) => a && a.trim() !== "");
                if (artistsList.length > 1) {
                  // Keep the player modal open, simply display the choices popup on top
                  if (artistsModalBody) {
                    const modalTitle = artistsModalEl.querySelector(".modal-title");
                    if (modalTitle) modalTitle.textContent = "Artists";
                    artistsModalBody.innerHTML = `
                            <div class="list-group list-group-flush rounded">
                              ${artistsList.map((a, idx) => `<button type="button" class="list-group-item list-group-item-action bg-transparent text-white border-secondary artist-modal-item py-3" data-artist="${encodeURIComponent(a)}" data-userid="${idx === 0 ? userId || "" : ""}">${a}</button>`).join("")}
                            </div>
                          `;
                    if (artistsModal) artistsModal.show();
                  }
                } else {
                  // Only one artist exists: Close the player modals and navigate directly
