            "get_collab_playlists",
            "get_following",
            "get_community",
            "get_notes",
            "get_tasks",
            "get_blogs",
            "get_categories",
            "manage_note_categories",
            "get_projects",
            "get_my_apis",
            "upload_art_page",
            "edit_art_page",
          ];
    
          if (!currentUser && (authRequiredViews.includes(currentView.type) || (currentView.type === 'get_arts' && currentView.filter === 'my_favorites'))) {
