                                display: inline-flex;
                                align-items: center;
                                justify-content: center;
                                gap: 8px;
                                background: rgba(255, 255, 255, 0.05);
                                color: #aaa;
                                border: 1px solid rgba(255, 255, 255, 0.02);
                                cursor: pointer;
                                backdrop-filter: blur(4px);
