                          new Date(a.created_at.replace(" ", "T") + "Z")
                        );
                      if (sortVal === "oldest")
                        return (
                          new Date(a.created_at.replace(" ", "T") + "Z") -
                          new Date(b.created_at.replace(" ", "T") + "Z")
                        );
                      if (sortVal === "modified")
                        return (
                          new Date(b.updated_at.replace(" ", "T") + "Z") -
                          new Date(a.updated_at.replace(" ", "T") + "Z")
                        );
                      if (sortVal === "title_asc")
                        return a.title.localeCompare(b.title);
                      return 0;
                    });
                    const pane = document.getElementById("blogs-pane");
