                      if (sCont && sSel) {
                        sSel.innerHTML =
                          '<option value="newest">Newest</option><option value="oldest">Oldest</option><option value="modified">Recently Modified</option><option value="title_asc">Title (A-Z)</option>';
                        sCont.classList.replace("d-none", "d-flex");
                        if (!sCont.classList.contains("d-flex"))
                          sCont.classList.add("d-flex");
                      }
    
                      if (cCont) {
                        const uniqueCategories = [];
                        const categoryMap = new Set();
                        (window.artistBlogsData || []).forEach((b) => {
                          const catId = b.category || "all";
                          if (catId !== "all" && !categoryMap.has(catId)) {
                            categoryMap.add(catId);
                            uniqueCategories.push({
                              id: catId,
                              name: b.category_name || "Unknown",
