                );
                countEls.forEach((countEl) => {
                  let currentCount =
                    parseInt(countEl.textContent.replace(/\D/g, "")) || 0;
                  countEl.textContent =
                    formatSongCount(currentCount + 1) + " followers";
                });
    
                // Fetch Recommended Artists and show the dismissible container
                const recs = await fetchData(
                  `?action=get_recommended_artists&target_id=${userId}`,
                );
