                for (const song of offlineViewSongsData) {
                  await recacheOfflineSong(parseInt(song.id));
                }
                recacheAllBtn.disabled = false;
                recacheAllBtn.innerHTML =
                  '<i class="bi bi-arrow-repeat me-1"></i> Re-cache All';
