                if (modalTitle) modalTitle.textContent = "Artists";
                artistsModalBody.innerHTML = `
                  <div class="list-group list-group-flush rounded">
                    ${artistsList.map((a, idx) => `<button type="button" class="list-group-item list-group-item-action bg-transparent text-white border-secondary artist-modal-item py-3" data-artist="${encodeURIComponent(a)}" data-userid="${idx === 0 ? userId || "" : ""}">${a}</button>`).join("")}
                  </div>
                `;
                if (artistsModal) artistsModal.show();
              }
            } else {
              // Only one artist exists: Close the player modals and navigate directly
              closeOpenModals();
              loadView({
                type: "artist_songs",
                param: artistRaw,
                sort: "album_asc",
                filter_user_id: userId,
                artist_name: "",
              });
            }
            return;
          }
          const songAlbumEl = target.closest(".song-album, .shelf-item[data-album]");
          if (songAlbumEl) {
            e.stopPropagation();
            const songItem = target.closest(".song-item, .shelf-item");
    
            let rawUserId =
              songAlbumEl.getAttribute("data-userid") ||
              (songItem
                ? songItem.getAttribute("data-userid") ||
                  songItem.getAttribute("data-song-user-id")
                : "") ||
              "";
            let validUserId = parseInt(rawUserId, 10);
            let safeUserId =
              isNaN(validUserId) || validUserId <= 0 ? "" : validUserId;
    
            let albumRaw = decodeURIComponent(
              songAlbumEl.getAttribute("data-album") || "",
            );
            let songArtistRaw = songItem
              ? songItem.getAttribute("data-song-artist") ||
                songItem.querySelector(".item-subtitle")?.textContent ||
                ""
              : "";
            const songArtistsList = songArtistRaw
              .split(
                /\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i,
              )
              .filter((a) => a && a.trim() !== "");
    
            if (songArtistsList.length > 1) {
              if (artistsModalBody) {
                const modalTitle = artistsModalEl.querySelector(".modal-title");
                if (modalTitle) modalTitle.textContent = "Select Album Artist";
                artistsModalBody.innerHTML = `
                        <div class="list-group list-group-flush rounded">
                          ${songArtistsList.map((a, idx) => `<button type="button" class="list-group-item list-group-item-action bg-transparent text-white border-secondary album-modal-item py-3" data-album="${encodeURIComponent(albumRaw)}" data-artist="${encodeURIComponent(a)}" data-userid="${idx === 0 ? safeUserId : ""}">${escapeHTML(albumRaw)} (${escapeHTML(a)})</button>`).join("")}
                        </div>
                      `;
                if (artistsModal) artistsModal.show();
              }
            } else {
              loadView({
                type: "album_songs",
                param: albumRaw,
                sort: "title_asc",
                filter_user_id: safeUserId,
                artist_name: songArtistRaw,
              });
            }
            return;
          }
          const cardEl = target.closest(
            ".card, .shelf-item[data-playlist], .shelf-item[data-mix], .shelf-item[data-artist]",
          );
          if (cardEl && !target.closest(".playlist-more-btn")) {
            let viewType, param, sort;
            let filterUserId = cardEl.dataset.userid || "";
            let filterArtistName = "";
    
            // Protect against 'undefined' or 'null' strings passed in HTML attributes
            if (filterUserId === "undefined" || filterUserId === "null")
              filterUserId = "";
    
            if (cardEl.dataset.artist) {
              viewType = "artist_songs";
              param = decodeURIComponent(cardEl.dataset.artist);
              sort = "album_asc";
              filterUserId = "";
            } else if (cardEl.dataset.album) {
              viewType = "album_songs";
              param = decodeURIComponent(cardEl.dataset.album);
              sort = "title_asc";
              filterArtistName = cardEl.dataset.artistname
