            localStorage.setItem('welcome_blog_shown', 'true');
            window.openBlogEditor({
              id: "",
              public_id: "",
              title: "",
              content: welcomeBlogText,
              status: "private",
              category:
                currentView.filter &&
                currentView.filter !== "all" &&
                currentView.filter !== "public" &&
                currentView.filter !== "private"
