            if (!currentUser) return showToast("Please login", "error");
            const reaction = communityReactBtn.dataset.reaction;
            const iconEl = communityReactBtn.querySelector("i");
            const countEl = communityReactBtn.querySelector("span");
            let count = parseInt(countEl.textContent) || 0;
            const isLiked =
              iconEl.classList.contains("bi-hand-thumbs-up-fill") ||
              iconEl.classList.contains("bi-hand-thumbs-down-fill");
    
            if (isLiked) {
              iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"} fs-5`;
              countEl.textContent = Math.max(0, count - 1);
            } else {
              const sibling = communityReactBtn.parentElement.querySelector(
                `[data-reaction="${reaction === "like" ? "dislike" : "like"}"]`,
              );
              if (sibling) {
                const sibIcon = sibling.querySelector("i");
                if (
                  sibIcon.classList.contains("bi-hand-thumbs-up-fill") ||
                  sibIcon.classList.contains("bi-hand-thumbs-down-fill")
                ) {
                  sibIcon.className = `bi bi-hand-thumbs-${reaction === "like" ? "down" : "up"} fs-5`;
                  const sibCountEl = sibling.querySelector("span");
                  sibCountEl.textContent = Math.max(
                    0,
                    (parseInt(sibCountEl.textContent) || 0) - 1,
                  );
                }
              }
              iconEl.className = `bi bi-hand-thumbs-${reaction === "like" ? "up" : "down"}-fill fs-5`;
              countEl.textContent = count + 1;
            }
            fetchData("?action=toggle_post_reaction", {
              method: "POST",
              body: JSON.stringify({
                post_id: communityReactBtn.dataset.id,
                reaction: reaction,
              }),
            });
            return;
          }
          const editPhpBoardBtn = target.closest(".edit-phpboard-btn");
          if (editPhpBoardBtn) {
            e.stopPropagation();
            const dropdown = editPhpBoardBtn.closest(".custom-opt-menu");
            if (dropdown) dropdown.style.display = "none";
    
            document.getElementById("edit-phpboard-id").value =
              editPhpBoardBtn.dataset.id;
            document.getElementById("edit-phpboard-type").value =
              editPhpBoardBtn.dataset.type;
            document.getElementById("edit-phpboard-input").value = decodeHTML(
              decodeURIComponent(editPhpBoardBtn.dataset.content),
            );
            bootstrap.Modal.getOrCreateInstance(
              document.getElementById("edit-phpboard-modal"),
            ).show();
            return;
