            const dropdown = deletePhpBoardBtn.closest(".custom-opt-menu");
            if (dropdown) dropdown.style.display = "none";
            const id = deletePhpBoardBtn.dataset.id;
            const type = deletePhpBoardBtn.dataset.type;
            const pwd = prompt(
              "Enter post deletion password (leave blank if Admin/Logged in):",
            );
            if (pwd !== null) {
              fetchData("?action=delete_phpboard_post", {
                method: "POST",
                headers: {
                  "Content-Type": "application/x-www-form-urlencoded",
                },
                body: `type=${type}&id=${id}&password=${encodeURIComponent(pwd)}`,
              }).then((res) => {
                if (res && res.status === "success") {
                  if (type === "thread" && currentView.type === "phpboard_thread") {
                    requestCache.clear();
                    loadView({
                      type: "phpboard_index",
                      param: "",
                      sort: "",
                      filter: "",
                    });
                  } else {
                    loadView(currentView);
                  }
                } else showToast(res?.message || "Error deleting", "error");
              });
            }
            return;
          }
          const editCatBtnGlobal = target.closest(".edit-cat-btn-global");
          if (editCatBtnGlobal) {
            e.stopPropagation();
            const type = editCatBtnGlobal.dataset.type || "note";
            loadView({
              type: "manage_note_categories",
              param: "",
              sort: "",
              filter: type,
              filter_user_id: "",
            });
            return;
          }
    
          const createTypedProjectBtn = target.closest(".create-typed-project-btn");
          if (createTypedProjectBtn) {
            e.stopPropagation();
            const pType = createTypedProjectBtn.dataset.type;
            const n = prompt("Project Name:");
            if (n && n.trim() !== "") {
              fetchData("?action=manage_project", {
