                body: JSON.stringify({
                  action_type: "create",
                  name: n,
                  project_type: pType,
                }),
              }).then((res) => {
                if (res && res.status === "success") {
                  showToast("Project created successfully!", "success");
                  loadView(currentView);
                }
              });
            }
            return;
          }
    
          const leaveProjectBtn = target.closest(".leave-project-btn");
          if (leaveProjectBtn) {
