              )
            ) {
              fetchData("?action=manage_project", {
                method: "POST",
                body: JSON.stringify({
                  action_type: "leave",
                  project_id: leaveProjectBtn.dataset.id,
                }),
              }).then((res) => {
                if (res && res.status === "success") {
                  showToast("You have left the project.", "success");
                  loadView(currentView);
                }
              });
            }
            return;
          }
    
          const deleteProjectBtn = target.closest(".delete-project-btn");
          if (deleteProjectBtn) {
