              sort: "newest",
              filter: projectNavBtn.dataset.filter,
            });
            return;
          }
    
          const inviteProjectBtn = target.closest(".invite-project-btn");
          if (inviteProjectBtn) {
            e.stopPropagation();
            const projectId = inviteProjectBtn.dataset.id;
            document.getElementById("manage-project-id").value = projectId;
    
            const loadMembers = async (page = 1) => {
              const res = await fetchData("?action=manage_project", {
                method: "POST",
                body: JSON.stringify({
                  action_type: "list_members",
                  project_id: projectId,
                  page: page,
                }),
              });
              if (res && res.status === "success") {
                const listEl = document.getElementById("project-members-list");
                const html = res.members
                  .map(
                    (m) => `
                      <div class="list-group-item bg-transparent text-white d-flex justify-content-between align-items-center border-secondary px-0">
                        <div class="d-flex align-items-center gap-3">
                          <img src="?action=get_profile_picture&id=${m.id}" class="rounded-circle" style="width: 32px; height: 32px; object-fit: cover;">
                          <div>
                            <div class="d-flex align-items-center gap-2">
                              <span class="badge bg-dark border border-secondary text-secondary" style="font-size: 0.75rem;">ID: ${m.id}</span>
                              <strong class="text-white">${escapeHTML(m.artist)}</strong>
                              ${m.role === "owner" ? '<span class="badge bg-warning text-dark">Owner</span>' : ""}
                            </div>
                            <div class="small text-secondary" style="font-size: 0.75rem; margin-top: 2px;">${escapeHTML(m.email || "")}</div>
                          </div>
                        </div>
                        ${m.role !== "owner" ? `<button class="btn btn-sm btn-outline-danger project-member-remove-btn" data-id="${m.id}"><i class="bi bi-x-lg"></i></button>` : ""}
                      </div>
                    `,
                  )
                  .join("");
    
                if (page === 1) {
                  listEl.innerHTML =
                    res.members.length === 0
                      ? '<p class="text-secondary small">No members.</p>'
                      : html;
                } else {
                  listEl.insertAdjacentHTML("beforeend", html);
                }
    
                const oldBtn = document.getElementById("project-members-load-more");
                if (oldBtn) oldBtn.remove();
    
                if (res.members.length === 25) {
                  listEl.insertAdjacentHTML(
                    "afterend",
                    `<button class="btn btn-sm btn-outline-light w-100 mt-3" id="project-members-load-more" onclick="window.loadProjectMembers(${page + 1})">Load More Members</button>`,
                  );
                }
              }
            };
            window.loadProjectMembers = loadMembers;
    
            // Clean up old elements when opening
            const existingLoadMore = document.getElementById(
              "project-members-load-more",
            );
            if (existingLoadMore) existingLoadMore.remove();
    
            const copyBtn = document.getElementById("project-copy-link-btn");
            const newCopyBtn = copyBtn.cloneNode(true);
            copyBtn.parentNode.replaceChild(newCopyBtn, copyBtn);
    
            newCopyBtn.addEventListener("click", async () => {
              let expireVal = document.getElementById("project-expire-select").value;
              if (expireVal === "forever") expireVal = null;
    
              newCopyBtn.disabled = true;
              newCopyBtn.innerHTML =
                '<span class="spinner-border spinner-border-sm"></span> Generating...';
    
              const r = await fetchData("?action=manage_project", {
                method: "POST",
                body: JSON.stringify({
                  action_type: "generate_link",
                  project_id: projectId,
                  expire: expireVal,
                }),
              });
    
              if (r && r.status === "success") {
                const inviteLink =
                  window.location.origin +
                  window.location.pathname +
                  "?project_invite=" +
                  r.token;
                const onSuccess = () => {
                  newCopyBtn.innerHTML =
                    '<i class="bi bi-check-lg"></i> Link Copied!';
                  newCopyBtn.classList.replace("btn-info", "btn-success");
                  setTimeout(() => {
                    newCopyBtn.innerHTML =
                      '<i class="bi bi-link-45deg"></i> Generate & Copy Link';
                    newCopyBtn.classList.replace("btn-success", "btn-info");
                  }, 2000);
                };
                const onError = () => showToast("Failed to copy link.", "error");
    
                if (navigator.clipboard && window.isSecureContext) {
                  navigator.clipboard
                    .writeText(inviteLink)
                    .then(onSuccess)
                    .catch(onError);
                } else {
                  const textArea = document.createElement("textarea");
                  textArea.value = inviteLink;
                  textArea.style.position = "fixed";
                  textArea.style.opacity = "0";
                  document.body.appendChild(textArea);
                  textArea.focus();
                  textArea.select();
                  try {
                    if (document.execCommand("copy")) onSuccess();
                    else onError();
                  } catch (err) {
                    onError();
                  }
                  document.body.removeChild(textArea);
                }
              } else {
                showToast(r?.message || "Error generating link", "error");
                newCopyBtn.innerHTML =
                  '<i class="bi bi-link-45deg"></i> Generate & Copy Link';
