              if (typeof metadataCropper !== "undefined" && metadataCropper) {
                metadataCropper.destroy();
                metadataCropper = null;
              }
    
              document.getElementById("edit-metadata-cover-preview").src =
                `?action=get_image&id=${id}&v=${Date.now()}`;
              document.getElementById("edit-metadata-cover").value = "";
              const metaSongDataToEdit = await fetchData(
                `?action=get_song_data&id=${id}`,
              );
              document.getElementById("edit-metadata-lyrics").value =
                metaSongDataToEdit ? metaSongDataToEdit.lyrics || "" : "";
              document.getElementById("edit-metadata-is-private").checked =
                metaSongDataToEdit ? metaSongDataToEdit.is_private == 1 : false;
    
              const isCollabCheck = document.getElementById(
