                        <div class="text-white fw-medium text-wrap">${metaSongData.bitrate ? Math.round(metaSongData.bitrate / 1000) + " kbps" : "N/A"}</div>
                      </div>
                      <div class="col-6">
                        <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px; font-size: 0.7rem;">Size</div>
                        <div class="text-white fw-medium text-wrap">${metaSongData.filesize ? (metaSongData.filesize / 1048576).toFixed(2) + " MB" : "N/A"}</div>
                      </div>
                    </div>
                  </div>
                `;
                bootstrap.Modal.getOrCreateInstance(
                  document.getElementById("metadata-modal"),
                ).show();
              }
              break;
            case "show_lyrics":
              const lyricsSongData = await fetchData(
                `?action=get_song_data&id=${id}`,
              );
              if (lyricsSongData) {
                const lyricsTitleEl = document.getElementById("lyrics-modal-title");
                const lyricsBodyEl = document.getElementById("lyrics-modal-body");
    
                if (lyricsTitleEl) lyricsTitleEl.textContent = lyricsSongData.title;
    
                if (lyricsBodyEl) {
                  if (lyricsSongData.lyrics && lyricsSongData.lyrics.trim() !== "") {
                    lyricsBodyEl.style.height = "100%";
                    const lrcData = parseLRC(lyricsSongData.lyrics);
                    if (lrcData.length > 0) {
                      currentLrcData = lrcData;
                      currentLrcSongId = parseInt(lyricsSongData.id);
                      currentLyricIndex = -1;
    
                      lyricsBodyEl.innerHTML =
                        `<div id="synced-lyrics-container" style="padding: 50vh 1.5rem;">` +
                        lrcData
                          .map(
