              const pipPaneLyrics =
                docPipWindow.document.getElementById("pip-pane-lyrics");
    
              pipTabPlayer.addEventListener("click", () => {
                pipTabPlayer.classList.add("active");
                pipTabLyrics.classList.remove("active");
                pipPanePlayer.classList.add("active");
                pipPaneLyrics.classList.remove("active");
              });
    
              pipTabLyrics.addEventListener("click", () => {
                pipTabLyrics.classList.add("active");
                pipTabPlayer.classList.remove("active");
                pipPaneLyrics.classList.add("active");
                pipPanePlayer.classList.remove("active");
                const activeLine = pipPaneLyrics.querySelector(
                  ".pip-lyric-line.active",
                );
                if (activeLine)
                  activeLine.scrollIntoView({
                    behavior: "smooth",
                    block: "center",
                  });
              });
    
              window.renderPipLyrics = () => {
                if (!docPipWindow) return;
                const container = docPipWindow.document.getElementById(
                  "pip-lyrics-container",
                );
                if (!container || !currentSong) return;
    
                if (currentSong.lyrics && currentSong.lyrics.trim() !== "") {
                  container.style.height = "100%";
                  const lrcData = parseLRC(currentSong.lyrics);
                  if (lrcData.length > 0) {
                    currentLrcData = lrcData;
                    currentLrcSongId = currentSong.id;
                    currentLyricIndex = -1;
                    container.innerHTML = lrcData
                      .map(
                        (line, idx) =>
                          `<div class="pip-lyric-line" data-index="${idx}" data-time="${line.time}">${escapeHTML(line.text)}</div>`,
                      )
                      .join("");
    
                    container.querySelectorAll(".pip-lyric-line").forEach((line) => {
                      line.addEventListener("click", (e) => {
                        if (isFinite(audio.duration))
                          audio.currentTime = parseFloat(e.target.dataset.time);
                      });
                    });
                  } else {
                    container.innerHTML = `<div class="desktop-plain-lyrics">${escapeHTML(currentSong.lyrics)}</div>`;
                  }
                } else {
                  container.style.height = "100dvh";
                  container.innerHTML = `
                    <div class="d-flex flex-column align-items-center justify-content-center text-center p-4 text-secondary opacity-50" style="height: 100dvh;">
                      <i class="bi bi-music-note-list mb-2" style="font-size: 2.5rem;"></i>
                      <h6 class="fw-bold text-white mb-1">No Lyrics Available</h6>
                    </div>
                  `;
                }
              };
    
              const pipEls = {
                art: docPipWindow.document.getElementById("pip-art"),
                title: docPipWindow.document.getElementById("pip-title"),
                artist: docPipWindow.document.getElementById("pip-artist"),
                currentTime: docPipWindow.document.getElementById("pip-current-time"),
                timeLeft: docPipWindow.document.getElementById("pip-time-left"),
                progress: docPipWindow.document.getElementById("pip-progress-bar"),
                progressContainer: docPipWindow.document.getElementById(
                  "pip-progress-container",
                ),
                seekSlider: docPipWindow.document.getElementById("pip-seek-slider"),
                playPauseBtn: docPipWindow.document.getElementById("pip-play-pause-btn"),
                prevBtn: docPipWindow.document.getElementById("pip-prev-btn"),
                nextBtn: docPipWindow.document.getElementById("pip-next-btn"),
                shuffleBtn: docPipWindow.document.getElementById("pip-shuffle-btn"),
                repeatBtn: docPipWindow.document.getElementById("pip-repeat-btn"),
              };

              playerElements.art.push(pipEls.art);
              playerElements.title.push(pipEls.title);
              playerElements.artist.push(pipEls.artist);
              playerElements.currentTime.push(pipEls.currentTime);
              playerElements.timeLeft.push(pipEls.timeLeft);
              playerElements.progress.push(pipEls.progress);
              playerElements.progressContainer.push(pipEls.progressContainer);
              playerElements.playPauseBtn.push(pipEls.playPauseBtn);
              playerElements.prevBtn.push(pipEls.prevBtn);
              playerElements.nextBtn.push(pipEls.nextBtn);
              playerElements.shuffleBtn.push(pipEls.shuffleBtn);
              playerElements.repeatBtn.push(pipEls.repeatBtn);

              pipEls.playPauseBtn.addEventListener("click", togglePlayPause);
              setupHoldToSkip([pipEls.prevBtn], "prev", playPrev);
              setupHoldToSkip([pipEls.nextBtn], "next", playNext);
              pipEls.shuffleBtn.addEventListener("click", toggleShuffle);
              pipEls.repeatBtn.addEventListener("click", () => {
                repeatMode =
                  repeatMode === "none" ?
                  "all" :
                  repeatMode === "all" ?
                  "one" :
                  "none";
                updateRepeatIcons();
              });

              pipEls.artist.style.cursor = "pointer";
              pipEls.artist.addEventListener(
                "mouseenter",
                () => (pipEls.artist.style.textDecoration = "underline"),
              );
              pipEls.artist.addEventListener(
                "mouseleave",
                () => (pipEls.artist.style.textDecoration = "none"),
              );

              pipEls.artist.addEventListener("click", (e) => {
                e.stopPropagation();
                if (!currentSong) return;

                const artistRaw = currentSong.artist;
                const userId = currentSong.user_id || "";
                const artistsList = artistRaw
                  .split(
                    /\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i,
                  )
                  .filter((a) => a && a.trim() !== "");

                if (artistsList.length > 1) {
                  if (artistsModalBody) {
                    artistsModalBody.innerHTML = `
                          <div class="list-group list-group-flush rounded">
                            ${artistsList.map((a) => `<button type="button" class="list-group-item list-group-item-action bg-transparent text-white border-secondary artist-modal-item py-3" data-artist="${encodeURIComponent(a)}" data-userid="${userId}">${a}</button>`).join("")}
                          </div>
                        `;
                    if (artistsModal) artistsModal.show();
                  }
                } else {
                  closeOpenModals();
                  hideMobileSidebar();
                  loadView({
                    type: "artist_songs",
                    param: artistRaw,
                    sort: "album_asc",
                    filter_user_id: userId,
                  });
                }
              });

              let isSeekingPip = false;
              pipEls.seekSlider.addEventListener("input", (e) => {
                isSeekingPip = true;
                const percent = e.target.value;
                pipEls.progress.style.width = `${percent}%`;
                if (isFinite(audio.duration)) {
                  pipEls.currentTime.textContent = formatTime(
                    (percent / 100) * audio.duration,
                  );
                }
              });
              pipEls.seekSlider.addEventListener("change", (e) => {
                if (isFinite(audio.duration)) {
                  audio.currentTime = (e.target.value / 100) * audio.duration;
                }
                isSeekingPip = false;
              });

              const updateSliderPip = () => {
                if (!isSeekingPip && docPipWindow && isFinite(audio.duration)) {
                  const percent = (audio.currentTime / audio.duration) * 100;
                  pipEls.seekSlider.value = percent;
                }
              };
              audio.addEventListener("timeupdate", updateSliderPip);
    
              if (pipBtnDesktop) pipBtnDesktop.classList.add("active");
              if (pipBtnMobile) pipBtnMobile.classList.add("active");
    
              docPipWindow.addEventListener("pagehide", () => {
                audio.removeEventListener("timeupdate", updateSliderPip);
                playerElements.art = playerElements.art.filter(
                  (el) => el !== pipEls.art,
                );
                playerElements.title = playerElements.title.filter(
                  (el) => el !== pipEls.title,
                );
                playerElements.artist = playerElements.artist.filter(
                  (el) => el !== pipEls.artist,
                );
                playerElements.currentTime = playerElements.currentTime.filter(
                  (el) => el !== pipEls.currentTime,
                );
                playerElements.timeLeft = playerElements.timeLeft.filter(
                  (el) => el !== pipEls.timeLeft,
                );
                playerElements.progress = playerElements.progress.filter(
                  (el) => el !== pipEls.progress,
                );
                playerElements.progressContainer =
                  playerElements.progressContainer.filter(
                    (el) => el !== pipEls.progressContainer,
                  );
                playerElements.playPauseBtn = playerElements.playPauseBtn.filter(
                  (el) => el !== pipEls.playPauseBtn,
                );
                playerElements.prevBtn = playerElements.prevBtn.filter(
                  (el) => el !== pipEls.prevBtn,
                );
                playerElements.nextBtn = playerElements.nextBtn.filter(
                  (el) => el !== pipEls.nextBtn,
                );
                playerElements.shuffleBtn = playerElements.shuffleBtn.filter(
                  (el) => el !== pipEls.shuffleBtn,
                );
                playerElements.repeatBtn = playerElements.repeatBtn.filter(
                  (el) => el !== pipEls.repeatBtn,
                );
    
                docPipWindow = null;
                if (pipBtnDesktop) pipBtnDesktop.classList.remove("active");
                if (pipBtnMobile) pipBtnMobile.classList.remove("active");
              });
    
              pipEls.prevBtn.innerHTML = ICONS.prev;
              pipEls.nextBtn.innerHTML = ICONS.next;
              pipEls.shuffleBtn.innerHTML = ICONS.shuffle;
    
              updatePlayerUI();
              updatePlayPauseIcons();
              updateRepeatIcons();
              updateShuffleButtons();
            } catch (err) {
              console.error("Doc PiP failed, falling back to video PiP", err);
              fallbackVideoPip();
            }
          } else {
            fallbackVideoPip();
          }
        };
    
        if (pipBtnDesktop) pipBtnDesktop.addEventListener("click", handlePipAction);
        if (pipBtnMobile) pipBtnMobile.addEventListener("click", handlePipAction);
    
        function fallbackVideoPip() {
          if (document.pictureInPictureElement) {
            document.exitPictureInPicture().catch(() => {});
          } else {
            pipVideo
              .play()
              .then(() => {
                pipVideo.requestPictureInPicture().catch((err) => {
                  console.error("PiP failed", err);
                  showToast(
                    "Picture-in-Picture is not supported by your browser.",
                    "error",
                  );
                });
              })
              .catch(console.error);
          }
        }
    
        pipVideo.addEventListener("enterpictureinpicture", () => {
          if (pipBtnDesktop) pipBtnDesktop.classList.add("active");
          if (pipBtnMobile) pipBtnMobile.classList.add("active");
        });
        pipVideo.addEventListener("leavepictureinpicture", () => {
          if (!docPipWindow) {
            if (pipBtnDesktop) pipBtnDesktop.classList.remove("active");
            if (pipBtnMobile) pipBtnMobile.classList.remove("active");
          }
        });
    
        clearCacheBtn.addEventListener("click", async (e) => {
          e.preventDefault();
          if (
            !confirm(
              "This will clear all cached app data and reload the page. Are you sure?",
            )
          ) {
            return;
          }
          try {
            try {
              const root = await navigator.storage.getDirectory();
              const fileHandle = await root.getFileHandle("appVersion.txt");
              await fileHandle.remove();
            } catch (err) {}
            if ("caches" in window) {
              const keys = await caches.keys();
              await Promise.all(
                keys.map((key) => {
                  if (key !== "php-music-offline") {
                    return caches.delete(key);
                  }
                }),
              );
            }
            if ("serviceWorker" in navigator) {
              const registrations = await navigator.serviceWorker.getRegistrations();
              for (const registration of registrations) {
                await registration.unregister();
              }
            }
            showToast("Cache cleared successfully. Reloading...", "success");
            setTimeout(() => window.location.reload(true), 1500);
          } catch (error) {
            console.error("Error clearing cache:", error);
            showToast("Failed to clear cache.", "error");
          }
        });
    
        const clearCookiesBtn = document.getElementById("clear-cookies-btn");
        if (clearCookiesBtn) {
          clearCookiesBtn.addEventListener("click", (e) => {
            e.preventDefault();
            if (
              !confirm("This will log you out and clear all cookies. Are you sure?")
            )
              return;
            document.cookie.split(";").forEach(function (c) {
              document.cookie = c
                .replace(/^ +/, "")
                .replace(/=.*/, "=;expires=" + new Date().toUTCString() + ";path=/");
            });
            showToast("Cookies cleared successfully. Reloading...", "success");
            setTimeout(() => window.location.reload(true), 1500);
          });
        }
    
        const clearSessionBtn = document.getElementById("clear-session-btn");
