                  showToast("Invalid JSON format. Missing notes array.", "error");
                  return;
                }
    
                const btn = importNotesForm.querySelector('button[type="submit"]');
                const originalText = btn.innerHTML;
                btn.disabled = true;
                btn.innerHTML =
                  '<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span> Importing...';
    
                const result = await fetchData("?action=import_notes", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify(importData),
                });
    
                if (result) {
                  showToast(result.message, result.status);
                  if (result.status === "success") {
                    bootstrap.Modal.getOrCreateInstance(
                      document.getElementById("import-notes-modal"),
                    ).hide();
                    importNotesForm.reset();
                    requestCache.clear();
                    loadView(currentView); // Refresh the Notes view
                  }
                }
                btn.disabled = false;
                btn.innerHTML = originalText;
              } catch (err) {
                showToast("Failed to parse JSON or import.", "error");
                const btn = importNotesForm.querySelector('button[type="submit"]');
                btn.disabled = false;
                btn.textContent = "Import Notes";
              }
            };
            reader.readAsText(file);
          });
