        const sleepTimerBubble = document.getElementById("sleep-timer-bubble");
        const sleepTimerCountdown = document.getElementById("sleep-timer-countdown");
        const sleepTimerCancelBtn = document.getElementById("sleep-timer-cancel-btn");
        const sleepTimerWakeBtn = document.getElementById("sleep-timer-wake-btn");
    
        let noSleep = new NoSleep();
    
        const releaseWakeLock = () => {
          if (sleepTimerKeepAwake) {
            noSleep.disable();
            sleepTimerKeepAwake = false;
            if (sleepTimerWakeBtn) {
              sleepTimerWakeBtn.classList.remove("active");
              sleepTimerWakeBtn.innerHTML = '<i class="bi bi-display"></i>';
            }
          }
        };
    
        const toggleWakeLock = async (e) => {
          if (e) e.stopPropagation();
    
          if (sleepTimerKeepAwake) {
            releaseWakeLock();
            showToast("Screen wake lock disabled.", "info");
          } else {
            try {
              noSleep.enable();
              sleepTimerKeepAwake = true;
              if (sleepTimerWakeBtn) {
                sleepTimerWakeBtn.classList.add("active");
                sleepTimerWakeBtn.innerHTML = '<i class="bi bi-display-fill"></i>';
              }
              showToast("Screen will stay awake.", "success");
            } catch (err) {
              showToast("Failed to acquire screen wake lock.", "error");
            }
          }
        };
    
        if (sleepTimerWakeBtn) {
          sleepTimerWakeBtn.addEventListener("click", toggleWakeLock);
        }
    
        const cancelSleepTimer = () => {
          if (sleepTimerInterval) clearInterval(sleepTimerInterval);
          sleepTimerInterval = null;
          sleepTimerBubble.classList.add("d-none");
          releaseWakeLock();
          showToast("Sleep timer canceled.", "info");
        };
    
        sleepTimerCancelBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          cancelSleepTimer();
        });
    
        const handleSleepTimer = (e) => {
          if (e) e.preventDefault();
          if (sleepTimerInterval) {
            if (confirm(`Sleep timer is active. Cancel it?`)) {
              cancelSleepTimer();
            }
            return;
          }
          const mins = prompt("Stop playing after how many minutes?", "30");
          if (mins && !isNaN(mins) && parseInt(mins) > 0) {
            releaseWakeLock();
    
            const ms = parseInt(mins) * 60000;
            sleepTimerEndTime = Date.now() + ms;
    
            const updateTimer = () => {
              const now = Date.now();
              const remaining = sleepTimerEndTime - now;
              if (remaining <= 0) {
                clearInterval(sleepTimerInterval);
                sleepTimerInterval = null;
                sleepTimerBubble.classList.add("d-none");
                releaseWakeLock();
                if (isPlaying) togglePlayPause();
                showToast("Sleep timer reached. Playback paused.", "info");
                return;
              }
              const totalSeconds = Math.floor(remaining / 1000);
              const m = Math.floor(totalSeconds / 60);
              const s = (totalSeconds % 60).toString().padStart(2, "0");
              sleepTimerCountdown.textContent = `${m}:${s}`;
            };
    
            updateTimer();
            sleepTimerInterval = setInterval(updateTimer, 1000);
            sleepTimerBubble.classList.remove("d-none");
            showToast(`Sleep timer set for ${mins} minutes.`, "success");
          }
        };
    
        // Sleep Timer Bubble Dragging Logic
        let isDraggingBubble = false;
        let bubbleOffsetX, bubbleOffsetY;
    
        const startDragBubble = (e) => {
          if (e.target.closest(".action-btn")) return;
          isDraggingBubble = true;
          const clientX = e.touches ? e.touches[0].clientX : e.clientX;
          const clientY = e.touches ? e.touches[0].clientY : e.clientY;
          const rect = sleepTimerBubble.getBoundingClientRect();
          bubbleOffsetX = clientX - rect.left;
          bubbleOffsetY = clientY - rect.top;
          sleepTimerBubble.style.cursor = "grabbing";
        };
    
        const moveDragBubble = (e) => {
          if (!isDraggingBubble) return;
          e.preventDefault(); // Prevents screen scrolling while dragging
          const clientX = e.touches ? e.touches[0].clientX : e.clientX;
          const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    
          let newLeft = clientX - bubbleOffsetX;
          let newTop = clientY - bubbleOffsetY;
    
          const maxX = window.innerWidth - sleepTimerBubble.offsetWidth;
          const maxY = window.innerHeight - sleepTimerBubble.offsetHeight;
          newLeft = Math.max(0, Math.min(newLeft, maxX));
          newTop = Math.max(0, Math.min(newTop, maxY));
    
          sleepTimerBubble.style.left = `${newLeft}px`;
          sleepTimerBubble.style.top = `${newTop}px`;
          sleepTimerBubble.style.right = "auto"; // Disable initial right constraint
        };
    
        const stopDragBubble = () => {
          if (isDraggingBubble) {
            isDraggingBubble = false;
            sleepTimerBubble.style.cursor = "grab";
          }
        };
    
        sleepTimerBubble.addEventListener("mousedown", startDragBubble);
        sleepTimerBubble.addEventListener("touchstart", startDragBubble, {
          passive: false,
        });
        document.addEventListener("mousemove", moveDragBubble, {
          passive: false,
        });
        document.addEventListener("touchmove", moveDragBubble, {
          passive: false,
        });
        document.addEventListener("mouseup", stopDragBubble);
        document.addEventListener("touchend", stopDragBubble);
    
        document
          .getElementById("sleep-timer-btn-desktop")
          .addEventListener("click", handleSleepTimer);
        document
          .getElementById("sleep-timer-btn-mobile")
          .addEventListener("click", handleSleepTimer);
    
        let profileBgCropper = null;
        const profileBgInput = document.getElementById("profile-bg-input");
        const profileBgPreview = document.getElementById("profile-bg-preview");
        const profileBgPreviewContainer = document.getElementById(
          "profile-bg-preview-container",
        );
    
        if (profileBgInput) {
          profileBgInput.addEventListener("change", function (e) {
            if (this.files && this.files[0]) {
              const reader = new FileReader();
              reader.onload = (ev) => {
                profileBgPreviewContainer.style.display = "block";
                profileBgPreview.src = ev.target.result;
                if (profileBgCropper) profileBgCropper.destroy();
                profileBgCropper = new Cropper(profileBgPreview, {
                  aspectRatio: 3 / 1,
                  viewMode: 1,
                  autoCropArea: 1,
                  dragMode: "move",
                  background: false,
                });
              };
              reader.readAsDataURL(this.files[0]);
            }
          });
        }
    
        const profileBgForm = document.getElementById("profile-bg-form");
        const bioForm = document.getElementById("bio-form");
    
        if (profileBgForm) {
          profileBgForm.addEventListener("submit", async (e) => {
            e.preventDefault();
            if (profileBgInput.files.length === 0 && !profileBgCropper) {
              showToast("Please select an image file.", "error");
              return;
            }
            const submitBtn = document.getElementById("profile-bg-submit-btn");
            submitBtn.disabled = true;
            submitBtn.textContent = "Uploading...";
    
            const doBgUpload = async (blob) => {
              const formData = new FormData();
              formData.append("profile_background", blob, "background.jpg");
    
              try {
                const res = await fetch("?action=upload_profile_background", {
                  method: "POST",
                  body: formData,
                });
                const result = await res.json();
                showToast(result.message, result.status);
                if (result.status === "success") {
                  if (profileBgCropper) {
                    profileBgCropper.destroy();
                    profileBgCropper = null;
                  }
                  profileBgPreviewContainer.style.display = "none";
                  profileBgInput.value = "";
                  await checkSession();
                  if (currentView.type === "user_profile") loadView(currentView);
                }
              } catch (err) {
                showToast("Upload failed", "error");
              }
              submitBtn.disabled = false;
              submitBtn.textContent = "Save Uploaded Background";
            };
    
            if (profileBgCropper) {
              profileBgCropper
                .getCroppedCanvas({
                  width: 1200,
                  height: 400,
                })
                .toBlob(
                  (blob) => {
                    doBgUpload(blob);
                  },
                  "image/jpeg",
                  0.85,
                );
            } else {
              doBgUpload(profileBgInput.files[0]);
            }
          });
        }
    
        // --- BACKGROUND GENERATOR LOGIC ---
        const bgCanvas = document.getElementById("bg-gen-canvas");
        if (bgCanvas) {
          const bgCtx = bgCanvas.getContext("2d");
          const bgState = {
            pattern: "blobs",
            hue: Math.floor(Math.random() * 360),
            saturation: 70,
            complexity: 5,
            scale: 100,
            angle: 0,
            drawStyle: "fill",
            seed: Math.random(),
          };
          let bgRng = null;
    
          function bgMulberry32(a) {
            return function () {
              var t = (a += 0x6d2b79f5);
              t = Math.imul(t ^ (t >>> 15), t | 1);
              t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
              return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
            };
          }
    
          function bgGetHsl(h, s, l, a = 1) {
            return `hsla(${h}, ${s}%, ${l}%, ${a})`;
          }
    
          function bgGetPalette() {
            const h = bgState.hue;
            const s = bgState.saturation;
            return [
              bgGetHsl(h, s, 40),
              bgGetHsl(h, s * 0.6, 30),
              bgGetHsl((h + 40) % 360, s * 0.8, 40),
              bgGetHsl((h - 40 + 360) % 360, s * 0.8, 40),
              bgGetHsl(h, s, 80, 0.7),
            ];
          }
    
          function bgApplyStyle(color) {
            bgCtx.fillStyle = color;
            bgCtx.strokeStyle = color;
            bgCtx.lineWidth = Math.max(
              1,
              ((bgState.scale / 100) * 15) / (bgState.complexity * 0.5),
            );
            bgCtx.lineCap = "round";
            bgCtx.lineJoin = "round";
          }
    
          function bgDrawPath() {
            if (bgState.drawStyle === "fill") bgCtx.fill();
            else if (bgState.drawStyle === "stroke") bgCtx.stroke();
            else {
              if (bgRng() > 0.5) bgCtx.fill();
              else bgCtx.stroke();
            }
          }
    
          const bgDrawFns = {
            blobs: (b, pal) => {
              const count = bgState.complexity * 3;
              const baseSize = (b.w * (bgState.scale / 100)) / 4;
              for (let i = 0; i < count; i++) {
                const cx = b.x + bgRng() * b.w;
                const cy = b.y + bgRng() * b.h;
                const size = baseSize * (0.5 + bgRng());
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.beginPath();
                const points = 5 + Math.floor(bgRng() * 3);
                let angle = 0;
                for (let j = 0; j <= points; j++) {
                  const r = size * (0.6 + bgRng() * 0.4);
                  const x = cx + Math.cos(angle) * r;
                  const y = cy + Math.sin(angle) * r;
                  if (j === 0) bgCtx.moveTo(x, y);
                  else {
                    const cp1x = cx + Math.cos(angle - Math.PI / points) * size;
                    const cp1y = cy + Math.sin(angle - Math.PI / points) * size;
                    bgCtx.quadraticCurveTo(cp1x, cp1y, x, y);
                  }
                  angle += (Math.PI * 2) / points;
                }
                bgDrawPath();
              }
            },
            geometric: (b, pal) => {
              const count = bgState.complexity * 5;
              const baseSize = (b.w * (bgState.scale / 100)) / 6;
              for (let i = 0; i < count; i++) {
                const x = b.x + bgRng() * b.w;
                const y = b.y + bgRng() * b.h;
                const size = baseSize * (0.2 + bgRng());
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                const type = Math.floor(bgRng() * 3);
                bgCtx.save();
                bgCtx.translate(x, y);
                bgCtx.rotate(bgRng() * Math.PI * 2);
                bgCtx.beginPath();
                if (type === 0) bgCtx.arc(0, 0, size, 0, Math.PI * 2);
                else if (type === 1) bgCtx.arc(0, 0, size, 0, Math.PI);
                else {
                  const rw = size * 2;
                  const rh = size * 0.5;
                  bgCtx.roundRect(-rw / 2, -rh / 2, rw, rh, rh / 2);
                }
                bgDrawPath();
                bgCtx.restore();
              }
            },
            mesh: (b, pal) => {
              const count = bgState.complexity * 2;
              const baseSize = b.w * (bgState.scale / 100) * 0.8;
              for (let i = 0; i < count; i++) {
                const cx = b.x + bgRng() * b.w;
                const cy = b.y + bgRng() * b.h;
                const size = baseSize * (0.5 + bgRng());
                const cBase = pal[Math.floor(bgRng() * pal.length)];
                const grad = bgCtx.createRadialGradient(cx, cy, 0, cx, cy, size);
                grad.addColorStop(0, cBase.replace(/[\d\.]+\)$/, "1)"));
                grad.addColorStop(1, cBase.replace(/[\d\.]+\)$/, "0)"));
                bgCtx.fillStyle = grad;
                bgCtx.globalCompositeOperation = "screen";
                bgCtx.fillRect(cx - size, cy - size, size * 2, size * 2);
                bgCtx.globalCompositeOperation = "source-over";
              }
            },
            waves: (b, pal) => {
              const count = bgState.complexity * 3;
              const sp = b.h / count;
              const amp = (bgState.scale / 100) * 200;
              for (let i = 0; i <= count; i++) {
                bgApplyStyle(pal[i % pal.length]);
                bgCtx.beginPath();
                bgCtx.moveTo(b.x, b.y + b.h);
                bgCtx.lineTo(b.x, b.y + i * sp + bgRng() * 50);
                const pts = 5;
                const step = b.w / pts;
                let cx = b.x;
                let cy = b.y + i * sp;
                for (let j = 0; j < pts; j++) {
                  const nX = cx + step;
                  const nY = cy + (bgRng() > 0.5 ? 1 : -1) * amp * bgRng();
                  bgCtx.bezierCurveTo(cx + step / 2, cy, nX - step / 2, nY, nX, nY);
                  cx = nX;
                  cy = nY;
                }
                bgCtx.lineTo(b.x + b.w, b.y + b.h);
                bgDrawPath();
              }
            },
            stripes: (b, pal) => {
              const w = (bgState.scale / 100) * 100;
              const gap = w * (10 / bgState.complexity);
              for (let x = b.x; x < b.x + b.w * 2; x += w + gap) {
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.beginPath();
                bgCtx.rect(x - b.w, b.y, w, b.h);
                bgDrawPath();
              }
            },
            dots: (b, pal) => {
              const sp = (bgState.scale / 100) * 100 + 20;
              const rad = sp * (bgState.complexity / 20);
              for (let y = b.y; y < b.y + b.h; y += sp) {
                for (let x = b.x; x < b.x + b.w; x += sp) {
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.beginPath();
                  bgCtx.arc(
                    x + bgRng() * sp * 0.2,
                    y + bgRng() * sp * 0.2,
                    rad * (0.5 + bgRng()),
                    0,
                    Math.PI * 2,
                  );
                  bgDrawPath();
                }
              }
            },
            particles: (b, pal) => {
              const count = bgState.complexity * 10;
              const pts = [];
              for (let i = 0; i < count; i++)
                pts.push({
                  x: b.x + bgRng() * b.w,
                  y: b.y + bgRng() * b.h,
                  c: pal[Math.floor(bgRng() * pal.length)],
                });
              const cDist = (bgState.scale / 100) * 300;
              bgCtx.lineWidth = 2;
              for (let i = 0; i < pts.length; i++) {
                for (let j = i + 1; j < pts.length; j++) {
                  const d = Math.hypot(pts[i].x - pts[j].x, pts[i].y - pts[j].y);
                  if (d < cDist) {
                    bgCtx.strokeStyle = pts[i].c;
                    bgCtx.globalAlpha = 1 - d / cDist;
                    bgCtx.beginPath();
                    bgCtx.moveTo(pts[i].x, pts[i].y);
                    bgCtx.lineTo(pts[j].x, pts[j].y);
                    bgCtx.stroke();
                    bgCtx.globalAlpha = 1;
                  }
                }
                bgApplyStyle(pts[i].c);
                bgCtx.beginPath();
                bgCtx.arc(pts[i].x, pts[i].y, 5 + bgRng() * 10, 0, Math.PI * 2);
                bgDrawPath();
              }
            },
            triangles: (b, pal) => {
              const step = (bgState.scale / 100) * 150 + 20;
              for (let y = b.y; y < b.y + b.h; y += step) {
                for (let x = b.x; x < b.x + b.w; x += step) {
                  if (bgRng() > bgState.complexity / 10) continue;
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.beginPath();
                  bgCtx.moveTo(x + bgRng() * step, y + bgRng() * step);
                  bgCtx.lineTo(x + step + bgRng() * step, y + bgRng() * step);
                  bgCtx.lineTo(x + bgRng() * step, y + step + bgRng() * step);
                  bgCtx.closePath();
                  bgDrawPath();
                }
              }
            },
            rays: (b, pal) => {
              const count = bgState.complexity * 8;
              const rad = b.w;
              for (let i = 0; i < count; i++) {
                bgApplyStyle(pal[i % pal.length]);
                const a1 = (i / count) * Math.PI * 2;
                const a2 = ((i + (bgRng() * 0.5 + 0.5)) / count) * Math.PI * 2;
                bgCtx.beginPath();
                bgCtx.moveTo(0, 0);
                bgCtx.lineTo(Math.cos(a1) * rad, Math.sin(a1) * rad);
                bgCtx.lineTo(Math.cos(a2) * rad, Math.sin(a2) * rad);
                bgCtx.closePath();
                bgDrawPath();
              }
            },
            squares: (b, pal) => {
              const count = bgState.complexity * 5;
              for (let i = 0; i < count; i++) {
                const s = (bgState.scale / 100) * 200 * (0.2 + bgRng());
                const x = b.x + bgRng() * b.w;
                const y = b.y + bgRng() * b.h;
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.beginPath();
                bgCtx.rect(x - s / 2, y - s / 2, s, s);
                bgDrawPath();
              }
            },
            hexagons: (b, pal) => {
              const r = (bgState.scale / 100) * 50 + 10;
              const dx = r * Math.sqrt(3);
              const dy = r * 1.5;
              let row = 0;
              for (let y = b.y; y < b.y + b.h + r; y += dy) {
                let offset = row % 2 === 0 ? 0 : dx / 2;
                for (let x = b.x; x < b.x + b.w + r; x += dx) {
                  if (bgRng() > bgState.complexity / 10) continue;
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.beginPath();
                  for (let i = 0; i < 6; i++) {
                    const angle = (i * Math.PI) / 3 + Math.PI / 6;
                    const px = x + offset + r * Math.cos(angle);
                    const py = y + r * Math.sin(angle);
                    if (i === 0) bgCtx.moveTo(px, py);
                    else bgCtx.lineTo(px, py);
                  }
                  bgCtx.closePath();
                  bgDrawPath();
                }
                row++;
              }
            },
            concentric: (b, pal) => {
              const count = bgState.complexity * 2;
              const maxR = (bgState.scale / 100) * 300;
              for (let i = 0; i < count; i++) {
                const cx = b.x + bgRng() * b.w;
                const cy = b.y + bgRng() * b.h;
                const rings = 3 + Math.floor(bgRng() * 5);
                for (let r = rings; r > 0; r--) {
                  bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                  bgCtx.beginPath();
                  bgCtx.arc(cx, cy, (r / rings) * maxR, 0, Math.PI * 2);
                  bgDrawPath();
                }
              }
            },
            noise: (b, pal) => {
              const size = Math.max(5, (bgState.scale / 100) * 30);
              const den = bgState.complexity * 0.08;
              for (let y = b.y; y < b.y + b.h; y += size) {
                for (let x = b.x; x < b.x + b.w; x += size) {
                  if (bgRng() < den) {
                    bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                    bgCtx.beginPath();
                    bgCtx.rect(x, y, size, size);
                    bgDrawPath();
                  }
                }
              }
            },
            scribble: (b, pal) => {
              const count = bgState.complexity * 3;
              for (let i = 0; i < count; i++) {
                bgApplyStyle(pal[Math.floor(bgRng() * pal.length)]);
                bgCtx.beginPath();
                let cx = b.x + bgRng() * b.w;
                let cy = b.y + bgRng() * b.h;
                bgCtx.moveTo(cx, cy);
