              bgCtx.lineTo(s, -q);
              bgCtx.lineTo(s, q);
              bgCtx.lineTo(q, q);
              bgCtx.lineTo(q, s);
              bgCtx.lineTo(-q, s);
              bgCtx.lineTo(-q, q);
              bgCtx.lineTo(-s, q);
