        document.addEventListener("submit", async (e) => {
          if (e.target.id === "page-upload-art-form") {
            e.preventDefault();
            if (window.artFilesToUpload.length === 0) return showToast("Select at least one image.", "error");
            
            const btn = document.getElementById("art-submit-btn");
            const originalText = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Uploading...';
            
            const progContainer = document.getElementById("art-upload-progress-container");
            const progBar = document.getElementById("art-upload-progress");
            progContainer.classList.remove("d-none");
            progBar.style.width = "0%";
            progBar.textContent = "0%";
            
            const fd = new FormData();
            fd.append("title", document.getElementById("art-title").value);
            fd.append("type", document.getElementById("art-type").value);
            fd.append("tags", document.getElementById("art-tags").value);
            fd.append("description", document.getElementById("art-desc").value);
            fd.append("characters", document.getElementById("art-characters").value);
            fd.append("parodies", document.getElementById("art-parodies").value);
            fd.append("groups", document.getElementById("art-groups").value);
            fd.append("series", document.getElementById("art-series").value);
            fd.append("nsfw", document.getElementById("art-nsfw").checked ? "1" : "0");
            
            window.artFilesToUpload.forEach(f => fd.append("files[]", f));
            
            const xhr = new XMLHttpRequest();
            xhr.upload.onprogress = (evt) => {
              if (evt.lengthComputable) {
                const pct = Math.round((evt.loaded / evt.total) * 100);
                progBar.style.width = pct + "%";
                progBar.textContent = pct + "%";
              }
            };
            xhr.open("POST", "?action=upload_art", true);
            xhr.onload = () => {
              btn.disabled = false;
              progContainer.classList.add("d-none");
              if (xhr.status === 200) {
                try {
                  const result = JSON.parse(xhr.responseText);
                  if (result && result.status === "success") {
                    showToast("Artwork published!", "success");
                    window.artFilesToUpload = [];
                    loadView({type: 'view_art', param: result.public_id, sort: '', filter: ''});
                  } else {
                    showToast(result.message || "Upload failed.", "error");
                    btn.innerHTML = originalText;
                  }
                } catch(e) {
                  showToast("Server error.", "error");
                  btn.innerHTML = originalText;
                }
              }
            };
            xhr.send(fd);
          } else if (e.target.id === "page-edit-art-form") {
            e.preventDefault();
            const btn = e.target.querySelector('button[type="submit"]');
            const origHtml = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Saving...';
            
            const fd = new FormData();
            fd.append("public_id", document.getElementById("edit-art-public-id").value);
            fd.append("title", document.getElementById("edit-art-title").value);
            fd.append("tags", document.getElementById("edit-art-tags").value);
            fd.append("description", document.getElementById("edit-art-desc").value);
            fd.append("characters", document.getElementById("edit-art-characters").value);
            fd.append("parodies", document.getElementById("edit-art-parodies").value);
            fd.append("groups", document.getElementById("edit-art-groups").value);
            fd.append("series", document.getElementById("edit-art-series").value);
            fd.append("nsfw", document.getElementById("edit-art-nsfw").checked ? "1" : "0");

            const res = await fetch("?action=edit_art", { method: "POST", body: fd });
            const result = await res.json();
            
            btn.disabled = false;
            btn.innerHTML = origHtml;
            
            if (result && result.status === "success") {
              showToast("Artwork updated!", "success");
              loadView({type: 'view_art', param: document.getElementById("edit-art-public-id").value, sort: '', filter: ''});
            } else {
              showToast(result.message || "Failed to update", "error");
            }
          } else if (e.target.id === "edit-art-comment-form") {
            e.preventDefault();
            const id = document.getElementById("edit-art-comment-id").value;
            const content = document.getElementById("edit-art-comment-input").value;
            await fetchData("?action=edit_art_comment", {
              method: "POST",
              body: JSON.stringify({ comment_id: id, content: content }),
            });
            bootstrap.Modal.getInstance(document.getElementById("edit-art-comment-modal")).hide();
            window.refreshArtComments();
          } else if (e.target.id === "reply-art-comment-form") {
            e.preventDefault();
            if (!currentUser) return showToast("Please login", "error");
            const input = document.getElementById("reply-art-comment-input-real");
            const parentId = document.getElementById("reply-art-comment-parent-id").value;
            const replyToId = document.getElementById("reply-art-comment-reply-to-id").value;
            await fetchData("?action=add_art_comment", {
              method: "POST",
              body: JSON.stringify({
                public_id: window.activeArtPublicId,
                parent_id: parentId || null,
                reply_to_id: replyToId || null,
                content: input.value,
              }),
            });
            input.value = "";
            bootstrap.Modal.getInstance(document.getElementById("reply-art-comment-modal"))?.hide();
            window.refreshArtComments();
          } else if (e.target.id === "blog-comment-form") {
            e.preventDefault();
            if (!currentUser) return showToast("Please login", "error");
            const input = document.getElementById("blog-comment-input");
            const parentId = document.getElementById("blog-comment-parent-id").value;
            await fetchData("?action=add_blog_comment", {
              method: "POST",
              body: JSON.stringify({
                blog_id: window.activeBlogPublicId,
                parent_id: parentId || null,
                content: input.value,
              }),
            });
            input.value = "";
            document.getElementById("blog-comment-parent-id").value = "";
            input.placeholder = "Add a comment... (use @ to mention)";
            window.refreshBlogComments(true);
          }
        });
    
        let findBlogMatches = [];
        let currentBlogMatchIdx = -1;
    
        const executeBlogFind = (fromInput = true) => {
          const text = document.getElementById("blogEditorContent").value;
          const query = document.getElementById("blogFindInput").value;
          findBlogMatches = [];
          if (!query) {
            updateBlogFindUI(-1, false);
            return;
          }
    
          const regex = new RegExp(
            query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
            "gi",
          );
          let match;
          while ((match = regex.exec(text)) !== null) {
            findBlogMatches.push({
              index: match.index,
              length: match[0].length,
            });
          }
    
          if (findBlogMatches.length > 0) {
            if (fromInput) {
              if (
                currentBlogMatchIdx < 0 ||
                currentBlogMatchIdx >= findBlogMatches.length
              )
                currentBlogMatchIdx = 0;
              updateBlogFindUI(currentBlogMatchIdx, false);
            } else {
              currentBlogMatchIdx = 0;
              updateBlogFindUI(currentBlogMatchIdx, true);
            }
          } else {
            updateBlogFindUI(-1, false);
          }
        };
    
        const updateBlogFindUI = (idx, doFocusJump = true) => {
          currentBlogMatchIdx = idx;
          const counter = document.getElementById("blogFindCounter");
          if (findBlogMatches.length === 0 || idx < 0) {
            counter.innerText = "0/0";
            return;
          }
          counter.innerText = `${idx + 1}/${findBlogMatches.length}`;
    
          if (doFocusJump) {
            const ta = document.getElementById("blogEditorContent");
            const match = findBlogMatches[idx];
            ta.focus({
              preventScroll: true,
            });
            ta.setSelectionRange(match.index, match.index + match.length);
          }
        };
    
        document
          .getElementById("blogEditorFindBtn")
          ?.addEventListener("click", () => {
            if (isBlogMarkdownPreview) return;
            const p = document.getElementById("blogFindReplacePanel");
            p.classList.toggle("active");
            if (p.classList.contains("active")) {
              document.getElementById("blogFindInput").focus();
              executeBlogFind();
            } else {
              document.getElementById("blogEditorContent").focus();
            }
          });
    
        document
          .getElementById("closeBlogFindBtn")
          ?.addEventListener("click", () =>
            document
              .getElementById("blogFindReplacePanel")
              .classList.remove("active"),
          );
        document
          .getElementById("blogFindInput")
          ?.addEventListener("input", executeBlogFind);
    
        document.getElementById("blogFindNextBtn")?.addEventListener("click", () => {
          if (findBlogMatches.length === 0) return;
          let next = currentBlogMatchIdx + 1;
          if (next >= findBlogMatches.length) next = 0;
          updateBlogFindUI(next, true);
        });
    
        document.getElementById("blogFindPrevBtn")?.addEventListener("click", () => {
          if (findBlogMatches.length === 0) return;
          let next = currentBlogMatchIdx - 1;
          if (next < 0) next = findBlogMatches.length - 1;
          updateBlogFindUI(next, true);
        });
    
        document.getElementById("blogReplaceBtn")?.addEventListener("click", () => {
          if (currentBlogMatchIdx < 0 || findBlogMatches.length === 0) return;
          const rep = document.getElementById("blogReplaceInput").value;
          const ta = document.getElementById("blogEditorContent");
          const match = findBlogMatches[currentBlogMatchIdx];
          ta.value =
            ta.value.substring(0, match.index) +
            rep +
            ta.value.substring(match.index + match.length);
          ta.dispatchEvent(new Event("input"));
          executeBlogFind(false);
        });
    
        document
          .getElementById("blogReplaceAllBtn")
          ?.addEventListener("click", () => {
            const query = document.getElementById("blogFindInput").value;
            if (!query) return;
            const rep = document.getElementById("blogReplaceInput").value;
            const ta = document.getElementById("blogEditorContent");
            const regex = new RegExp(
              query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
              "gi",
            );
            ta.value = ta.value.replace(regex, rep);
            ta.dispatchEvent(new Event("input"));
            executeBlogFind(false);
          });
    
        window.openEditorNote = (note) => {
          activeEditorNote = note;
          if (note.id) fetchData("?action=log_item_view", { method: "POST", body: JSON.stringify({ item_id: note.id, item_type: "note" }) }, true);
          const isOwner =
            !note.id || note.user_id == (currentUser ? currentUser.id : null);
    
          const catSelect = document.getElementById("editorCategorySelect");
          if (catSelect) {
            catSelect.disabled = !isOwner;
            catSelect.style.opacity = isOwner ? "1" : "0.6";
            catSelect.style.cursor = isOwner ? "pointer" : "default";
            if (note.category) catSelect.value = note.category;
          }
    
          const moveBtn = document.getElementById("editorMoveProjectBtn");
          if (moveBtn) moveBtn.style.display = isOwner ? "flex" : "none";
    
          const delBtn = document.getElementById("editorDeleteBtn");
          if (delBtn) delBtn.style.display = isOwner ? "flex" : "none";
    
          const noteIdEl = document.getElementById("editorNoteId");
          if (noteIdEl) noteIdEl.value = note.id || "";
    
          const noteTypeEl = document.getElementById("editorNoteType");
          if (noteTypeEl) noteTypeEl.value = note.note_type || "note";
    
          const titleEl = document.getElementById("editorTitle");
          if (titleEl) {
            titleEl.value = note.title ? decodeHTML(note.title) : "";
            titleEl.lastServerText = titleEl.value;
          }
    
          const contentEl = document.getElementById("editorContent");
          if (contentEl) {
            contentEl.value = note.content ? decodeHTML(note.content) : "";
            contentEl.lastServerText = contentEl.value;
          }
    
          const dateEl = document.getElementById("editorDate");
          if (dateEl)
            dateEl.innerText = note.updated_at
              ? new Date(note.updated_at.replace(" ", "T") + "Z").toLocaleDateString()
              : new Date().toLocaleDateString();
    
          // History state implementation for back/forth
          if (!history.state || history.state.overlay !== "note_" + note.id) {
            history.pushState(
              {
                viewConfig: currentView,
                overlay: "note_" + note.id,
              },
              "",
              window.location.pathname,
            );
          }
    
          const savedNoteMode = localStorage.getItem('note_view_mode') || 'edit';
          setNoteViewMode(savedNoteMode);
    
          if (contentEl) noteTextHistory = [contentEl.value];
          noteHistoryIdx = 0;
    
          const starIcon = document.getElementById("editorStarIcon");
          if (starIcon) {
            starIcon.className =
              note.starred == 1 ? "bi bi-star-fill text-warning" : "bi bi-star";
          }
    
          updateEditorWordCount();
          const findPanel = document.getElementById("findReplacePanel");
          if (findPanel) findPanel.classList.remove("active");
    
          const moreMenu = document.getElementById("editorMoreMenu");
          if (moreMenu) moreMenu.classList.remove("active");
    
          const overlay = document.getElementById("editorOverlay");
          if (overlay) overlay.classList.add("active");
          if (typeof currentSong !== 'undefined' && currentSong) toggleMainMiniPlayer(true);
    
          const isCollab = currentView.filter && currentView.filter.startsWith("proj_");
          if (note.id && isCollab) {
            lastSyncContentTime = note.updated_at;
            startPresenceSync(note.id, "note");
          }
        };
    
        const saveCurrentEditorNote = async (force = false) => {
          window.isSavingItem = true;
          const statusIndicator = document.getElementById("noteSaveStatus");
          if (statusIndicator) statusIndicator.textContent = "Saving...";
          const idInput = document.getElementById("editorNoteId");
          const id = idInput.value;
          const title = document.getElementById("editorTitle").value.trim();
          const content = document.getElementById("editorContent").value;
          const category = document.getElementById("editorCategorySelect").value;
          const noteType = document.getElementById("editorNoteType").value || "note";
          const isStarred = document
            .getElementById("editorStarIcon")
            .classList.contains("bi-star-fill")
            ? 1
            : 0;
    
          if (!title && !content) return;
    
          let projId = null;
          if (currentView.filter && currentView.filter.startsWith("proj_")) {
            projId = currentView.filter.replace("proj_", "");
          }
          const res = await fetchData(
            "?action=save_note",
            {
              method: "POST",
              body: JSON.stringify({
                id: id || null,
                title,
                content,
                category,
                starred: isStarred,
                note_type: noteType,
                project_id: projId,
              }),
            },
            true,
          );
    
          if (res && res.status === "success" && res.id && !id) {
            idInput.value = res.id;
            startPresenceSync(res.id, "note");
          }
          if (statusIndicator && res && res.status === "success") {
            statusIndicator.textContent = "Saved";
    
            // Update baseline cache to prevent text duplication on echo
            const titleEl = document.getElementById("editorTitle");
            if (titleEl) titleEl.lastServerText = titleEl.value;
            const contentEl = document.getElementById("editorContent");
            if (contentEl) contentEl.lastServerText = contentEl.value;
    
            setTimeout(() => {
              if (statusIndicator.textContent === "Saved")
                statusIndicator.textContent = "";
            }, 2000);
          }
          window.isSavingItem = false;
          window.lastLocalEditTime = Date.now();
        };
    
        document.getElementById("editorPresentBtn")?.addEventListener("click", () => {
          const text = document.getElementById("editorContent").value;
          window.openPresentation(text);
        });

        let isNoteSplitView = false;

        const generateTOC = (previewElement, tocContainerId) => {
          const tocList = document.getElementById(tocContainerId);
          if (!tocList) return;
          const headings = previewElement.querySelectorAll('h1, h2, h3, h4, h5, h6');
          tocList.innerHTML = '';
          if (headings.length === 0) {
            tocList.innerHTML = '<div class="text-muted p-2 small">No headings found in the document.</div>';
            return;
          }
          headings.forEach((h, index) => {
            if (!h.id) h.id = 'heading-' + index;
            const link = document.createElement('a');
            link.href = '#' + h.id;
            link.textContent = h.textContent;
            const level = parseInt(h.tagName[1]);
            link.className = `toc-link text-truncate py-1 px-2 mb-1`;
            link.style.paddingLeft = `${(level - 1) * 15 + 10}px`;
            if (level === 1) link.classList.add('fw-bold', 'text-white');
            else link.classList.add('text-secondary');

            link.addEventListener('click', (e) => {
              e.preventDefault();
              h.scrollIntoView({ behavior: 'smooth', block: 'start' });
            });
            tocList.appendChild(link);
          });
        };

        const renderNoteMarkdown = async () => {
          const contentArea = document.getElementById("editorContent");
          const previewArea = document.getElementById("editorMarkdownPreview");
          if (typeof marked !== "undefined") {
            const rawHTML = marked.parse(contentArea.value);
            
            // SECURITY FIX: Sanitize HTML output to prevent "Re-scan Covers" Modal header injections!
            let cleanHTML = rawHTML;
            if (typeof DOMPurify !== 'undefined') {
               cleanHTML = DOMPurify.sanitize(rawHTML, { ADD_TAGS: ['iframe', 'video', 'source'], ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'src', 'controls', 'type', 'width', 'height'] });
            } else {
               cleanHTML = cleanHTML.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/class="[^"]*fixed[^"]*"/gi, '');
            }

            previewArea.innerHTML = cleanHTML;
            await parseMermaidBlocks(previewArea);
            generateTOC(previewArea, "toc-list-note");

            previewArea.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
              cb.addEventListener("change", (e) => {
                const isChecked = e.target.checked;
                const regex = new RegExp(`\\[[ xX]\\]`, "g");
                let matchCount = 0;
                let cbIndex = Array.from(previewArea.querySelectorAll('input[type="checkbox"]')).indexOf(e.target);

                contentArea.value = contentArea.value.replace(regex, (match) => {
                  if (matchCount === cbIndex) {
                    matchCount++;
                    return isChecked ? `[x]` : `[ ]`;
                  }
                  matchCount++;
                  return match;
                });
                if (isNoteSplitView) renderNoteMarkdown();
                saveCurrentEditorNote(false);
              });
            });
          } else {
            previewArea.innerHTML = '<p class="text-secondary text-center p-5">Markdown renderer is loading or unavailable.</p>';
          }
        };

        let isSyncingLeftNote = false;
        let isSyncingRightNote = false;

        document.getElementById("editorContent")?.addEventListener("scroll", (e) => {
          if (!isNoteSplitView) return;
          if (isSyncingRightNote) { isSyncingRightNote = false; return; }
          isSyncingLeftNote = true;
          const previewArea = document.getElementById("editorMarkdownPreview");
          if (!previewArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          previewArea.scrollTop = percentage * (previewArea.scrollHeight - previewArea.clientHeight);
        });

        document.getElementById("editorMarkdownPreview")?.addEventListener("scroll", (e) => {
          if (!isNoteSplitView) return;
          if (isSyncingLeftNote) { isSyncingLeftNote = false; return; }
          isSyncingRightNote = true;
          const contentArea = document.getElementById("editorContent");
          if (!contentArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          contentArea.scrollTop = percentage * (contentArea.scrollHeight - contentArea.clientHeight);
        });

        document.getElementById("editorSplitBtn")?.addEventListener("click", () => {
          isNoteSplitView = !isNoteSplitView;
          localStorage.setItem('note_split_view', isNoteSplitView);
          const container = document.getElementById("noteSplitContainer");
          const contentArea = document.getElementById("editorContent");
          const previewArea = document.getElementById("editorMarkdownPreview");
          const splitIcon = document.getElementById("editorSplitBtn").querySelector("i");
          
          isMarkdownPreview = false;
          const mdIcon = document.getElementById("editorMarkdownBtn").querySelector("i");
          if (mdIcon) mdIcon.className = "bi bi-markdown";
          const findBtn = document.getElementById("editorFindBtn");
          if (findBtn) {
            findBtn.disabled = false;
            findBtn.style.opacity = "1";
          }

          if (isNoteSplitView) {
            splitIcon.className = "bi bi-layout-split text-info";
            container.classList.add("split-active");
            contentArea.classList.remove("d-none");
            previewArea.classList.remove("d-none");
            renderNoteMarkdown();
          } else {
            splitIcon.className = "bi bi-layout-split";
            container.classList.remove("split-active");
            previewArea.classList.add("d-none");
            contentArea.classList.remove("d-none");
          }
        });

        let wordCountTimeout = null;
        const updateEditorWordCount = () => {
          const text = document.getElementById("editorContent").value;
          document.getElementById("editorCharCount").innerText =
            `${new Intl.NumberFormat().format(text.length)} chars`;

          clearTimeout(wordCountTimeout);
          wordCountTimeout = setTimeout(() => {
            let words = 0;
            if (text.length > 100000) {
              const approxWords = (text.match(/ /g) || []).length + 1;
              document.getElementById("editorWordCount").innerText = `~${new Intl.NumberFormat().format(approxWords)} words`;
              const readTime = Math.max(1, Math.ceil(approxWords / 200));
              const readTimeEl = document.getElementById("editorReadTime");
              if (readTimeEl) readTimeEl.innerHTML = `<i class="bi bi-book"></i> ~${readTime} min read`;
            } else if (text.trim()) {
              const matches = text.match(/\S+/g);
              words = matches ? matches.length : 0;
              document.getElementById("editorWordCount").innerText = `${new Intl.NumberFormat().format(words)} words`;
              const readTime = Math.max(1, Math.ceil(words / 200));
              const readTimeEl = document.getElementById("editorReadTime");
              if (readTimeEl) readTimeEl.innerHTML = `<i class="bi bi-book"></i> ${readTime} min read`;
            } else {
              document.getElementById("editorWordCount").innerText = `0 words`;
              const readTimeEl = document.getElementById("editorReadTime");
              if (readTimeEl) readTimeEl.innerHTML = `<i class="bi bi-book"></i> 0 min read`;
            }
          }, 400);
        };
    
        document.getElementById("editorCopyBtn")?.addEventListener("click", () => {
          document.getElementById("editorMoreMenu").classList.remove("active");
          const text = document.getElementById("editorContent").value;
          if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard
              .writeText(text)
              .then(() => showToast("Copied to clipboard!", "success"));
          }
        });
    
        document.addEventListener("click", (e) => {
          const btn = e.target.closest("button[data-md]");
          if (!btn) return;
          e.preventDefault();
          const md = btn.dataset.md;
          let ta;
          const container = btn.closest(".rich-input-container");
    
          if (container) {
            ta = document.getElementById(container.dataset.targetId);
          } else if (btn.closest("#blogEditorToolbar")) {
            ta = document.getElementById("blogEditorContent");
          } else if (btn.closest(".editor-toolbar")) {
            ta = document.getElementById("editorContent");
          }
          if (!ta) return;
    
          const start = ta.selectionStart;
          const end = ta.selectionEnd;
          const selectedText = ta.value.substring(start, end);
          let pre = "",
            suf = "",
            def = "";
    
          switch (md) {
            case "bold":
              pre = "**";
              suf = "**";
              def = "bold text";
              break;
            case "italic":
              pre = "*";
              suf = "*";
              def = "italic text";
              break;
            case "heading":
              pre = "### ";
              def = "Heading";
              break;
            case "strikethrough":
              pre = "~~";
              suf = "~~";
              def = "strikethrough";
              break;
            case "spoiler":
              pre = "[spoiler]";
              suf = "[/spoiler]";
              def = "spoiler text";
              break;
            case "ul":
              pre = "- ";
              def = "List item";
              break;
            case "ol":
              pre = "1. ";
              def = "List item";
              break;
            case "task":
              pre = "- [ ] ";
              def = "Task";
              break;
            case "quote":
              pre = "> ";
              def = "Quote";
              break;
            case "code":
              pre = "```\n";
              suf = "\n```";
              def = "code block";
              break;
            case "table":
              pre = "| Header | Header |\n| --- | --- |\n| Cell | Cell |";
              break;
            case "mermaid":
              pre = "```mermaid\ngraph TD;\n    A-->B;\n    A-->C;\n    B-->D;\n    C-->D;\n```\n";
              def = "";
              break;
            case "align-left":
              pre = '<div style="text-align: left;">\n';
              suf = "\n</div>";
              def = "Left aligned text";
              break;
            case "align-center":
              pre = '<div style="text-align: center;">\n';
              suf = "\n</div>";
              def = "Center aligned text";
              break;
            case "align-right":
              pre = '<div style="text-align: right;">\n';
              suf = "\n</div>";
              def = "Right aligned text";
              break;
            case "link":
              pre = "[";
              suf = "](url)";
              def = "link text";
              break;
            case "image":
              const imgUrl = prompt(
                "Enter image URL:",
                "https://example.com/image.jpg",
              );
              if (imgUrl) {
                const imgWidth = prompt(
                  "Enter width (e.g. 100%, 300px, auto):",
                  "100%",
                );
                const imgHeight = prompt("Enter height (e.g. auto, 300px):", "auto");
                pre = `<img src="${imgUrl}" width="${imgWidth || "100%"}" height="${imgHeight || "auto"}" alt="`;
                suf = '">';
                def = "image description";
              } else {
                return; // Cancelled
              }
              break;
            case "video":
              const vidUrl = prompt(
                "Enter Video or YouTube URL:",
                "https://www.youtube.com/watch?v=...",
              );
              if (vidUrl) {
                const ytMatch = vidUrl.match(
                  /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i,
                );
                if (ytMatch && ytMatch[1]) {
                  pre = `\n<iframe src="https://www.youtube.com/embed/${ytMatch[1]}" title="YouTube video player" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>\n`;
                } else {
                  pre = `\n<video src="${vidUrl}" controls style="background: #000;"></video>\n`;
                }
                suf = "";
                def = "";
              } else {
                return; // Cancelled
              }
              break;
          }
    
          const insertText = selectedText || def;
          const finalInsert = md === "table" ? pre : pre + insertText + suf;
    
          ta.value =
            ta.value.substring(0, start) + finalInsert + ta.value.substring(end);
          ta.focus();
    
          if (md === "table") {
            ta.setSelectionRange(start + 2, start + 8);
          } else if (selectedText) {
            ta.setSelectionRange(start, start + finalInsert.length);
          } else {
            ta.setSelectionRange(start + pre.length, start + pre.length + def.length);
          }
    
          ta.dispatchEvent(new Event("input"));
          ta.style.height = "";
          ta.style.height = ta.scrollHeight + "px";
        });
    
        let taskSaveTimeout = null;
        let isTaskSplitView = false;
        let isTaskMarkdownPreview = false;
        window.taskSortable = null;

        const updateTaskEditorWordCount = () => {
          const total = window.currentTaskItems ? window.currentTaskItems.length : 0;
          const completed = window.currentTaskItems ? window.currentTaskItems.filter(i => i.completed).length : 0;
          const pct = total > 0 ? Math.round((completed / total) * 100) : 0;

          const totalEl = document.getElementById("taskEditorTotalCount");
          const compEl = document.getElementById("taskEditorCompletedCount");
          const badgeEl = document.getElementById("taskEditorProgressBadge");

          if (totalEl) totalEl.innerText = `${total} ${total === 1 ? 'item' : 'items'}`;
          if (compEl) compEl.innerText = `${completed} completed`;
          if (badgeEl) badgeEl.innerHTML = `<i class="bi bi-check2-circle"></i> ${pct}% Done`;
        };

        const setTaskViewMode = (mode) => {
          const container = document.getElementById("taskSplitContainer");
          if (!container) return;
          
          if (mode === 'split' && window.innerWidth < 768) {
            mode = 'edit';
          }

          localStorage.setItem('task_view_mode', mode);

          const idInput = document.getElementById("taskEditorId")?.value;
          if (idInput) window.noteViewerStates[idInput] = (mode === 'preview') ? "markdown" : "editor";

          container.classList.remove('view-mode-edit', 'view-mode-split', 'view-mode-preview');
          container.classList.add(`view-mode-${mode}`);
          
          ['taskEditorModeEditBtn', 'taskEditorSplitBtn', 'taskEditorMarkdownBtn'].forEach(id => {
            const btn = document.getElementById(id);
            if (btn) btn.classList.remove('active');
          });
          
          let activeBtnId = 'taskEditorModeEditBtn';
          if (mode === 'split') activeBtnId = 'taskEditorSplitBtn';
          if (mode === 'preview') activeBtnId = 'taskEditorMarkdownBtn';
          
          const activeBtn = document.getElementById(activeBtnId);
          if (activeBtn) activeBtn.classList.add('active');
          
          const findBtn = document.getElementById("taskEditorFindBtn");
          const addToolbarBtn = document.getElementById("addTaskItemBtnToolbar");

          const contentArea = document.getElementById("taskEditorContentArea");
          const previewArea = document.getElementById("taskMarkdownPreview");
          const resizer = document.getElementById("taskResizer");

          if (mode === 'edit') {
            isTaskSplitView = false;
            isTaskMarkdownPreview = false;
            if (contentArea) {
              contentArea.style.width = "100%";
              contentArea.style.flex = "1 1 100%";
            }
            if (resizer) resizer.style.display = "none";
            if (previewArea) previewArea.style.display = "none";
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
            if (addToolbarBtn) { addToolbarBtn.style.display = "inline-flex"; }
            if (window.taskSortable) window.taskSortable.option("disabled", false);
          } else if (mode === 'split') {
            isTaskSplitView = true;
            isTaskMarkdownPreview = false;
            if (contentArea) {
              contentArea.style.width = "50%";
              contentArea.style.flex = "none";
            }
            if (resizer) resizer.style.display = "block";
            if (previewArea) {
              previewArea.style.display = "block";
              previewArea.style.width = "";
              previewArea.style.flex = "1 1 0%";
            }
            window.renderTaskMarkdown(false);
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
            if (addToolbarBtn) { addToolbarBtn.style.display = "inline-flex"; }
            if (window.taskSortable) window.taskSortable.option("disabled", false);
          } else if (mode === 'preview') {
            isTaskSplitView = false;
            isTaskMarkdownPreview = true;
            document.getElementById("taskFindReplacePanel")?.classList.remove("active");
            if (contentArea) contentArea.style.display = "none";
            if (resizer) resizer.style.display = "none";
            if (previewArea) {
              previewArea.style.display = "block";
              previewArea.style.width = "100%";
              previewArea.style.flex = "1 1 100%";
            }
            if (findBtn) { findBtn.disabled = true; findBtn.style.opacity = "0.5"; }
            if (addToolbarBtn) { addToolbarBtn.style.display = "none"; }
            if (window.taskSortable) window.taskSortable.option("disabled", true);
            window.renderTaskMarkdown(true); // Pure read-only non-interactive view
          }
        };

        document.getElementById("taskEditorModeEditBtn")?.addEventListener("click", () => setTaskViewMode('edit'));
        document.getElementById("taskEditorSplitBtn")?.addEventListener("click", () => setTaskViewMode('split'));
        document.getElementById("taskEditorMarkdownBtn")?.addEventListener("click", () => setTaskViewMode('preview'));

        window.openTaskEditor = (task) => {
          if (task.id) fetchData("?action=log_item_view", { method: "POST", body: JSON.stringify({ item_id: task.id, item_type: "task" }) }, true);
          const isOwner =
            !task.id || task.user_id == (currentUser ? currentUser.id : null);
    
          const catSelect = document.getElementById("taskEditorCategorySelect");
          if (catSelect) {
            catSelect.disabled = !isOwner;
            catSelect.style.opacity = isOwner ? "1" : "0.6";
            catSelect.style.cursor = isOwner ? "pointer" : "default";
            if (task.category) catSelect.value = task.category;
          }
    
          const moveBtn = document.getElementById("taskMoveProjectBtn");
          if (moveBtn) moveBtn.style.display = isOwner ? "flex" : "none";
    
          const delBtn = document.getElementById("taskEditorDeleteBtn");
          if (delBtn) delBtn.style.display = isOwner ? "flex" : "none";
    
          if (!history.state || history.state.overlay !== "task_" + task.id) {
            history.pushState(
              {
                viewConfig: currentView,
                overlay: "task_" + task.id,
              },
              "",
              window.location.pathname,
            );
          }
    
          const idEl = document.getElementById("taskEditorId");
          if (idEl) idEl.value = task.id || "";
    
          const titleEl = document.getElementById("taskEditorTitle");
          if (titleEl) {
            titleEl.value = task.title ? decodeHTML(task.title) : "";
            titleEl.lastServerText = titleEl.value;
          }
    
          const dateEl = document.getElementById("taskEditorDate");
          if (dateEl)
            dateEl.innerText = task.updated_at
              ? new Date(task.updated_at.replace(" ", "T") + "Z").toLocaleDateString()
              : new Date().toLocaleDateString();
    
          const starIcon = document.getElementById("taskEditorStarIcon");
          if (starIcon)
            starIcon.className =
              task.starred == 1 ? "bi bi-star-fill text-warning" : "bi bi-star";
    
          let items = [];
          try {
            items = task.items ? JSON.parse(task.items) : [];
          } catch (e) {}
          window.currentTaskItems = items;
    
          window.renderTaskItems();

          const savedTaskMode = localStorage.getItem('task_view_mode') || 'edit';
          setTaskViewMode(savedTaskMode);
    
          const findPanel = document.getElementById("taskFindReplacePanel");
          if (findPanel) findPanel.classList.remove("active");
    
          const moreMenu = document.getElementById("taskEditorMoreMenu");
          if (moreMenu) moreMenu.classList.remove("active");
    
          const overlay = document.getElementById("taskEditorOverlay");
          if (overlay) overlay.classList.add("active");
          if (typeof currentSong !== 'undefined' && currentSong) toggleMainMiniPlayer(true);
    
          // Re-calculate accurate heights once overlay is rendered and visible in DOM
          requestAnimationFrame(() => {
            document.querySelectorAll("#taskItemsContainer .task-item-input").forEach((input) => {
              input.style.height = "0px";
              input.style.height = Math.max(24, input.scrollHeight) + "px";
            });
          });

          const isCollab = currentView.filter && currentView.filter.startsWith("proj_");
          if (task.id && isCollab) {
            lastSyncContentTime = task.updated_at;
            startPresenceSync(task.id, "task");
          }
        };
    
        window.renderTaskMarkdown = async (readOnly = false) => {
          const previewArea = document.getElementById("taskMarkdownPreview");
          if (!previewArea) return;
          const itemsList = window.currentTaskItems || [];
          let markdownText = itemsList.map(t => (t.completed ? "- [x] " : "- [ ] ") + t.text).join('\n');
          
          if (typeof marked !== "undefined") {
            marked.use({ gfm: true });
            const rawHTML = marked.parse(markdownText || "*(No tasks added yet)*");

            let cleanHTML = rawHTML;
            if (typeof DOMPurify !== 'undefined') {
              cleanHTML = DOMPurify.sanitize(rawHTML, { ADD_TAGS: ['iframe', 'video', 'source'], ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'src', 'controls', 'type', 'width', 'height'] });
            } else {
              cleanHTML = cleanHTML.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/class="[^"]*fixed[^"]*"/gi, '');
            }

            previewArea.innerHTML = cleanHTML;
            await parseMermaidBlocks(previewArea);
            generateTOC(previewArea, "toc-list-task");

            previewArea.querySelectorAll('input[type="checkbox"]').forEach((cb) => {
              if (readOnly) {
                cb.setAttribute("disabled", "true");
                cb.style.pointerEvents = "none";
                cb.style.cursor = "default";
              } else {
                cb.removeAttribute("disabled");
                cb.style.pointerEvents = "auto";
                cb.style.cursor = "pointer";
                cb.addEventListener("change", (e) => {
                  const isChecked = e.target.checked;
                  let cbIndex = Array.from(previewArea.querySelectorAll('input[type="checkbox"]')).indexOf(e.target);
                  if (window.currentTaskItems[cbIndex]) {
                    window.currentTaskItems[cbIndex].completed = isChecked;
                    window.renderTaskItems();
                    window.saveCurrentTask(false);
                  }
                });
              }
            });
          } else {
            previewArea.innerHTML = '<p class="text-secondary text-center p-5">Markdown renderer is loading or unavailable.</p>';
          }
        };

        let isSyncingLeftTask = false;
        let isSyncingRightTask = false;

        document.getElementById("taskItemsContainer")?.addEventListener("scroll", (e) => {
          if (!isTaskSplitView) return;
          if (isSyncingRightTask) { isSyncingRightTask = false; return; }
          isSyncingLeftTask = true;
          const previewArea = document.getElementById("taskMarkdownPreview");
          if (!previewArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          previewArea.scrollTop = percentage * (previewArea.scrollHeight - previewArea.clientHeight);
        });

        document.getElementById("taskMarkdownPreview")?.addEventListener("scroll", (e) => {
          if (!isTaskSplitView) return;
          if (isSyncingLeftTask) { isSyncingLeftTask = false; return; }
          isSyncingRightTask = true;
          const contentArea = document.getElementById("taskItemsContainer");
          if (!contentArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          contentArea.scrollTop = percentage * (contentArea.scrollHeight - contentArea.clientHeight);
        });

        window.renderTaskItems = () => {
          const container = document.getElementById("taskItemsContainer");
          if (!container) return;
          const autoResizeTaskInput = (el) => {
            if (!el) return;
            el.style.height = "0px";
            el.style.height = Math.max(24, el.scrollHeight) + "px";
          };
    
          container.innerHTML = (window.currentTaskItems || [])
            .map(
              (item, idx) => `
                <div class="task-item-row" data-idx="${idx}">
                  <i class="bi bi-grip-vertical text-secondary task-item-drag-handle" title="Drag to reorder" style="cursor: grab; font-size: 1.1rem; user-select: none;"></i>
                  <input type="checkbox" class="task-item-checkbox" data-idx="${idx}" ${item.completed ? "checked" : ""}>
                  <textarea class="task-item-input ${item.completed ? "completed" : ""}" data-idx="${idx}" placeholder="Task description..." rows="1" style="resize: none; overflow: hidden; height: 24px; padding: 2px 0; line-height: 1.4;">${escapeHTML(item.text)}</textarea>
                  <button class="task-item-del" data-idx="${idx}"><i class="bi bi-x-lg"></i></button>
                </div>
              `,
            )
            .join("");

          updateTaskEditorWordCount();

          // Initialize / reattach SortableJS for drag-and-drop task sorting
          if (typeof Sortable !== "undefined") {
            if (window.taskSortable) {
              window.taskSortable.destroy();
              window.taskSortable = null;
            }
            window.taskSortable = Sortable.create(container, {
              animation: 150,
              handle: ".task-item-drag-handle",
              ghostClass: "ghost",
              onEnd: () => {
                window.lastLocalEditTime = Date.now();
                const reorderedItems = [];
                container.querySelectorAll(".task-item-row").forEach((row) => {
                  const idx = parseInt(row.dataset.idx);
                  if (window.currentTaskItems[idx]) {
                    reorderedItems.push(window.currentTaskItems[idx]);
                  }
                });
                window.currentTaskItems = reorderedItems;
                window.renderTaskItems();
                if (isTaskSplitView) {
                  window.renderTaskMarkdown(false);
                }
                window.saveCurrentTask(false);
              },
            });
          }
    
          container.querySelectorAll(".task-item-input").forEach((input) => {
            autoResizeTaskInput(input);
            input.addEventListener("input", (e) => {
              window.lastLocalEditTime = Date.now();
              autoResizeTaskInput(e.target);
              window.currentTaskItems[e.target.dataset.idx].text = e.target.value;
              updateTaskEditorWordCount();
              if (isTaskSplitView) {
                window.renderTaskMarkdown(false);
              }
              if (
                document
                  .getElementById("taskFindReplacePanel")
                  .classList.contains("active")
              )
                executeTaskFind();
              clearTimeout(taskSaveTimeout);
              taskSaveTimeout = setTimeout(() => window.saveCurrentTask(false), 300);
            });
            input.addEventListener("keydown", (e) => {
              window.lastLocalEditTime = Date.now();
              if (e.key === "Enter") {
                e.preventDefault();
                const idx = parseInt(e.target.dataset.idx);
                window.currentTaskItems.splice(idx + 1, 0, {
                  text: "",
                  completed: false,
                });
                window.renderTaskItems();
                const inputs = document.querySelectorAll(".task-item-input");
                if (inputs.length > idx + 1) inputs[idx + 1].focus();
                window.saveCurrentTask(false);
              } else if (e.key === "Backspace" && e.target.value === "") {
                e.preventDefault();
                const idx = parseInt(e.target.dataset.idx);
                if (idx > 0) {
                  window.currentTaskItems.splice(idx, 1);
                  window.renderTaskItems();
                  const inputs = document.querySelectorAll(".task-item-input");
                  if (inputs.length > idx - 1) {
                    inputs[idx - 1].focus();
                    const val = inputs[idx - 1].value;
                    inputs[idx - 1].value = "";
                    inputs[idx - 1].value = val;
                  }
                  window.saveCurrentTask(false);
                }
              }
            });
          });
    
          container.querySelectorAll(".task-item-checkbox").forEach((chk) => {
            chk.addEventListener("change", (e) => {
              window.lastLocalEditTime = Date.now();
              const idx = e.target.dataset.idx;
              const isChecked = e.target.checked;
              window.currentTaskItems[idx].completed = isChecked;
    
              const row = e.target.closest(".task-item-row");
              if (row) {
                const inputField = row.querySelector(".task-item-input");
                if (inputField) {
                  if (isChecked) inputField.classList.add("completed");
                  else inputField.classList.remove("completed");
                }
              }
              updateTaskEditorWordCount();
              if (isTaskSplitView) {
                window.renderTaskMarkdown(false);
              }
              window.saveCurrentTask(false);
            });
          });
    
          container.querySelectorAll(".task-item-del").forEach((btn) => {
            btn.addEventListener("click", (e) => {
              window.lastLocalEditTime = Date.now();
              window.currentTaskItems.splice(e.currentTarget.dataset.idx, 1);
              window.renderTaskItems();
              if (isTaskSplitView) window.renderTaskMarkdown(false);
              window.saveCurrentTask(false);
            });
          });
        };
    
        window.saveCurrentTask = async (force = false) => {
          window.isSavingItem = true;
          const statusIndicator = document.getElementById("taskSaveStatus");
          if (statusIndicator) statusIndicator.textContent = "Saving...";
          const idInput = document.getElementById("taskEditorId");
          const id = idInput.value;
          const title = document.getElementById("taskEditorTitle").value.trim();
          const category = document.getElementById("taskEditorCategorySelect").value;
          const isStarred = document
            .getElementById("taskEditorStarIcon")
            .classList.contains("bi-star-fill")
            ? 1
            : 0;
          const items = JSON.stringify(window.currentTaskItems);
    
          if (!title && window.currentTaskItems.length === 0) return;
    
          let projId = null;
          if (currentView.filter && currentView.filter.startsWith("proj_")) {
            projId = currentView.filter.replace("proj_", "");
          }
          const res = await fetchData(
            "?action=save_task",
            {
              method: "POST",
              body: JSON.stringify({
                id: id || null,
                title,
                items,
                category,
                starred: isStarred,
                project_id: projId,
              }),
            },
            true,
          );
    
          if (res && res.status === "success" && res.id && !id) {
            idInput.value = res.id;
            startPresenceSync(res.id, "task");
          }
          if (statusIndicator && res && res.status === "success") {
            statusIndicator.textContent = "Saved";
    
            const titleEl = document.getElementById("taskEditorTitle");
            if (titleEl) titleEl.lastServerText = titleEl.value;
    
            setTimeout(() => {
              if (statusIndicator.textContent === "Saved")
                statusIndicator.textContent = "";
            }, 2000);
          }
          window.isSavingItem = false;
          window.lastLocalEditTime = Date.now();
        };
    
        const handleAddTaskItem = () => {
          window.lastLocalEditTime = Date.now();
          if (isTaskMarkdownPreview) {
            setTaskViewMode('edit');
          }
          window.currentTaskItems.push({
            text: "",
            completed: false,
          });
          window.renderTaskItems();
          if (isTaskSplitView) window.renderTaskMarkdown(false);
          const inputs = document.querySelectorAll(".task-item-input");
          if (inputs.length > 0) inputs[inputs.length - 1].focus();
        };

        document.getElementById("addTaskItemBtn")?.addEventListener("click", handleAddTaskItem);
        document.getElementById("addTaskItemBtnToolbar")?.addEventListener("click", handleAddTaskItem);
    
        document.getElementById("taskEditorTitle")?.addEventListener("input", () => {
          window.lastLocalEditTime = Date.now();
          clearTimeout(taskSaveTimeout);
          taskSaveTimeout = setTimeout(() => window.saveCurrentTask(false), 300);
        });
    
        document
          .getElementById("taskEditorCategorySelect")
          ?.addEventListener("change", () => window.saveCurrentTask(false));
    
        document
          .getElementById("closeTaskEditorBtn")
          ?.addEventListener("click", async () => {
            if (taskPipWin) {
              taskPipWin.close();
              taskPipWin = null;
            }
            await window.saveCurrentTask(true);
            stopPresenceSync();
            document
              .getElementById("taskFindReplacePanel")
              ?.classList.remove("active");
            document.getElementById("taskEditorOverlay").classList.remove("active");
            toggleMainMiniPlayer(false);
            if (currentView.type === "get_tasks") loadView(currentView);
          });
    
        document
          .getElementById("taskEditorStarBtn")
          ?.addEventListener("click", () => {
            const starIcon = document.getElementById("taskEditorStarIcon");
            starIcon.className = starIcon.classList.contains("bi-star-fill")
              ? "bi bi-star"
              : "bi bi-star-fill text-warning";
            window.saveCurrentTask(true);
          });
    
        document
          .getElementById("taskEditorMoreBtn")
          ?.addEventListener("click", (e) => {
            e.stopPropagation();
            document.getElementById("taskEditorMoreMenu").classList.toggle("active");
          });
    
        document
          .getElementById("taskEditorForceSaveBtn")
          ?.addEventListener("click", async () => {
            await window.saveCurrentTask(true);
            showToast("Tasks saved!", "success");
            document.getElementById("taskEditorMoreMenu").classList.remove("active");
          });
    
        document
          .getElementById("taskEditorCopyBtn")
          ?.addEventListener("click", () => {
            document.getElementById("taskEditorMoreMenu").classList.remove("active");
            const text = window.currentTaskItems
              .map((t) => (t.completed ? "[x] " : "[ ] ") + t.text)
              .join("\n");
            if (navigator.clipboard && window.isSecureContext) {
              navigator.clipboard
                .writeText(text)
                .then(() => showToast("Copied to clipboard!", "success"));
            }
          });
    
        document
          .getElementById("taskEditorDeleteBtn")
          ?.addEventListener("click", async () => {
            if (taskPipWin) {
              taskPipWin.close();
              taskPipWin = null;
            }
            document.getElementById("taskEditorMoreMenu").classList.remove("active");
            const id = document.getElementById("taskEditorId").value;
            if (!id) {
              document.getElementById("taskEditorOverlay").classList.remove("active");
              showToast("Discarded unsaved task list.", "info");
              return;
            }
            if (confirm("Delete this task list?")) {
              await fetchData("?action=delete_task", {
                method: "POST",
                body: JSON.stringify({
                  id,
                }),
              });
              document.getElementById("taskEditorOverlay").classList.remove("active");
              if (currentView.type === "get_tasks") loadView(currentView);
            }
          });
    
        let noteMarkdownTimer = null;
        document.getElementById("editorContent").addEventListener("input", (e) => {
          window.lastLocalEditTime = Date.now();
          clearTimeout(noteSaveTimeout);
          clearTimeout(noteMarkdownTimer);
          if (isNoteSplitView) noteMarkdownTimer = setTimeout(renderNoteMarkdown, 300);
          clearTimeout(noteHistoryTimeout);
          updateEditorWordCount();
          if (
            document.getElementById("findReplacePanel").classList.contains("active")
          )
            executeNoteFind();
          noteSaveTimeout = setTimeout(() => saveCurrentEditorNote(false), 300);
          noteHistoryTimeout = setTimeout(() => {
            if (noteTextHistory[noteHistoryIdx] === e.target.value) return;
            noteTextHistory = noteTextHistory.slice(0, noteHistoryIdx + 1);
            noteTextHistory.push(e.target.value);
    
            // ADVANCED MEMORY MGMT: Cap history dynamically to prevent RAM crashes on massive documents
            const maxHistory = e.target.value.length > 200000 ? 5 : 50;
            if (noteTextHistory.length > maxHistory) noteTextHistory.shift();
            else noteHistoryIdx++;
          }, 600);
        });
    
        document.getElementById("editorTitle").addEventListener("input", () => {
          window.lastLocalEditTime = Date.now();
          clearTimeout(noteSaveTimeout);
          noteSaveTimeout = setTimeout(() => saveCurrentEditorNote(false), 300);
        });
    
        document
          .getElementById("editorCategorySelect")
          .addEventListener("change", () => saveCurrentEditorNote(false));
    
        document
          .getElementById("closeEditorBtn")
          .addEventListener("click", async () => {
            if (notePipWin) {
              notePipWin.close();
              notePipWin = null;
            }
            await saveCurrentEditorNote(true);
            stopPresenceSync();
            document.getElementById("editorOverlay").classList.remove("active");
            toggleMainMiniPlayer(false);
            activeEditorNote = null;
            if (currentView.type === "get_notes") loadView(currentView);
          });
    
        let blogSaveTimeout = null;
        let blogHistoryTimeout = null;
        let blogTextHistory = [];
        let blogHistoryIdx = -1;
        let isBlogMarkdownPreview = false;
    
        window.openBlogEditor = (blog) => {
          if (blog.public_id) fetchData("?action=log_item_view", { method: "POST", body: JSON.stringify({ item_id: blog.public_id, item_type: "blog" }) }, true);
          const isOwner =
            !blog.id || blog.user_id == (currentUser ? currentUser.id : null);
    
          const catSelect = document.getElementById("blogEditorCategorySelect");
          if (catSelect) {
            catSelect.disabled = !isOwner;
            catSelect.style.opacity = isOwner ? "1" : "0.6";
            catSelect.style.cursor = isOwner ? "pointer" : "default";
            if (blog.category) catSelect.value = blog.category;
          }
    
          const moveBtn = document.getElementById("blogEditorMoveProjectBtn");
          if (moveBtn) moveBtn.style.display = isOwner ? "flex" : "none";
    
          const delBtn = document.getElementById("blogEditorDeleteBtn");
          if (delBtn) delBtn.style.display = isOwner ? "flex" : "none";
    
          const titleEl = document.getElementById("blogEditorTitle");
          const contentEl = document.getElementById("blogEditorContent");
          const idEl = document.getElementById("blogEditorId");
          const pubIdEl = document.getElementById("blogEditorPublicId");
          const statusSelect = document.getElementById("blogEditorStatusSelect");
          const dateEl = document.getElementById("blogEditorDate");
    
          idEl.value = blog.id || "";
          if (pubIdEl) pubIdEl.value = blog.public_id || "";
          titleEl.value = blog.title ? decodeHTML(blog.title) : "";
          titleEl.lastServerText = titleEl.value;
          contentEl.value = blog.content ? decodeHTML(blog.content) : "";
          contentEl.lastServerText = contentEl.value;
          statusSelect.value = blog.status || "private";
          dateEl.innerText = blog.updated_at
            ? new Date(blog.updated_at.replace(" ", "T") + "Z").toLocaleDateString()
            : new Date().toLocaleDateString();
    
          const savedBlogMode = localStorage.getItem('blog_view_mode') || 'edit';
          setBlogViewMode(savedBlogMode);
    
          if (contentEl) blogTextHistory = [contentEl.value];
          blogHistoryIdx = 0;
          updateBlogEditorWordCount();
    
          document.getElementById("blogEditorOverlay").classList.add("active");
          if (typeof currentSong !== 'undefined' && currentSong) toggleMainMiniPlayer(true);
    
          const isCollab = currentView.filter && currentView.filter.startsWith("proj_");
          if (blog.id && isCollab) {
            lastSyncContentTime = blog.updated_at;
            startPresenceSync(blog.id, "blog");
          }
        };
    
        const saveCurrentBlog = async (force = false) => {
          window.isSavingItem = true;
          const statusIndicator = document.getElementById("blogSaveStatus");
          if (statusIndicator) statusIndicator.textContent = "Saving...";
          const idInput = document.getElementById("blogEditorId");
          const id = idInput.value;
          const title = document.getElementById("blogEditorTitle").value.trim();
          const content = document.getElementById("blogEditorContent").value;
          const status = document.getElementById("blogEditorStatusSelect").value;
          const category = document.getElementById("blogEditorCategorySelect").value;
    
          if (!title && !content) return;
    
          let projId = null;
          if (currentView.filter && currentView.filter.startsWith("proj_")) {
            projId = currentView.filter.replace("proj_", "");
          }
    
          const res = await fetchData(
            "?action=save_blog",
            {
              method: "POST",
              body: JSON.stringify({
                id: id || null,
                title,
                content,
                status,
                category,
                project_id: projId,
              }),
            },
            true,
          );
    
          if (res && res.status === "success" && res.id && !id) {
            idInput.value = res.id;
            startPresenceSync(res.id, "blog");
          }
          if (res && res.status === "success" && res.public_id) {
            const pubIdEl = document.getElementById("blogEditorPublicId");
            if (pubIdEl) pubIdEl.value = res.public_id;
          }
          if (statusIndicator && res && res.status === "success") {
            statusIndicator.textContent = "Saved";
    
            const titleEl = document.getElementById("blogEditorTitle");
            if (titleEl) titleEl.lastServerText = titleEl.value;
            const contentEl = document.getElementById("blogEditorContent");
            if (contentEl) contentEl.lastServerText = contentEl.value;
    
            setTimeout(() => {
              if (statusIndicator.textContent === "Saved")
                statusIndicator.textContent = "";
            }, 2000);
          }
          window.isSavingItem = false;
          window.lastLocalEditTime = Date.now();
        };
    
        document
          .getElementById("blogEditorViewBtn")
          ?.addEventListener("click", async () => {
            await saveCurrentBlog(true);
            const pubId = document.getElementById("blogEditorPublicId")?.value;
            if (pubId) {
              if (blogPipWin) {
                blogPipWin.close();
                blogPipWin = null;
              }
              document.getElementById("blogEditorOverlay").classList.remove("active");
              loadView({
                type: "view_blog",
                param: pubId,
                sort: "",
                filter: "",
              });
            } else {
              showToast("Save the blog first before viewing.", "error");
            }
          });
    
        document
          .getElementById("closeBlogEditorBtn")
          ?.addEventListener("click", async () => {
            if (blogPipWin) {
              blogPipWin.close();
              blogPipWin = null;
            }
            await saveCurrentBlog(true);
            stopPresenceSync();
            document.getElementById("blogEditorOverlay").classList.remove("active");
            toggleMainMiniPlayer(false);
            if (currentView.type === "get_blogs" || currentView.type === "view_blog")
              loadView(currentView);
          });
    
        document
          .getElementById("blogEditorForceSaveBtn")
          ?.addEventListener("click", async () => {
            await saveCurrentBlog(true);
            showToast("Blog saved!", "success");
          });
    
       let blogMarkdownTimer = null;
        document
          .getElementById("blogEditorContent")
          ?.addEventListener("input", (e) => {
            window.lastLocalEditTime = Date.now();
            clearTimeout(blogSaveTimeout);
            clearTimeout(blogMarkdownTimer);
            if (isBlogSplitView) blogMarkdownTimer = setTimeout(renderBlogMarkdown, 300);
            clearTimeout(blogHistoryTimeout);
            updateBlogEditorWordCount();
            blogSaveTimeout = setTimeout(() => saveCurrentBlog(false), 300);
            blogHistoryTimeout = setTimeout(() => {
              if (blogTextHistory[blogHistoryIdx] === e.target.value) return;
              blogTextHistory = blogTextHistory.slice(0, blogHistoryIdx + 1);
              blogTextHistory.push(e.target.value);
              const maxHistory = e.target.value.length > 200000 ? 5 : 50;
              if (blogTextHistory.length > maxHistory) blogTextHistory.shift();
              else blogHistoryIdx++;
            }, 600);
          });
    
        document
          .getElementById("blogEditorCopyBtn")
          ?.addEventListener("click", () => {
            const text = document.getElementById("blogEditorContent").value;
            if (navigator.clipboard && window.isSecureContext) {
              navigator.clipboard
                .writeText(text)
                .then(() => showToast("Copied to clipboard!", "success"));
            }
          });
    
        const performBlogUndo = () => {
          const ta = document.getElementById("blogEditorContent");
          if (!ta) return;
          if (blogHistoryIdx > 0) {
            blogHistoryIdx--;
            ta.value = blogTextHistory[blogHistoryIdx];
            updateBlogEditorWordCount();
            saveCurrentBlog(false);
          } else {
            ta.focus();
            try { document.execCommand("undo"); } catch (e) {}
          }
        };

        const performBlogRedo = () => {
          const ta = document.getElementById("blogEditorContent");
          if (!ta) return;
          if (blogHistoryIdx < blogTextHistory.length - 1) {
            blogHistoryIdx++;
            ta.value = blogTextHistory[blogHistoryIdx];
            updateBlogEditorWordCount();
            saveCurrentBlog(false);
          } else {
            ta.focus();
            try { document.execCommand("redo"); } catch (e) {}
          }
        };

        document.getElementById("blogEditorUndoBtn")?.addEventListener("click", performBlogUndo);
        document.getElementById("blogEditorUndoToolbarBtn")?.addEventListener("click", performBlogUndo);
        document.getElementById("blogEditorRedoBtn")?.addEventListener("click", performBlogRedo);
        document.getElementById("blogEditorRedoToolbarBtn")?.addEventListener("click", performBlogRedo);
    
        document.getElementById("blogEditorTitle")?.addEventListener("input", () => {
          window.lastLocalEditTime = Date.now();
          clearTimeout(blogSaveTimeout);
          blogSaveTimeout = setTimeout(() => saveCurrentBlog(false), 300);
        });
    
        document
          .getElementById("blogEditorStatusSelect")
          ?.addEventListener("change", () => saveCurrentBlog(false));
        document
          .getElementById("blogEditorCategorySelect")
          ?.addEventListener("change", () => saveCurrentBlog(false));
    
        document
          .getElementById("blogEditorDeleteBtn")
          ?.addEventListener("click", async () => {
            if (blogPipWin) {
              blogPipWin.close();
              blogPipWin = null;
            }
            const id = document.getElementById("blogEditorId").value;
            if (!id) {
              document.getElementById("blogEditorOverlay").classList.remove("active");
              return;
            }
            if (confirm("Delete this blog permanently?")) {
              await fetchData("?action=delete_blog", {
                method: "POST",
                body: JSON.stringify({
                  id,
                }),
              });
              document.getElementById("blogEditorOverlay").classList.remove("active");
              if (
                currentView.type === "get_blogs" ||
                currentView.type === "view_blog"
              ) {
                loadView({
                  type: "get_blogs",
                  param: "",
                  sort: "newest",
                  filter: "",
                });
              }
            }
          });
    
        document.getElementById("blogEditorPresentBtn")?.addEventListener("click", () => {
          const text = document.getElementById("blogEditorContent").value;
          window.openPresentation(text);
        });

        let isBlogSplitView = false;

        const renderBlogMarkdown = async () => {
          const contentArea = document.getElementById("blogEditorContent");
          const previewArea = document.getElementById("blogEditorMarkdownPreview");
          if (typeof marked !== "undefined") {
            const rawHTML = marked.parse(contentArea.value);
            
            // SECURITY FIX: Sanitize HTML output to prevent "Re-scan Covers" Modal header injections!
            let cleanHTML = rawHTML;
            if (typeof DOMPurify !== 'undefined') {
               cleanHTML = DOMPurify.sanitize(rawHTML, { ADD_TAGS: ['iframe', 'video', 'source'], ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'src', 'controls', 'type', 'width', 'height'] });
            } else {
               cleanHTML = cleanHTML.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/class="[^"]*fixed[^"]*"/gi, '');
            }

            previewArea.innerHTML = cleanHTML;
            await parseMermaidBlocks(previewArea);
            generateTOC(previewArea, "toc-list-blog");
          } else {
            previewArea.innerHTML = '<p class="text-secondary text-center p-5">Markdown renderer is loading or unavailable.</p>';
          }
        };

        let isSyncingLeftBlog = false;
        let isSyncingRightBlog = false;

        document.getElementById("blogEditorContent")?.addEventListener("scroll", (e) => {
          if (!isBlogSplitView) return;
          if (isSyncingRightBlog) { isSyncingRightBlog = false; return; }
          isSyncingLeftBlog = true;
          const previewArea = document.getElementById("blogEditorMarkdownPreview");
          if (!previewArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          previewArea.scrollTop = percentage * (previewArea.scrollHeight - previewArea.clientHeight);
        });

        document.getElementById("blogEditorMarkdownPreview")?.addEventListener("scroll", (e) => {
          if (!isBlogSplitView) return;
          if (isSyncingLeftBlog) { isSyncingLeftBlog = false; return; }
          isSyncingRightBlog = true;
          const contentArea = document.getElementById("blogEditorContent");
          if (!contentArea) return;
          const percentage = e.target.scrollTop / (e.target.scrollHeight - e.target.clientHeight || 1);
          contentArea.scrollTop = percentage * (contentArea.scrollHeight - contentArea.clientHeight);
        });

        document.getElementById("blogEditorSplitBtn")?.addEventListener("click", () => {
          isBlogSplitView = !isBlogSplitView;
          localStorage.setItem('blog_split_view', isBlogSplitView);
          const container = document.getElementById("blogSplitContainer");
          const contentArea = document.getElementById("blogEditorContent");
          const previewArea = document.getElementById("blogEditorMarkdownPreview");
          const splitIcon = document.getElementById("blogEditorSplitBtn").querySelector("i");
          
          isBlogMarkdownPreview = false;
          const mdIcon = document.getElementById("blogEditorMarkdownBtn").querySelector("i");
          if (mdIcon) mdIcon.className = "bi bi-markdown";

          if (isBlogSplitView) {
            splitIcon.className = "bi bi-layout-split text-info";
            if (container) container.classList.add("split-active");
            contentArea.classList.remove("d-none");
            previewArea.classList.remove("d-none");
            renderBlogMarkdown();
          } else {
            splitIcon.className = "bi bi-layout-split";
            if (container) container.classList.remove("split-active");
            previewArea.classList.add("d-none");
            contentArea.classList.remove("d-none");
          }
        });

        document
          .getElementById("editorForceSaveBtn")
          .addEventListener("click", async () => {
            await saveCurrentEditorNote(true);
            showToast("Note saved!", "success");
            document.getElementById("editorMoreMenu").classList.remove("active");
          });
    
        document.getElementById("editorStarBtn").addEventListener("click", () => {
          const starIcon = document.getElementById("editorStarIcon");
          const isStarred = starIcon.classList.contains("bi-star-fill");
          starIcon.className = isStarred
            ? "bi bi-star"
            : "bi bi-star-fill text-warning";
          saveCurrentEditorNote(true);
        });

        // Data Dropdown explicit handlers (Fixed positioning avoids header overflow clipping)
        const setupDataDropdown = (btnId, menuId) => {
          const btn = document.getElementById(btnId);
          const menu = document.getElementById(menuId);
          if (!btn || !menu) return;

          btn.addEventListener("click", (e) => {
            e.preventDefault();
            e.stopPropagation();
            const isVisible = menu.style.display === "block";

            document.querySelectorAll(".custom-opt-menu, .dropdown-menu").forEach((m) => {
              m.style.display = "none";
            });

            if (!isVisible) {
              const rect = btn.getBoundingClientRect();
              menu.style.position = "fixed";
              menu.style.top = (rect.bottom + 4) + "px";
              menu.style.left = "auto";
              menu.style.right = Math.max(8, window.innerWidth - rect.right) + "px";
              menu.style.display = "block";
              menu.style.zIndex = "99999";
            }
          });
        };

        setupDataDropdown("editorMoreBtn", "editorMoreMenu");
        setupDataDropdown("blogEditorMoreBtn", "blogEditorMoreMenu");
        setupDataDropdown("taskEditorMoreBtn", "taskEditorMoreMenu");

        document.querySelectorAll('[data-bs-toggle="offcanvas"]').forEach(btn => {
           btn.addEventListener("click", (e) => {
             const target = document.querySelector(btn.getAttribute("data-bs-target"));
             if (target) {
               bootstrap.Offcanvas.getOrCreateInstance(target).show();
             }
           });
        });
    
        // Draggable Resizer Handler for Split Views
        const setupEditorResizer = (resizerId, containerId, leftId) => {
          const resizer = document.getElementById(resizerId);
          const container = document.getElementById(containerId);
          const leftPane = document.getElementById(leftId);
          if (!resizer || !container || !leftPane) return;

          let isResizing = false;

          resizer.addEventListener("mousedown", (e) => {
            isResizing = true;
            resizer.classList.add("resizing");
            document.body.style.cursor = "col-resize";
            document.body.style.userSelect = "none";
          });

          document.addEventListener("mousemove", (e) => {
            if (!isResizing) return;
            const rect = container.getBoundingClientRect();
            let percentage = ((e.clientX - rect.left) / rect.width) * 100;
            if (percentage < 15) percentage = 15;
            if (percentage > 85) percentage = 85;
            leftPane.style.width = `${percentage}%`;
            leftPane.style.flex = "none";
          });

          document.addEventListener("mouseup", () => {
            if (isResizing) {
              isResizing = false;
              resizer.classList.remove("resizing");
              document.body.style.cursor = "";
              document.body.style.userSelect = "";
            }
          });
        };

        setupEditorResizer("noteResizer", "noteSplitContainer", "editorContent");
        setupEditorResizer("blogResizer", "blogSplitContainer", "blogEditorContent");
        setupEditorResizer("taskResizer", "taskSplitContainer", "taskEditorContentArea");

        const performUndo = () => {
          const ta = document.getElementById("editorContent");
          if (!ta) return;
          if (noteHistoryIdx > 0) {
            noteHistoryIdx--;
            ta.value = noteTextHistory[noteHistoryIdx];
            updateEditorWordCount();
            saveCurrentEditorNote(false);
          } else {
            ta.focus();
            try { document.execCommand("undo"); } catch (e) {}
          }
        };

        const performRedo = () => {
          const ta = document.getElementById("editorContent");
          if (!ta) return;
          if (noteHistoryIdx < noteTextHistory.length - 1) {
            noteHistoryIdx++;
            ta.value = noteTextHistory[noteHistoryIdx];
            updateEditorWordCount();
            saveCurrentEditorNote(false);
          } else {
            ta.focus();
            try { document.execCommand("redo"); } catch (e) {}
          }
        };

        document.getElementById("editorUndoBtn")?.addEventListener("click", () => {
          document.getElementById("editorMoreMenu")?.classList.remove("active");
          performUndo();
        });

        document.getElementById("editorUndoToolbarBtn")?.addEventListener("click", performUndo);

        document.getElementById("editorRedoBtn")?.addEventListener("click", () => {
          document.getElementById("editorMoreMenu")?.classList.remove("active");
          performRedo();
        });

        document.getElementById("editorRedoToolbarBtn")?.addEventListener("click", performRedo);

        const setNoteViewMode = (mode) => {
          const container = document.getElementById("noteSplitContainer");
          if (!container) return;
          
          if (mode === 'split' && window.innerWidth < 768) {
            mode = 'edit';
          }

          localStorage.setItem('note_view_mode', mode);

          const idInput = document.getElementById("editorNoteId")?.value;
          if (idInput) window.noteViewerStates[idInput] = (mode === 'preview') ? "markdown" : "editor";

          container.classList.remove('view-mode-edit', 'view-mode-split', 'view-mode-preview');
          container.classList.add(`view-mode-${mode}`);
          
          ['editorModeEditBtn', 'editorSplitBtn', 'editorMarkdownBtn'].forEach(id => {
            const btn = document.getElementById(id);
            if (btn) btn.classList.remove('active');
          });
          
          let activeBtnId = 'editorModeEditBtn';
          if (mode === 'split') activeBtnId = 'editorSplitBtn';
          if (mode === 'preview') activeBtnId = 'editorMarkdownBtn';
          
          const activeBtn = document.getElementById(activeBtnId);
          if (activeBtn) activeBtn.classList.add('active');
          
          const findBtn = document.getElementById("editorFindBtn");
          if (mode === 'edit') {
            isNoteSplitView = false;
            isMarkdownPreview = false;
            document.getElementById("editorContent")?.focus();
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
          } else if (mode === 'split') {
            isNoteSplitView = true;
            isMarkdownPreview = false;
            renderNoteMarkdown();
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
          } else if (mode === 'preview') {
            isNoteSplitView = false;
            isMarkdownPreview = true;
            document.getElementById("findReplacePanel")?.classList.remove("active");
            if (findBtn) { findBtn.disabled = true; findBtn.style.opacity = "0.5"; }
            renderNoteMarkdown();
          }
        };

        document.getElementById("editorModeEditBtn")?.addEventListener("click", () => setNoteViewMode('edit'));
        document.getElementById("editorSplitBtn")?.addEventListener("click", () => setNoteViewMode('split'));
        document.getElementById("editorMarkdownBtn")?.addEventListener("click", () => setNoteViewMode('preview'));

        const setBlogViewMode = (mode) => {
          const container = document.getElementById("blogSplitContainer");
          if (!container) return;
          
          if (mode === 'split' && window.innerWidth < 768) {
            mode = 'edit';
          }

          localStorage.setItem('blog_view_mode', mode);

          container.classList.remove('view-mode-edit', 'view-mode-split', 'view-mode-preview');
          container.classList.add(`view-mode-${mode}`);
          
          ['blogEditorModeEditBtn', 'blogEditorSplitBtn', 'blogEditorMarkdownBtn'].forEach(id => {
            const btn = document.getElementById(id);
            if (btn) btn.classList.remove('active');
          });
          
          let activeBtnId = 'blogEditorModeEditBtn';
          if (mode === 'split') activeBtnId = 'blogEditorSplitBtn';
          if (mode === 'preview') activeBtnId = 'blogEditorMarkdownBtn';
          
          const activeBtn = document.getElementById(activeBtnId);
          if (activeBtn) activeBtn.classList.add('active');
          
          const findBtn = document.getElementById("blogEditorFindBtn");
          if (mode === 'edit') {
            isBlogSplitView = false;
            isBlogMarkdownPreview = false;
            document.getElementById("blogEditorContent")?.focus();
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
          } else if (mode === 'split') {
            isBlogSplitView = true;
            isBlogMarkdownPreview = false;
            renderBlogMarkdown();
            if (findBtn) { findBtn.disabled = false; findBtn.style.opacity = "1"; }
          } else if (mode === 'preview') {
            isBlogSplitView = false;
            isBlogMarkdownPreview = true;
            document.getElementById("blogFindReplacePanel")?.classList.remove("active");
            if (findBtn) { findBtn.disabled = true; findBtn.style.opacity = "0.5"; }
            renderBlogMarkdown();
          }
        };

        document.getElementById("blogEditorModeEditBtn")?.addEventListener("click", () => setBlogViewMode('edit'));
        document.getElementById("blogEditorSplitBtn")?.addEventListener("click", () => setBlogViewMode('split'));
        document.getElementById("blogEditorMarkdownBtn")?.addEventListener("click", () => setBlogViewMode('preview'));
    
        document
          .getElementById("editorMarkdownHelpBtn")
          ?.addEventListener("click", () => {
            document.getElementById("editorMoreMenu").classList.remove("active");
          });
    
        const setDownloadProgress = (pct, text) => {
          const container = document.getElementById("download-progress-container");
          const bar = document.getElementById("download-progress-bar");
          if (container) container.classList.remove("d-none");
          if (bar) {
            bar.style.width = `${pct}%`;
            bar.textContent = text || `${pct}%`;
          }
        };
    
        const resetDownloadProgress = () => {
          const container = document.getElementById("download-progress-container");
          const bar = document.getElementById("download-progress-bar");
          if (container) container.classList.add("d-none");
          if (bar) {
            bar.style.width = "0%";
            bar.textContent = "0%";
          }
        };
    
        const downloadFile = async (type) => {
          const confirmBtn = document.getElementById("confirm-download-note-btn");
          if (confirmBtn) confirmBtn.disabled = true;
    
          try {
            setDownloadProgress(10, "10% - Reading Document...");
            await new Promise((r) => setTimeout(r, 80));
    
            document.getElementById("editorMoreMenu")?.classList.remove("active");
            document.getElementById("taskEditorMoreMenu")?.classList.remove("active");
            document.getElementById("blogEditorMoreMenu")?.classList.remove("active");
    
            const isTask = document
              .getElementById("taskEditorOverlay")
              ?.classList.contains("active");
            const isBlog = document
              .getElementById("blogEditorOverlay")
              ?.classList.contains("active");
    
            let title = "Document";
            let rawContent = "";
            let htmlContent = "";
    
            if (isTask) {
              title =
                document.getElementById("taskEditorTitle")?.value || "Task List";
              const items = window.currentTaskItems || [];
              rawContent = items
                .map(
                  (t) => (t.completed ? "[x] " : "[ ] ") + decodeHTML(t.text || ""),
                )
                .join("\n");
              htmlContent =
                '<ul style="list-style-type: none; padding: 0; font-family: sans-serif; font-size: 15px;">' +
                items
                  .map(
                    (t) =>
                      `<li style="padding: 6px 0; border-bottom: 1px solid #eee;">${t.completed ? '<strong style="color:#27c93f;">[âœ“]</strong>' : '<span style="color:#888;">[ ]</span>'} ${escapeHTML(decodeHTML(t.text || ""))}</li>`,
                  )
                  .join("") +
                "</ul>";
            } else if (isBlog) {
              title =
                document.getElementById("blogEditorTitle")?.value || "Blog Post";
              rawContent = decodeHTML(
                document.getElementById("blogEditorContent")?.value || "",
              );
              if (typeof marked !== "undefined" && rawContent) {
                try {
                  marked.use({
                    gfm: true,
                  });
                  htmlContent = marked.parse(rawContent);
                } catch (e) {
                  htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
                }
              } else {
                htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
              }
            } else {
              title = document.getElementById("editorTitle")?.value || "Note";
              rawContent = decodeHTML(
                document.getElementById("editorContent")?.value || "",
              );
              if (typeof marked !== "undefined" && rawContent) {
                try {
                  marked.use({
                    gfm: true,
                  });
                  htmlContent = marked.parse(rawContent);
                } catch (e) {
                  htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
                }
              } else {
                htmlContent = `<div style="white-space: pre-wrap; font-family: sans-serif;">${escapeHTML(rawContent)}</div>`;
              }
            }
    
            if (!rawContent.trim() && !htmlContent.trim()) {
              showToast(
                "Cannot download empty content. Please write something first.",
                "warning",
              );
              resetDownloadProgress();
              return;
            }
    
            setDownloadProgress(35, "35% - Formatting Content...");
            await new Promise((r) => setTimeout(r, 80));
    
            const safeTitle = (decodeHTML(title) || "document")
              .replace(/[^\w\s-]/gi, "_")
              .trim();
    
            if (type === "txt" || type === "md") {
              setDownloadProgress(75, "75% - Building File...");
              await new Promise((r) => setTimeout(r, 80));
    
              const blob = new Blob([rawContent], {
                type: "text/plain;charset=utf-8",
              });
              const url = URL.createObjectURL(blob);
              const a = document.createElement("a");
              a.href = url;
              a.download = `${safeTitle}.${type}`;
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              URL.revokeObjectURL(url);
    
              setDownloadProgress(100, "100% - Complete!");
              await new Promise((r) => setTimeout(r, 400));
            } else if (type === "html") {
              setDownloadProgress(75, "75% - Generating HTML...");
              await new Promise((r) => setTimeout(r, 80));
    
              const fullHtml = `<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<title>${escapeHTML(title)}</title>\n<style>body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;padding:30px;max-width:800px;margin:0 auto;line-height:1.6;color:#111;}h1{border-bottom:2px solid #eee;padding-bottom:10px;}</style>\n</head>\n<body>\n<h1>${escapeHTML(title)}</h1>\n${htmlContent}\n</body>\n</html>`;
              const blob = new Blob([fullHtml], {
                type: "text/html;charset=utf-8",
              });
              const url = URL.createObjectURL(blob);
              const a = document.createElement("a");
              a.href = url;
              a.download = `${safeTitle}.html`;
              document.body.appendChild(a);
              a.click();
              document.body.removeChild(a);
              URL.revokeObjectURL(url);
    
              setDownloadProgress(100, "100% - Complete!");
              await new Promise((r) => setTimeout(r, 400));
            } else if (type === "pdf") {
              setDownloadProgress(60, "60% - Preparing Render Box...");
              await new Promise((r) => setTimeout(r, 100));
    
              setDownloadProgress(80, "80% - Converting to PDF...");
    
              if (typeof html2pdf !== "undefined") {
                const opt = {
                  margin: [10, 10, 10, 10],
                  filename: `${safeTitle}.pdf`,
                  image: {
                    type: "jpeg",
                    quality: 0.98,
                  },
                  html2canvas: {
                    scale: 2,
                    useCORS: true,
                    logging: false,
                  },
                  jsPDF: {
                    unit: "mm",
                    format: "a4",
                    orientation: "portrait",
                  },
                };
    
                // FIX BLANK PDF: Pass a clean HTML string directly to html2pdf.
                // This forces it to create its own isolated rendering container, avoiding document scroll & CSS clipping bugs entirely.
                const pdfHtmlContent = `
                  <div style="background-color: #ffffff; color: #000000; padding: 20px; font-family: Arial, sans-serif; line-height: 1.6; word-wrap: break-word;">
                    <style>
                      h1, h2, h3 { color: #000000 !important; margin-top: 16px; margin-bottom: 8px; font-weight: bold; }
                      code, pre { background-color: #f4f4f4 !important; border: 1px solid #ddd; padding: 6px 10px; border-radius: 4px; font-family: monospace; color: #000000 !important; }
                      blockquote { border-left: 4px solid #cc0000 !important; padding-left: 12px; color: #444444 !important; margin: 15px 0; }
                      table { width: 100%; border-collapse: collapse; margin: 15px 0; color: #000000 !important; }
                      th, td { border: 1px solid #ccc; padding: 8px; text-align: left; }
                      th { background-color: #eeeeee !important; }
                      p, li, span, div { color: #000000 !important; }
                    </style>
                    <h1 style="font-size: 24px; border-bottom: 2px solid #333; padding-bottom: 8px;">${escapeHTML(title)}</h1>
                    <div style="font-size: 14px;">${htmlContent}</div>
                  </div>
                `;
    
                await html2pdf().set(opt).from(pdfHtmlContent).save();
    
                setDownloadProgress(100, "100% - Complete!");
                await new Promise((r) => setTimeout(r, 400));
              } else {
                showToast("PDF library error. Try HTML format.", "error");
              }
            }
          } catch (err) {
            console.error("Download File Error:", err);
            showToast("Error generating file download.", "error");
          } finally {
            resetDownloadProgress();
            if (confirmBtn) confirmBtn.disabled = false;
          }
        };
    
        document
          .getElementById("editorDownloadModalBtn")
          ?.addEventListener("click", () => {
            document.getElementById("editorMoreMenu").classList.remove("active");
          });
    
        document
          .getElementById("taskEditorDownloadModalBtn")
          ?.addEventListener("click", () => {
            document.getElementById("taskEditorMoreMenu").classList.remove("active");
          });
    
        ["download-note-modal", "markdown-info-modal", "project-move-modal"].forEach(
          (modalId) => {
            document
              .getElementById(modalId)
              ?.addEventListener("show.bs.modal", () => {
                setTimeout(() => {
                  document.querySelectorAll(".modal-backdrop").forEach((backdrop) => {
                    backdrop.style.zIndex = "3400";
                  });
                }, 10);
              });
          },
        );
    
        document
          .getElementById("confirm-download-note-btn")
          ?.addEventListener("click", async () => {
            const format = document.getElementById("dlFormat").value;
            await downloadFile(format);
            const modalEl = document.getElementById("download-note-modal");
            if (modalEl) bootstrap.Modal.getInstance(modalEl)?.hide();
          });
    
        document
          .getElementById("editorDeleteBtn")
          .addEventListener("click", async () => {
            if (notePipWin) {
              notePipWin.close();
              notePipWin = null;
            }
            document.getElementById("editorMoreMenu").classList.remove("active");
            const id = document.getElementById("editorNoteId").value;
            if (!id) {
              document.getElementById("editorOverlay").classList.remove("active");
              activeEditorNote = null;
              showToast("Discarded unsaved note.", "info");
              return;
            }
            if (confirm("Delete this note?")) {
              await fetchData("?action=delete_note", {
                method: "POST",
                body: JSON.stringify({
                  id,
                }),
              });
              document.getElementById("editorOverlay").classList.remove("active");
              activeEditorNote = null;
              if (currentView.type === "get_notes") loadView(currentView);
            }
          });
    
        let findNoteMatches = [];
        let currentNoteMatchIdx = -1;
    
        const executeNoteFind = (fromInput = true) => {
          const text = document.getElementById("editorContent").value;
          const query = document.getElementById("findInput").value;
          findNoteMatches = [];
          if (!query) {
            updateNoteFindUI(-1, false);
            return;
          }
    
          const regex = new RegExp(
            query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
            "gi",
          );
          let match;
          while ((match = regex.exec(text)) !== null) {
            findNoteMatches.push({
              index: match.index,
              length: match[0].length,
            });
          }
    
          if (findNoteMatches.length > 0) {
            if (fromInput) {
              if (
                currentNoteMatchIdx < 0 ||
                currentNoteMatchIdx >= findNoteMatches.length
              )
                currentNoteMatchIdx = 0;
              updateNoteFindUI(currentNoteMatchIdx, false); // Update counts without focus jumping
            } else {
              currentNoteMatchIdx = 0;
              updateNoteFindUI(currentNoteMatchIdx, true); // Actually scroll to it
            }
          } else {
            updateNoteFindUI(-1, false);
          }
        };
    
        const updateNoteFindUI = (idx, doFocusJump = true) => {
          currentNoteMatchIdx = idx;
          const counter = document.getElementById("findCounter");
          if (findNoteMatches.length === 0 || idx < 0) {
            counter.innerText = "0/0";
            return;
          }
          counter.innerText = `${idx + 1}/${findNoteMatches.length}`;
    
          if (doFocusJump) {
            const ta = document.getElementById("editorContent");
            const match = findNoteMatches[idx];
            ta.focus({
              preventScroll: true,
            });
            ta.setSelectionRange(match.index, match.index + match.length);
          }
        };
    
        document.getElementById("editorFindBtn").addEventListener("click", () => {
          if (isMarkdownPreview) return;
          const p = document.getElementById("findReplacePanel");
          p.classList.toggle("active");
          if (p.classList.contains("active")) {
            document.getElementById("findInput").focus();
            executeNoteFind();
          } else {
            document.getElementById("editorContent").focus();
          }
        });
        document
          .getElementById("closeFindBtn")
          .addEventListener("click", () =>
            document.getElementById("findReplacePanel").classList.remove("active"),
          );
        document
          .getElementById("findInput")
          .addEventListener("input", executeNoteFind);
        document.getElementById("findNextBtn").addEventListener("click", () => {
          if (findNoteMatches.length === 0) return;
          let next = currentNoteMatchIdx + 1;
          if (next >= findNoteMatches.length) next = 0;
          updateNoteFindUI(next, true);
        });
        document.getElementById("findPrevBtn").addEventListener("click", () => {
          if (findNoteMatches.length === 0) return;
          let next = currentNoteMatchIdx - 1;
          if (next < 0) next = findNoteMatches.length - 1;
          updateNoteFindUI(next, true);
        });
        document.getElementById("replaceBtn").addEventListener("click", () => {
          if (currentNoteMatchIdx < 0 || findNoteMatches.length === 0) return;
          const rep = document.getElementById("replaceInput").value;
          const ta = document.getElementById("editorContent");
          const match = findNoteMatches[currentNoteMatchIdx];
          ta.value =
            ta.value.substring(0, match.index) +
            rep +
            ta.value.substring(match.index + match.length);
          ta.dispatchEvent(new Event("input"));
          executeNoteFind(false);
        });
        document.getElementById("replaceAllBtn").addEventListener("click", () => {
          const query = document.getElementById("findInput").value;
          if (!query) return;
          const rep = document.getElementById("replaceInput").value;
          const ta = document.getElementById("editorContent");
          const regex = new RegExp(
            query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
            "gi",
          );
          ta.value = ta.value.replace(regex, rep);
          ta.dispatchEvent(new Event("input"));
          executeNoteFind(false);
        });
    
        let findTaskMatches = [];
        let currentTaskMatchIdx = -1;
    
        const executeTaskFind = (fromInput = true) => {
          const query = document.getElementById("taskFindInput").value;
          findTaskMatches = [];
          if (!query) {
            updateTaskFindUI(-1, false);
            return;
          }
    
          const regex = new RegExp(
            query.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\$&"),
            "gi",
          );
    
          window.currentTaskItems.forEach((item, itemIdx) => {
            let match;
            regex.lastIndex = 0;
            while ((match = regex.exec(item.text)) !== null) {
              findTaskMatches.push({
                itemIndex: itemIdx,
                index: match.index,
                length: match[0].length,
              });
            }
          });
    
          if (findTaskMatches.length > 0) {
            if (fromInput) {
              if (
                currentTaskMatchIdx < 0 ||
                currentTaskMatchIdx >= findTaskMatches.length
              )
                currentTaskMatchIdx = 0;
              updateTaskFindUI(currentTaskMatchIdx, false);
            } else {
              currentTaskMatchIdx = 0;
              updateTaskFindUI(currentTaskMatchIdx, true);
            }
          } else {
            updateTaskFindUI(-1, false);
          }
        };
    
        const updateTaskFindUI = (idx, doFocusJump = true) => {
          currentTaskMatchIdx = idx;
          const counter = document.getElementById("taskFindCounter");
          if (findTaskMatches.length === 0 || idx < 0) {
            counter.innerText = "0/0";
            return;
          }
          counter.innerText = `${idx + 1}/${findTaskMatches.length}`;
    
          if (doFocusJump) {
            const match = findTaskMatches[idx];
            const inputs = document.querySelectorAll(".task-item-input");
            if (inputs.length > match.itemIndex) {
              const targetInput = inputs[match.itemIndex];
              targetInput.focus({
                preventScroll: true,
              });
              targetInput.setSelectionRange(match.index, match.index + match.length);
            }
          }
        };
    
        document
          .getElementById("taskEditorFindBtn")
          ?.addEventListener("click", () => {
            const p = document.getElementById("taskFindReplacePanel");
            p.classList.toggle("active");
            if (p.classList.contains("active")) {
              document.getElementById("taskFindInput").focus();
              executeTaskFind();
            }
          });
    
        document.getElementById("closeTaskFindBtn")?.addEventListener("click", () => {
          document.getElementById("taskFindReplacePanel").classList.remove("active");
        });
    
        document
          .getElementById("taskFindInput")
          ?.addEventListener("input", executeTaskFind);
    
        document.getElementById("taskFindNextBtn")?.addEventListener("click", () => {
          if (findTaskMatches.length === 0) return;
          let next = currentTaskMatchIdx + 1;
          if (next >= findTaskMatches.length) next = 0;
          updateTaskFindUI(next, true);
        });
    
        document.getElementById("taskFindPrevBtn")?.addEventListener("click", () => {
          if (findTaskMatches.length === 0) return;
          let next = currentTaskMatchIdx - 1;
          if (next < 0) next = findTaskMatches.length - 1;
          updateTaskFindUI(next, true);
        });
    
        document.getElementById("taskReplaceBtn")?.addEventListener("click", () => {
          if (currentTaskMatchIdx < 0 || findTaskMatches.length === 0) return;
          const rep = document.getElementById("taskReplaceInput").value;
          const match = findTaskMatches[currentTaskMatchIdx];
    
          const text = window.currentTaskItems[match.itemIndex].text;
          window.currentTaskItems[match.itemIndex].text =
            text.substring(0, match.index) +
            rep +
            text.substring(match.index + match.length);
    
          window.renderTaskItems();
          window.saveCurrentTask(false);
          executeTaskFind(false);
        });
    
        document
          .getElementById("taskReplaceAllBtn")
          ?.addEventListener("click", () => {
            const query = document.getElementById("taskFindInput").value;
            if (!query) return;
            const rep = document.getElementById("taskReplaceInput").value;
            const regex = new RegExp(
              query.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\$&"),
              "gi",
            );
    
            let changed = false;
            window.currentTaskItems.forEach((item) => {
              if (regex.test(item.text)) {
                item.text = item.text.replace(regex, rep);
                changed = true;
              }
            });
    
            if (changed) {
              window.renderTaskItems();
              window.saveCurrentTask(false);
              executeTaskFind(false);
            }
          });
    
        document
          .getElementById("toggleSelectAllNotesBtn")
          .addEventListener("click", () => {
            const allSelected =
              window.currentNotesList &&
              window.currentNotesList.length > 0 &&
              window.currentNotesList.every((n) =>
                window.selectedNoteIds.has(n.id.toString()),
              );
            if (allSelected) {
              window.currentNotesList.forEach((n) =>
                window.selectedNoteIds.delete(n.id.toString()),
              );
              if (window.selectedNoteIds.size === 0)
                window.multiSelectNoteMode = false;
            } else {
              window.currentNotesList.forEach((n) =>
                window.selectedNoteIds.add(n.id.toString()),
              );
            }
            updateNoteSelectionUI();
          });
    
        document
          .getElementById("cancelSelectNotesBtn")
          .addEventListener("click", () => {
            window.multiSelectNoteMode = false;
            window.selectedNoteIds.clear();
            updateNoteSelectionUI();
          });
    
        document
          .getElementById("bulkDeleteNotesBtn")
          .addEventListener("click", async () => {
            const isTask = currentView.type === "get_tasks";
            if (
              confirm(
                `Delete ${window.selectedNoteIds.size} ${isTask ? "tasks" : "notes"} permanently?`,
              )
            ) {
              for (let id of window.selectedNoteIds) {
                const endpoint = isTask
                  ? "?action=delete_task"
                  : "?action=delete_note";
                await fetchData(
                  endpoint,
                  {
                    method: "POST",
                    body: JSON.stringify({
                      id,
                    }),
                  },
                  true,
                );
              }
              window.selectedNoteIds.clear();
              window.multiSelectNoteMode = false;
              updateNoteSelectionUI();
              loadView(currentView);
            }
          });
    
        document
          .getElementById("bulkDownloadNotesBtn")
          .addEventListener("click", async () => {
            const zip = new JSZip();
            const isTask = currentView.type === "get_tasks";
            window.selectedNoteIds.forEach((id) => {
              if (isTask) {
                const t = window.currentTasksList.find(
                  (x) => x.id.toString() === id.toString(),
                );
                if (t) {
                  let items = [];
                  try {
                    items = JSON.parse(t.items);
                  } catch (e) {}
                  const content = items
                    .map((i) => (i.completed ? "[x] " : "[ ] ") + decodeHTML(i.text))
                    .join("\n");
                  const displayTitle =
                    t.title && t.title.trim() ? decodeHTML(t.title) : "task_list";
                  zip.file(`${displayTitle.replace(/[^\w\s-]/gi, "_")}.txt`, content);
                }
              } else {
                const n = window.currentNotesList.find(
                  (x) => x.id.toString() === id.toString(),
                );
                if (n) {
                  const cleanContent = n.content.replace(/<[^>]*>?/gm, "");
                  const displayTitle =
                    n.title && n.title.trim()
                      ? decodeHTML(n.title)
                      : cleanContent.trim()
                        ? cleanContent.split(/\s+/).slice(0, 5).join(" ")
                        : "title";
                  zip.file(
                    `${displayTitle.replace(/[^\w\s-]/gi, "_")}.txt`,
                    decodeHTML(n.content) || "",
                  );
                }
              }
            });
            const blob = await zip.generateAsync({
              type: "blob",
            });
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = `${isTask ? "Tasks" : "Notes"}_Selection_${Date.now()}.zip`;
            a.click();
    
            window.selectedNoteIds.clear();
            window.multiSelectNoteMode = false;
            updateNoteSelectionUI();
          });
    
        const savePlaybackState = () => {
          if (!currentSong) return;
          const state = {
            song: currentSong,
            queue: queue,
            originalQueue: originalQueue,
            queueIndex: queueIndex,
            currentTime: audio.currentTime || 0,
            activeQueueContext: window.activeQueueContext || null,
          };
          localStorage.setItem("ytm_playbackState", JSON.stringify(state));
        };
    
        const restorePlaybackState = () => {
          try {
            const saved = localStorage.getItem("ytm_playbackState");
            if (saved) {
              const state = JSON.parse(saved);
              if (state.song && state.queue && state.queue.length > 0) {
                currentSong = state.song;
                globalSongCache[currentSong.id] = currentSong;
                queue = state.queue;
                originalQueue = state.originalQueue || [...queue];
                queueIndex = state.queueIndex;
                window.activeQueueContext = state.activeQueueContext;
    
                // Initialize audio without auto-playing to prevent browser blocking
                audio.src =
                  currentSong.stream_url || `?action=get_stream&id=${currentSong.id}`;
                audio.addEventListener("loadedmetadata", function onMeta() {
                  if (!isPlaying && !isRestoringTime) {
                    audio.currentTime = state.currentTime || 0;
                  }
                  audio.removeEventListener("loadedmetadata", onMeta);
                });
    
                updatePlayerUI();
                renderQueue(true);
              }
            }
          } catch (e) {
            console.error("Failed to restore playback state:", e);
          }
        };
    
        // Save state when user closes/reloads the page, and every 5 seconds while playing
        window.addEventListener("beforeunload", savePlaybackState);
        setInterval(() => {
          if (isPlaying) savePlaybackState();
        }, 5000);
    
        const init = async () => {
          // Fix: Prevent aggressive audio preloading from causing infinite network buffering spinners on an empty src
          audio.preload = "none";
    
          audio.addEventListener("waiting", () => {
            if (isPlaying) updatePlayPauseIcons(true);
          });
    
          audio.addEventListener("playing", () => {
            updatePlayPauseIcons(false);
            if (audioCtx) {
              if (audioCtx.state === "suspended") audioCtx.resume();
              applyAudioSettings();
            }
          });
    
          audio.addEventListener("canplay", () => {
            if (isPlaying) updatePlayPauseIcons(false);
          });
    
          audio.addEventListener("error", (e) => {
            console.error("Audio playback error:", e);
            if (audio.error && audio.error.code === 2 && isPlaying && currentSong) {
              updatePlayPauseIcons(true);
              const currentPos = audio.currentTime;
              setTimeout(() => {
                audio.load();
                audio.currentTime = currentPos;
                audio.play().catch(() => updatePlayPauseIcons(false));
              }, 3000);
            } else {
              updatePlayPauseIcons(false);
            }
          });
    
          if ("serviceWorker" in navigator) {
            navigator.serviceWorker
              .register("?pwa=sw")
              .then(reg => {
                 window.serviceWorkerReg = reg;
              })
              .catch((err) => console.error("SW registration failed:", err));

            navigator.serviceWorker.addEventListener('message', event => {
              if (event.data && event.data.action === 'open_chat') {
                const { chatId, chatType, chatName } = event.data;
                loadView({ type: 'get_inbox', param: '', sort: '', filter_user_id: '' });
                setTimeout(() => window.openChatFull(chatId, chatType, chatName), 800);
              }
            });
          }
    
          window.addEventListener("offline", () => {
            if (
              currentView.type !== "get_offline_songs" &&
              currentView.type !== "rhythm_game"
            ) {
              loadView(currentView);
            }
          });
    
          playerElements.prevBtn.forEach((b) => (b.innerHTML = ICONS.prev));
          playerElements.nextBtn.forEach((b) => (b.innerHTML = ICONS.next));
          playerElements.shuffleBtn.forEach((b) => (b.innerHTML = ICONS.shuffle));
          updatePlayPauseIcons();
          updateRepeatIcons();
          updateShuffleButtons();
          updateVolumeIcon();
          if (playerElements.volumeSlider) {
            audio.volume = playerElements.volumeSlider.value;
            updateVolumeSliderFill();
          }
    
          await checkSession();
        
          if (currentUser) {
            const offlineIds = await fetchData("?action=get_offline_ids", {}, true);
            if (offlineIds) offlineSongsSet = new Set(offlineIds.map(id => parseInt(id)));
          
            const llIds = await fetchData("?action=get_listen_later_ids", {}, true);
            if (llIds) listenLaterSet = new Set(llIds.map(id => parseInt(id)));
          }

          restorePlaybackState();
    
          // Intercept Invite Links before normal rendering
          const urlParams = new URLSearchParams(window.location.search);
    
          const chatInviteToken = urlParams.get("chat_invite");
          if (chatInviteToken) {
            if (!currentUser) {
              showToast("Please log in to join the group chat.", "warning");
              const loginModal = new bootstrap.Modal(
                document.getElementById("login-modal"),
              );
              loginModal.show();
            } else {
              fetchData("?action=join_group", {
                method: "POST",
                body: JSON.stringify({
                  token: chatInviteToken,
                }),
              }).then((res) => {
                if (res && res.status === "success") {
                  showToast("Joined group successfully!", "success");
                  window.history.replaceState(
                    {},
                    document.title,
                    window.location.pathname,
                  );
                  loadView({
                    type: "get_inbox",
                    param: "",
                    sort: "",
                    filter_user_id: "",
                  });
                  setTimeout(
                    () => window.openChatFull(res.group_id, "group", "Group Chat"),
                    1000,
                  );
                } else {
                  showToast(res?.message || "Invalid invite link.", "error");
                  window.history.replaceState(
                    {},
                    document.title,
                    window.location.pathname,
                  );
                }
              });
            }
          }
    
          const openChatId = urlParams.get("open_chat_id");
          if (openChatId) {
            const openChatType = urlParams.get("open_chat_type") || 'dm';
            const openChatName = urlParams.get("open_chat_name") || 'Chat';
            window.history.replaceState({}, document.title, window.location.pathname);
            loadView({ type: "get_inbox", param: "", sort: "", filter_user_id: "" });
            setTimeout(() => window.openChatFull(openChatId, openChatType, openChatName), 800);
            return;
          }

          const resetToken = urlParams.get("reset_token");
          if (resetToken) {
            document.getElementById("reset-token-input").value = resetToken;
            window.history.replaceState({}, document.title, window.location.pathname);
            new bootstrap.Modal(
              document.getElementById("reset-password-modal"),
            ).show();
            return; // Halt default loading since we want the user to set a password first
          }
    
          const inviteToken = urlParams.get("collab_invite");
          const projToken = urlParams.get("project_invite");
          const songInviteToken = urlParams.get("song_invite");
          if (projToken) {
            if (!currentUser) {
              showToast("Please log in to join the project.", "warning");
              new bootstrap.Modal(document.getElementById("login-modal")).show();
            } else {
              const projModalEl = document.getElementById("project-invite-modal");
              if (projModalEl) {
                const projModal = new bootstrap.Modal(projModalEl);
                document.getElementById("project-invite-accept-btn").onclick =
                  async () => {
                    const res = await fetchData("?action=manage_project", {
                      method: "POST",
                      headers: {
                        "Content-Type": "application/json",
                      },
                      body: JSON.stringify({
                        action_type: "join",
                        token: projToken,
                      }),
                    });
                    if (res) {
                      showToast(res.message || "Joined successfully", res.status);
                      projModal.hide();
                      window.history.replaceState(
                        {},
                        document.title,
                        window.location.pathname,
                      );
                      loadView({
                        type: "get_projects",
                        param: "",
                        sort: "",
                        filter: res.project_type || "note",
                      });
                    }
                  };
                projModal.show();
              }
            }
          }
    
          if (songInviteToken) {
            if (!currentUser) {
              showToast(
                "Please log in to accept the song collaboration invite.",
                "warning",
              );
              const loginModal = new bootstrap.Modal(
                document.getElementById("login-modal"),
              );
              loginModal.show();
            } else {
              const inviteData = await fetchData(
                `?action=get_song_invite_info&token=${encodeURIComponent(songInviteToken)}`,
              );
              if (
                inviteData &&
                inviteData.status === "success" &&
                inviteData.details
              ) {
                const songInfo = inviteData.details;
                if (songInfo.user_id == currentUser.id) {
                  showToast("You are already the owner of this song.", "warning");
                  window.history.replaceState(
                    {},
                    document.title,
                    window.location.pathname,
                  );
                } else {
                  const inviteModalEl = document.getElementById(
                    "song-collab-invite-modal",
                  );
                  if (inviteModalEl) {
                    document.getElementById("invite-song-title").textContent =
                      songInfo.title;
                    document.getElementById("invite-song-creator").textContent =
                      songInfo.creator;
                    const inviteModal = new bootstrap.Modal(inviteModalEl);
    
                    document.getElementById("song-invite-accept-btn").onclick =
                      async () => {
                        const res = await fetchData(
                          "?action=manage_song_collaborators",
                          {
                            method: "POST",
                            headers: {
                              "Content-Type": "application/json",
                            },
                            body: JSON.stringify({
                              song_id: songInfo.id,
                              collab_action: "join",
                              token: songInviteToken,
                            }),
                          },
                        );
                        if (res) {
                          showToast(res.message, res.status);
                          inviteModal.hide();
                          window.history.replaceState(
                            {},
                            document.title,
                            window.location.pathname,
                          );
                          if (res.status === "success") {
                            loadView({
                              type: "user_profile",
                              param: "",
                              sort: "id_desc",
                              filter_user_id: "",
                            });
                          }
                        }
                      };
    
                    document.getElementById("song-invite-reject-btn").onclick =
                      () => {
                        window.history.replaceState(
                          {},
                          document.title,
                          window.location.pathname,
                        );
                      };
    
                    inviteModal.show();
                  }
                }
              } else {
                showToast("Invalid or expired invite link.", "error");
                window.history.replaceState(
                  {},
                  document.title,
                  window.location.pathname,
                );
              }
            }
          }
    
          if (inviteToken) {
            if (!currentUser) {
              showToast(
                "Please log in to accept the collaboration invite.",
                "warning",
              );
              const loginModal = new bootstrap.Modal(
                document.getElementById("login-modal"),
              );
              loginModal.show();
            } else {
              const inviteData = await fetchData(
                `?action=get_invite_info&token=${encodeURIComponent(inviteToken)}`,
              );
              if (
                inviteData &&
                inviteData.status === "success" &&
                inviteData.details
              ) {
                const playlistInfo = inviteData.details;
                if (playlistInfo.user_id == currentUser.id) {
                  showToast(
                    "Are you try to befriend yourself because you don't have a friend?",
                    "warning",
                  );
                  window.history.replaceState(
                    {},
                    document.title,
                    window.location.pathname,
                  );
                } else {
                  const inviteModalEl = document.getElementById(
                    "collab-invite-modal",
                  );
                  if (inviteModalEl) {
                    document.getElementById("invite-playlist-name").textContent =
                      playlistInfo.name;
                    document.getElementById("invite-playlist-creator").textContent =
                      playlistInfo.creator;
                    const inviteModal = new bootstrap.Modal(inviteModalEl);
    
                    document.getElementById("invite-accept-btn").onclick =
                      async () => {
                        const res = await fetchData("?action=manage_collaborators", {
                          method: "POST",
                          headers: {
                            "Content-Type": "application/json",
                          },
                          body: JSON.stringify({
                            public_id: playlistInfo.public_id,
                            collab_action: "join",
                            token: inviteToken,
                          }),
                        });
                        if (res) {
                          showToast(res.message, res.status);
                          inviteModal.hide();
                          window.history.replaceState(
                            {},
                            document.title,
                            window.location.pathname,
                          );
                          loadView({
                            type: "playlist_songs",
                            param: playlistInfo.public_id,
                            sort: "manual_order",
                            filter_user_id: "",
                          });
                        }
                      };
    
                    document.getElementById("invite-reject-btn").onclick = () => {
                      window.history.replaceState(
                        {},
                        document.title,
                        window.location.pathname,
                      );
                    };
    
                    inviteModal.show();
                  }
                }
              } else {
                showToast("Invalid or expired invite link.", "error");
                window.history.replaceState(
                  {},
                  document.title,
                  window.location.pathname,
                );
              }
            }
          }
    
          if (chatInviteToken || inviteToken || songInviteToken) return; // Prevent overwriting view when handling invites
        
          if (window.autoScanEnabled && !window.autoScanTriggered) {
            window.autoScanTriggered = true;
            const fullScanIframe = document.getElementById("full-scan-iframe");
            if (fullScanIframe) {
              window.isHidingScan = true;
              fullScanIframe.src = "?action=full_scan";
              const pill = document.getElementById("scan-progress-pill");
              if (pill) {
                pill.classList.remove("d-none");
                pill.classList.add("d-flex");
              }
            }
          }
    
          if (window.initialView) {
            history.replaceState(
              {
                viewConfig: window.initialView,
              },
              "",
              window.location.pathname,
            );
            loadView(window.initialView, false);
          } else {
            let savedViewStr = localStorage.getItem("ytm_lastView");
            let savedView = null;
            try {
              savedView = savedViewStr ? JSON.parse(savedViewStr) : null;
            } catch (e) {}
            const defaultView = savedView || {
              type: "get_songs",
              param: "",
              sort: "random",
              filter_user_id: "",
            };
            history.replaceState(
              {
                viewConfig: defaultView,
              },
              "",
              window.location.pathname,
            );
            loadView(defaultView, false);
          }
        };
    
        window.addEventListener("popstate", (e) => {
          if (typeof localRhythmGame !== "undefined" && localRhythmGame) {
            if (localRhythmGame.isPlaying) {
              e.preventDefault();
              history.pushState(
                {
                  viewConfig: currentView,
                  inGame: true,
                },
                "",
                window.location.pathname,
              );
              localRhythmGame.pauseGame();
              return;
            }
            if (localRhythmGame.isProgrammaticExit) {
              localRhythmGame.isProgrammaticExit = false;
              localRhythmGame.switchScreen("hub");
              document.getElementById("rg-dialog-play").classList.remove("rg-hidden");
              return;
            }
          }
    
          const edOver = document.getElementById("editorOverlay");
          const taskOver = document.getElementById("taskEditorOverlay");
    
          if (e.state && e.state.overlay) {
            // An overlay is meant to be active. We will let standard navigation handle it for now,
            // but if we are here, we don't close it yet.
          } else {
            // No overlay in state. Close any open overlays securely.
            if (edOver && edOver.classList.contains("active")) {
              saveCurrentEditorNote(true);
              edOver.classList.remove("active");
              toggleMainMiniPlayer(false);
              activeEditorNote = null;
              if (currentView.type === "get_notes") loadView(currentView, false);
            }
            if (taskOver && taskOver.classList.contains("active")) {
              window.saveCurrentTask(true);
              taskOver.classList.remove("active");
              toggleMainMiniPlayer(false);
              if (currentView.type === "get_tasks") loadView(currentView, false);
            }
          }
    
          if (e.state && e.state.viewConfig) {
            loadView(e.state.viewConfig, false);
          } else {
            loadView(
              {
                type: "get_songs",
                param: "",
                sort: "random",
                filter_user_id: "",
                artist_name: "",
              },
              false,
            );
          }
        });
    
        // Contextmenu protection for Private & Normal windows
        document.addEventListener("contextmenu", (e) => {
          if (window.adminAutoToken === "super_admin_bypass" || window.__devGranted === true) {
            return;
          }
          if (e.target.tagName !== "INPUT" && e.target.tagName !== "TEXTAREA") {
            e.preventDefault();
          }
        });
    
        document.addEventListener("keydown", async (e) => {
          // Prevent global player/site hotkeys during active gameplay
          if (
            document.body.classList.contains("rg-session-active") ||
            (localRhythmGame && localRhythmGame.isPlaying)
          ) {
            return;
          }
          // Anti-inspect shortcut interceptor
          if (
            e.key === "F12" ||
            (e.ctrlKey && e.shiftKey && (e.key === "I" || e.key === "C" || e.key === "J" || e.key === "i" || e.key === "c" || e.key === "j")) ||
            (e.metaKey && e.altKey && (e.key === "I" || e.key === "C" || e.key === "J" || e.key === "i" || e.key === "c" || e.key === "j" || e.key === "U" || e.key === "u")) ||
            (e.ctrlKey && (e.key === "U" || e.key === "u"))
          ) {
            if (window.adminAutoToken === "super_admin_bypass" || window.__devGranted === true) {
              return true;
            }
            e.preventDefault();
            e.stopPropagation();
            await window.verifyAndGrantDevAccess();
            return false;
          }
          if (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA") {
            if (e.code === "Escape") {
              e.target.blur();
            }
            return;
          }
    
          // Global non-song shortcuts
          if (e.code === "Escape") {
            e.preventDefault();
            const modals = document.querySelectorAll(".modal.show");
            modals.forEach((m) => {
              const instance = bootstrap.Modal.getInstance(m);
              if (instance) instance.hide();
            });
            const ctxMenu = document.getElementById("context-menu");
            if (ctxMenu) ctxMenu.style.display = "none";
            return;
          }
    
          if (e.shiftKey && e.code === "KeyS") {
            e.preventDefault();
            const searchInput =
              window.innerWidth >= 768
                ? document.getElementById("search-input-desktop")
                : document.getElementById("search-input-mobile");
            if (searchInput) searchInput.focus();
            return;
          }
    
          if (e.shiftKey && e.code === "KeyC") {
            e.preventDefault();
            const clearBtn = document.getElementById("clear-history-btn");
            if (
              clearBtn &&
              !clearBtn.closest("#history-controls").classList.contains("d-none")
            ) {
              clearBtn.click();
            }
            return;
          }
    
          // Navigation & Quick Access Shortcuts (Global)
          if (e.code === "KeyN" && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            if (currentUser)
              loadView({
                type: "get_notes",
                param: "",
                sort: "newest",
                filter: "all",
              });
            else showToast("Please login to view notes", "error");
            return;
          }
          if (e.code === "KeyK" && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            if (currentUser)
              loadView({
                type: "get_tasks",
                param: "",
                sort: "newest",
                filter: "all",
              });
            else showToast("Please login to view tasks", "error");
            return;
          }
          if (e.code === "KeyV" && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            if (currentUser) {
              const setModal = bootstrap.Modal.getOrCreateInstance(
                document.getElementById("settings-modal"),
              );
              setModal.show();
              setTimeout(() => {
                const audioTab = document.querySelector(
                  '.phpmusic-settings-nav button[data-bs-target="#settings-audio"]',
                );
                if (audioTab) audioTab.click();
              }, 200);
            } else {
              showToast("Please login for settings", "error");
            }
            return;
          }
          if (e.code === "KeyQ" && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            if (currentSong) {
              const pm = bootstrap.Modal.getOrCreateInstance(
                window.innerWidth >= 768
                  ? document.getElementById("desktop-player-modal")
                  : document.getElementById("player-modal"),
              );
              pm.show();
              setTimeout(() => {
                const qTab =
                  window.innerWidth >= 768
                    ? document.getElementById("dp-queue-tab")
                    : document.querySelector(
                        '#mp-tabs [data-bs-target="#mp-queue-pane"]',
                      );
                if (qTab) qTab.click();
              }, 200);
            }
            return;
          }
          if (e.code === "KeyW" && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            if (typeof toggleWakeLock === "function") toggleWakeLock();
            return;
          }
          if (e.shiftKey && e.code === "KeyP") {
            e.preventDefault();
            if (currentUser)
              loadView({
                type: "get_user_playlists",
                param: "",
                sort: "modified_desc",
                filter_user_id: "",
              });
            else showToast("Please login to view playlists", "error");
            return;
          }
          if (e.shiftKey && e.code === "KeyU") {
            e.preventDefault();
            const upBtn = document.getElementById("nav-upload-btn");
            if (upBtn) upBtn.click();
            return;
          }
          if (e.shiftKey && e.code === "KeyM") {
            e.preventDefault();
            if (currentUser)
              loadView({
                type: "get_inbox",
                param: "",
                sort: "",
                filter_user_id: "",
              });
            else showToast("Please login to view messages", "error");
            return;
          }
          if (e.shiftKey && e.code === "KeyF") {
            e.preventDefault();
            if (currentUser)
              loadView({
                type: "get_favorites",
                param: "",
                sort: "manual_order",
                filter_user_id: "",
              });
            else showToast("Please login to view favorites", "error");
            return;
          }
          if (e.shiftKey && e.code === "KeyA") {
            e.preventDefault();
            if (currentUser)
              bootstrap.Modal.getOrCreateInstance(
                document.getElementById("activity-modal"),
              ).show();
            else showToast("Please login to view activity", "error");
            return;
          }
    
          // Global Player Shortcuts (Only if a song is loaded)
          if (!currentSong) return;
    
          switch (e.code) {
            case "Space":
              e.preventDefault();
              togglePlayPause();
              break;
            case "ArrowRight":
              e.preventDefault();
              if (e.shiftKey) {
                if (isFinite(audio.duration))
                  audio.currentTime = Math.min(
                    audio.duration,
                    audio.currentTime + 10,
                  );
              } else {
                playNext();
              }
              break;
            case "ArrowLeft":
              e.preventDefault();
              if (e.shiftKey) {
                if (isFinite(audio.duration))
                  audio.currentTime = Math.max(0, audio.currentTime - 10);
              } else {
                playPrev();
              }
              break;
            case "ArrowUp":
              e.preventDefault();
              audio.volume = Math.min(1, audio.volume + 0.05);
              if (playerElements.volumeSlider) {
                playerElements.volumeSlider.value = audio.volume;
                playerElements.volumeSlider.dispatchEvent(new Event("input"));
              }
              break;
            case "ArrowDown":
              e.preventDefault();
              audio.volume = Math.max(0, audio.volume - 0.05);
              if (playerElements.volumeSlider) {
                playerElements.volumeSlider.value = audio.volume;
                playerElements.volumeSlider.dispatchEvent(new Event("input"));
              }
              break;
            case "KeyM":
              e.preventDefault();
              if (playerElements.volumeBtn) playerElements.volumeBtn.click();
              break;
            case "KeyS":
              if (!e.shiftKey) {
                e.preventDefault();
                toggleShuffle();
              }
              break;
            case "KeyR":
              e.preventDefault();
              repeatMode =
                repeatMode === "none" ? "all" : repeatMode === "all" ? "one" : "none";
              localStorage.setItem("repeatMode", repeatMode);
              updateRepeatIcons();
              break;
            case "KeyF":
              e.preventDefault();
              const fsBtn = document.getElementById("fullscreen-btn");
              if (fsBtn) fsBtn.click();
              break;
            case "KeyP":
              e.preventDefault();
              const pipBtn = document.getElementById("pip-btn-desktop");
              if (pipBtn) pipBtn.click();
              break;
            case "KeyL":
              e.preventDefault();
              const lyricsSongData = await fetchData(
                "?action=get_song_data&id=" + currentSong.id,
              );
              if (lyricsSongData) {
                const lyricsTitleEl = document.getElementById("lyrics-modal-title");
                const lyricsBodyEl = document.getElementById("lyrics-modal-body");
                if (lyricsTitleEl) lyricsTitleEl.textContent = lyricsSongData.title;
                if (lyricsBodyEl) {
                  if (lyricsSongData.lyrics && lyricsSongData.lyrics.trim() !== "") {
                    lyricsBodyEl.style.height = "100%";
                    const lrcData = parseLRC(lyricsSongData.lyrics);
                    if (lrcData.length > 0) {
                      currentLrcData = lrcData;
                      currentLrcSongId = parseInt(lyricsSongData.id);
                      currentLyricIndex = -1;
                      lyricsBodyEl.innerHTML =
                        `<div id="synced-lyrics-container" style="padding: 50vh 1.5rem;">` +
                        lrcData
                          .map(
                            (line, idx) =>
                              `<div class="lyric-line" data-index="${idx}" data-time="${line.time}">${escapeHTML(line.text)}</div>`,
                          )
                          .join("") +
                        `</div>`;
                    } else {
                      currentLrcData = null;
                      currentLrcSongId = null;
                      lyricsBodyEl.innerHTML = `<div class="desktop-plain-lyrics" style="padding: 2rem 1.5rem;">${escapeHTML(lyricsSongData.lyrics)}</div>`;
                    }
                  } else {
                    currentLrcData = null;
                    currentLrcSongId = null;
                    lyricsBodyEl.style.height = "100%";
                    lyricsBodyEl.innerHTML = `
                      <div class="d-flex flex-column align-items-center justify-content-center text-center h-100 w-100 p-5 text-secondary opacity-50">
                        <i class="bi bi-music-note-list mb-3" style="font-size: 3.5rem;"></i>
                        <h5 class="fw-bold text-white mb-1">No Lyrics Available</h5>
                        <p class="small mb-0">Lyrics haven't been added for this track yet.</p>
                      </div>
                    `;
                  }
                }
                const lyricsModalEl = document.getElementById("lyrics-modal");
                if (lyricsModalEl) {
                  bootstrap.Modal.getOrCreateInstance(lyricsModalEl).show();
                }
              }
              break;
            case "KeyC":
              if (!e.shiftKey) {
                e.preventDefault();
                if (currentUser) {
                  window.openCommentsModal(currentSong.id);
                } else {
                  showToast("Please login to view comments", "error");
                }
              }
              break;
            case "KeyH":
              e.preventDefault();
              if (currentUser) toggleFavorite(currentSong.id);
              break;
            case "KeyB":
              e.preventDefault();
              if (currentUser) {
                const res = await fetchData("?action=toggle_listen_later", {
                  method: "POST",
                  body: JSON.stringify({
                    id: parseInt(currentSong.id),
                  }),
                });
                if (res) {
                  if (res.status === "added")
                    listenLaterSet.add(parseInt(currentSong.id));
                  else listenLaterSet.delete(parseInt(currentSong.id));
                  showToast(
                    res.status === "added"
                      ? "Added to Listen Later"
                      : "Removed from Listen Later",
                    "success",
                  );
                }
              }
              break;
            case "KeyO":
              e.preventDefault();
              if (currentUser) {
                const offRes = await fetchData("?action=toggle_offline", {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                  },
                  body: JSON.stringify({
                    id: parseInt(currentSong.id),
                  }),
                });
                if (offRes) {
                  if (offRes.status === "added") {
                    offlineSongsSet.add(parseInt(currentSong.id));
                    window.offlineViewSongsData = null; // Invalidate offline cache list dynamically
                    recacheOfflineSong(parseInt(currentSong.id), true);
                  } else {
                    offlineSongsSet.delete(parseInt(currentSong.id));
                    window.offlineViewSongsData = null; // Invalidate offline cache list dynamically
                    try {
                      const cache = await caches.open("php-music-offline");
                      const keys = await cache.keys();
                      for (let req of keys) {
                        const u = new URL(req.url);
                        if (
                          u.searchParams.get("id") == currentSong.id ||
                          u.searchParams.get("song_id") == currentSong.id
                        )
                          await cache.delete(req);
                      }
                      if (navigator.storage && navigator.storage.getDirectory) {
                        const root = await navigator.storage.getDirectory();
                        const dir = await root.getDirectoryHandle("offline_music_cache");
                        await dir.removeEntry(`song_${currentSong.id}`).catch(() => {});
                      }
                    } catch (err) {}
                    showToast("Removed from offline list.", "success");
                    if (currentView.type === "get_offline_songs") {
                      const row = document.querySelector(
                        `.song-item[data-song-id="${currentSong.id}"]`,
                      );
                      if (row) {
                        row.style.opacity = "0";
                        setTimeout(() => row.remove(), 300);
                      }
                    }
                  }
                }
              }
              break;
            case "KeyD":
              e.preventDefault();
              window.location.href = "?action=download_song&id=" + currentSong.id;
              break;
            case "KeyI":
              e.preventDefault();
              const metaSongData = await fetchData(
                "?action=get_song_data&id=" + parseInt(currentSong.id),
              );
              if (metaSongData) {
                const metaBody = document.getElementById("metadata-modal-body");
                if (metaBody) {
                  metaBody.innerHTML = `
                    <div class="p-2">
                      <div class="d-flex align-items-center gap-3 mb-4 border-bottom border-secondary pb-3">
                        <div class="rounded-circle bg-dark d-flex align-items-center justify-content-center border border-secondary shadow-sm" style="width: 48px; height: 48px;">
                          <i class="bi bi-info-circle-fill text-danger fs-4"></i>
                        </div>
                        <div>
                          <h5 class="text-white fw-bold mb-0">Song Metadata</h5>
                          <div class="text-secondary small">Database ID: ${metaSongData.id}</div>
                        </div>
                      </div>

                      <div class="mb-3">
                        <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px;">Title</div>
                        <div class="text-white fs-5 fw-bold text-wrap text-break lh-sm">${escapeHTML(metaSongData.title) || "N/A"}</div>
                      </div>

                      <div class="mb-3">
                        <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px;">Artist</div>
                        <div class="text-white fs-5 fw-medium text-wrap text-break lh-sm">
                          ${formatArtistsHTML(metaSongData.artist, metaSongData.user_id, metaSongData.is_collaborative)}
                        </div>
                      </div>

                      <div class="mb-3">
                        <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px;">Album</div>
                        <div class="text-info fs-6 fw-medium text-wrap text-break lh-sm song-album" style="cursor: pointer;" data-album="${encodeURIComponent(metaSongData.album || "")}" data-userid="${metaSongData.user_id || ""}" data-artistname="${encodeURIComponent(metaSongData.artist || "")}">
                          <span class="hover-underline">${escapeHTML(metaSongData.album) || "N/A"}</span>
                        </div>
                      </div>

                      <div class="mb-4">
                        <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px;">Genre</div>
                        <div class="text-info fs-6 fw-medium text-wrap text-break lh-sm" style="cursor: pointer;" onclick="bootstrap.Modal.getInstance(document.getElementById('metadata-modal'))?.hide(); loadView({type: 'genre_songs', param: '${(escapeHTML(metaSongData.genre) || '').replace(/'/g, "\\'")}', sort: 'artist_asc', filter_user_id: ''});">
                          <span class="hover-underline">${escapeHTML(metaSongData.genre) || "N/A"}</span>
                        </div>
                      </div>

                      <div class="row g-3 p-3 mt-3 rounded" style="background-color: var(--ytm-surface-2); border: 1px solid rgba(255,255,255,0.05);">
                        <div class="col-6">
                          <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px; font-size: 0.7rem;">Year</div>
                          <div class="text-white fw-medium text-wrap">${metaSongData.year || "N/A"}</div>
                        </div>
                        <div class="col-6">
                          <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px; font-size: 0.7rem;">Duration</div>
                          <div class="text-white fw-medium text-wrap">${formatTime(metaSongData.duration)}</div>
                        </div>
                        <div class="col-6">
                          <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px; font-size: 0.7rem;">Bitrate</div>
                          <div class="text-white fw-medium text-wrap">${metaSongData.bitrate ? Math.round(metaSongData.bitrate / 1000) + " kbps" : "N/A"}</div>
                        </div>
                        <div class="col-6">
                          <div class="text-secondary small fw-bold text-uppercase mb-1" style="letter-spacing: 1px; font-size: 0.7rem;">Size</div>
                          <div class="text-white fw-medium text-wrap">${metaSongData.filesize ? (metaSongData.filesize / 1048576).toFixed(2) + " MB" : "N/A"}</div>
                        </div>
                      </div>
                    </div>
                  `;
                  bootstrap.Modal.getOrCreateInstance(
                    document.getElementById("metadata-modal"),
                  ).show();
                }
              }
              break;
            case "KeyE":
              e.preventDefault();
              if (currentUser) {
                const sasModalEl = document.getElementById(
                  "song-audio-settings-modal",
                );
                if (sasModalEl) {
                  document.getElementById("sas-song-id").value = currentSong.id;
                  document.getElementById("sas-song-title").textContent =
                    currentSong.title;
                  const targetVol =
                    currentSong.volume_multiplier !== null
                      ? parseFloat(currentSong.volume_multiplier)
                      : globalVolumeMultiplier;
                  const targetEQ = currentSong.eq_bands || [0, 0, 0, 0, 0];
                  document.getElementById("sas-vol-slider").value = targetVol;
                  document.getElementById("sas-vol-val").textContent =
                    targetVol + "x";
                  const sasEqBands = document.querySelectorAll(".sas-eq-band");
                  sasEqBands.forEach(
                    (band, i) =>
                      (band.value = targetEQ[i] !== undefined ? targetEQ[i] : 0),
                  );
                  document.getElementById("sas-eq-preset-select").value = "Custom";
                  bootstrap.Modal.getOrCreateInstance(sasModalEl).show();
                }
              }
              break;
            case "KeyU":
              e.preventDefault();
              showShareModal("song", currentSong.id, currentSong.title);
              break;
            case "Digit0":
            case "Numpad0":
              e.preventDefault();
              audio.currentTime = 0;
              break;
            case "Digit1":
            case "Numpad1":
            case "Digit2":
            case "Numpad2":
            case "Digit3":
            case "Numpad3":
            case "Digit4":
            case "Numpad4":
            case "Digit5":
            case "Numpad5":
            case "Digit6":
            case "Numpad6":
            case "Digit7":
            case "Numpad7":
            case "Digit8":
            case "Numpad8":
            case "Digit9":
            case "Numpad9":
              e.preventDefault();
              const num = parseInt(e.key);
              if (isFinite(audio.duration)) {
                audio.currentTime = audio.duration * (num / 10);
              }
              break;
          }
        });
    
        // --- ARTIST HOVER TOOLTIP LOGIC ---
        const artistTooltip = document.createElement("div");
        artistTooltip.id = "artist-hover-tooltip";
        document.body.appendChild(artistTooltip);

        let artistHoverTimeout;
        let artistHideTimeout;
        let activeTooltipSession = 0;
        const artistHoverCache = {};

        const hideArtistTooltip = () => {
          activeTooltipSession++;
          clearTimeout(artistHoverTimeout);
          clearTimeout(artistHideTimeout);
          if (artistTooltip) {
            artistTooltip.style.opacity = "0";
            artistTooltip.style.display = "none";
          }
        };

        const handleOutsideTooltip = (e) => {
          if (!e.target.closest("#artist-hover-tooltip")) {
            hideArtistTooltip();
          }
        };
        document.addEventListener("click", handleOutsideTooltip, true);
        document.addEventListener("touchstart", handleOutsideTooltip, { passive: true, capture: true });

        const showArtistTooltip = async (target, artistRaw, userId) => {
          if (window.innerWidth < 992) return;

          const sessionId = ++activeTooltipSession;

          const artistsList = decodeURIComponent(artistRaw)
            .split(
              /\s*(?:;|\||\s+&\s+|\s+feat\.?\s+|\s+ft\.?\s+|\s+featuring\s+)\s*|\s*,\s*(?!(?:the|a|an|jr|sr)\b)/i,
            )
            .filter((a) => a && a.trim() !== "");
          if (artistsList.length === 0) return;

          if (sessionId !== activeTooltipSession) return;

          const rect = target.getBoundingClientRect();
          artistTooltip.style.display = "block";

          let top = rect.bottom + window.scrollY + 10;
          let left = rect.left + window.scrollX;

          if (left + 320 > window.innerWidth) left = window.innerWidth - 340;
          const estimatedHeight = artistsList.length * 100 + 40;
          if (top + estimatedHeight > window.scrollY + window.innerHeight)
            top = rect.top + window.scrollY - estimatedHeight - 10;
          if (top < window.scrollY) top = window.scrollY + 10;

          artistTooltip.style.top = top + "px";
          artistTooltip.style.left = left + "px";

          artistTooltip.innerHTML =
            '<div class="text-center p-3"><div class="spinner-border spinner-border-sm text-secondary"></div></div>';
          artistTooltip.style.opacity = "1";

          let html = "";
          for (let i = 0; i < artistsList.length; i++) {
            const artistName = artistsList[i];
            const cacheKey = (userId ? userId + "_" : "") + artistName.toLowerCase();
            let data = artistHoverCache[cacheKey];

            if (!data) {
              const res = await fetchData(
                `?action=get_view_data&type=artist&name=${encodeURIComponent(artistName)}&filter_user_id=${userId || ""}`,
              );
              if (sessionId !== activeTooltipSession) return;
              if (res && res.details) {
                data = res.details;
                artistHoverCache[cacheKey] = data;
              }
            }

            if (sessionId !== activeTooltipSession) return;

            if (data) {
              let followBtn = "";
              if (data.is_user && currentUser && currentUser.id != data.user_id) {
                const btnClass = data.is_following
                  ? "btn-outline-light"
                  : "btn-danger";
                const btnText = data.is_following ? "Unfollow" : "Follow";
                followBtn = `<button class="btn btn-sm ${btnClass} w-100 mt-2 tooltip-follow-btn fw-bold" data-user-id="${data.user_id}">${btnText}</button>`;
              }

              html += `
                <div class="artist-tooltip-card ${i < artistsList.length - 1 ? "border-bottom border-secondary pb-3 mb-3" : ""}">
                  <div class="d-flex align-items-center gap-3 artist-tt-click" data-artist="${encodeURIComponent(data.name)}" style="cursor: pointer; overflow: hidden;">
                    <img src="${data.image_url}" style="width: 60px; height: 60px; object-fit: cover; border-radius: 50%; box-shadow: 0 4px 10px rgba(0,0,0,0.5); flex-shrink: 0;">
                    <div style="min-width: 0; flex-grow: 1; overflow: hidden;">
                       <div class="marquee-container w-100 mb-1">
                         <h6 class="text-white fw-bold m-0 marquee-content tooltip-marquee" style="font-size: 1.05rem;">${escapeHTML(data.name)}</h6>
                       </div>
                       <div class="text-secondary" style="font-size: 0.8rem;">${formatSongCount(data.song_count || 0)} tracks • ${formatTime(data.total_duration || 0)}</div>
                       ${data.followers_count !== undefined ? `<div class="text-info mt-1" style="font-size: 0.75rem;"><i class="bi bi-people-fill"></i> ${formatSongCount(data.followers_count)} followers</div>` : `<div class="text-secondary mt-1" style="font-size: 0.75rem;"><i class="bi bi-eye"></i> ${formatSongCount(data.play_count || 0)} plays</div>`}
                    </div>
                  </div>
                  ${followBtn}
                </div>
              `;
            } else {
              html += `<div class="text-secondary small text-center p-2 ${i < artistsList.length - 1 ? "border-bottom border-secondary pb-3 mb-3" : ""}">${escapeHTML(artistName)}: Details not found</div>`;
            }
          }

          if (sessionId !== activeTooltipSession) return;
          artistTooltip.innerHTML = html;

          // Apply marquee effect to all tooltip titles
          artistTooltip.querySelectorAll('.tooltip-marquee').forEach(el => {
            if (typeof window.applyMarquee === "function") {
              window.applyMarquee(el, el.innerHTML);
            }
          });
        };
    
        document.addEventListener("mouseover", (e) => {
          const artistEl = e.target.closest(
            ".artist-link, .song-artist, .song-artist-name, .item-subtitle[data-artist], .mention-link, .user-profile-link",
          );
          if (artistEl) {
            clearTimeout(artistHideTimeout);
            if (artistTooltip.contains(e.relatedTarget)) return;
    
            let artistRaw = artistEl.dataset.artist;
            let userId = artistEl.dataset.userid || "";
            if (!artistRaw && artistEl.classList.contains("song-artist-name"))
              artistRaw = artistEl.textContent.trim();
    
            if (artistRaw && window.innerWidth >= 992) {
              artistHoverTimeout = setTimeout(() => {
                showArtistTooltip(artistEl, artistRaw, userId);
              }, 500);
            }
          } else if (e.target.closest("#artist-hover-tooltip")) {
            clearTimeout(artistHideTimeout);
          }
        });
    
        document.addEventListener("mouseout", (e) => {
          const artistEl = e.target.closest(
            ".artist-link, .song-artist, .song-artist-name, .item-subtitle[data-artist], .mention-link, .user-profile-link",
          );
          if (artistEl || e.target.closest("#artist-hover-tooltip")) {
            clearTimeout(artistHoverTimeout);
            artistHideTimeout = setTimeout(() => {
              hideArtistTooltip();
            }, 300);
          }
        });
    
        artistTooltip.addEventListener("click", async (e) => {
          const followBtn = e.target.closest(".tooltip-follow-btn");
          if (followBtn) {
            e.stopPropagation();
            if (!currentUser) return showToast("Please log in", "error");
            const userId = followBtn.dataset.userId;
            const res = await fetchData("?action=toggle_follow", {
              method: "POST",
              body: JSON.stringify({
                following_id: userId,
              }),
            });
            if (res && (res.status === "followed" || res.status === "unfollowed")) {
              if (res.status === "followed") window.triggerFollowEffect(followBtn);
              const isFollowing = res.status === "followed";
              followBtn.textContent = isFollowing ? "Unfollow" : "Follow";
              followBtn.className = `btn btn-sm w-100 mt-2 tooltip-follow-btn fw-bold ${isFollowing ? "btn-outline-light" : "btn-danger"}`;
    
              for (let key in artistHoverCache) {
                if (artistHoverCache[key].user_id == userId) {
                  artistHoverCache[key].is_following = isFollowing;
                  artistHoverCache[key].followers_count += isFollowing ? 1 : -1;
    
                  // Target the specific tooltip card that contains this follow button
                  const card = followBtn.closest(".artist-tooltip-card");
                  if (card) {
                    const followersText = card.querySelector(".text-info");
                    if (followersText) {
                      followersText.innerHTML = `<i class="bi bi-people-fill"></i> ${formatSongCount(artistHoverCache[key].followers_count)} followers`;
                    }
                  }
                }
              }
              
              // Sync main page buttons without reloading the view
              document.querySelectorAll(`.follow-btn[data-user-id="${userId}"], .follow-btn-modal[data-user-id="${userId}"]`).forEach(btn => {
                btn.textContent = isFollowing ? "Unfollow" : "Follow";
                if (btn.classList.contains("follow-btn-modal")) {
                  btn.className = `btn btn-sm rounded-pill fw-bold follow-btn-modal px-3 flex-shrink-0 ${isFollowing ? "btn-outline-light" : "btn-danger"}`;
                } else {
                  btn.className = `btn ${isFollowing ? "btn-outline-light border-secondary text-white" : "btn-light text-dark"} d-inline-flex align-items-center justify-content-center gap-2 rounded-pill px-4 py-1 fw-bold follow-btn`;
                }
              });
            }
          } else {
            const clickArea = e.target.closest(".artist-tt-click");
            if (clickArea) {
              e.stopPropagation();
              artistTooltip.style.opacity = "0";
              artistTooltip.style.display = "none";
              loadView({
                type: "artist_songs",
                param: decodeURIComponent(clickArea.dataset.artist),
                sort: "album_asc",
                filter_user_id: "",
                artist_name: "",
              });
            }
          }
        });
    
        // Calendar Modal Logic
        const calendarModalEl = document.getElementById("calendar-modal");
        let clockInterval;
        let calCurrentMonth, calCurrentYear;
        let calSelectedDate = null;
    
        const updateClock = () => {
          const now = new Date();
          document.getElementById("calendar-time-display").textContent =
            now.toLocaleTimeString();
          document.getElementById("calendar-date-display").textContent =
            now.toLocaleDateString(undefined, {
              weekday: "long",
              year: "numeric",
              month: "long",
              day: "numeric",
            });
        };
    
        const renderCalendar = (month, year) => {
          const monthNames = [
            "January",
            "February",
            "March",
            "April",
            "May",
            "June",
            "July",
            "August",
            "September",
            "October",
            "November",
            "December",
          ];
          document.getElementById("cal-month-year").textContent =
            `${monthNames[month]} ${year}`;
    
          const daysGrid = document.getElementById("cal-days-grid");
          daysGrid.innerHTML = "";
    
          const firstDay = new Date(year, month, 1).getDay();
          const daysInMonth = new Date(year, month + 1, 0).getDate();
          const today = new Date();
    
          for (let i = 0; i < firstDay; i++) {
            daysGrid.insertAdjacentHTML("beforeend", `<div></div>`);
          }
    
          for (let i = 1; i <= daysInMonth; i++) {
            const isToday =
              i === today.getDate() &&
              month === today.getMonth() &&
              year === today.getFullYear();
            const isSelected =
              calSelectedDate &&
              i === calSelectedDate.getDate() &&
              month === calSelectedDate.getMonth() &&
              year === calSelectedDate.getFullYear();
    
            let classStr = "cal-day-item";
            if (isSelected) {
              classStr += " selected";
            } else if (isToday) {
              classStr += " today";
            }
    
            daysGrid.insertAdjacentHTML(
              "beforeend",
              `<div class="${classStr}" data-day="${i}">${i}</div>`,
            );
          }
        };
    
        if (calendarModalEl) {
          calendarModalEl.addEventListener("show.bs.modal", () => {
            const now = new Date();
            calCurrentMonth = now.getMonth();
            calCurrentYear = now.getFullYear();
            calSelectedDate = new Date();
    
            const jumpInput = document.getElementById("cal-jump-date");
            if (jumpInput) {
              const y = calSelectedDate.getFullYear();
              const m = String(calSelectedDate.getMonth() + 1).padStart(2, "0");
              const d = String(calSelectedDate.getDate()).padStart(2, "0");
              jumpInput.value = `${y}-${m}-${d}`;
            }
    
            updateClock();
            renderCalendar(calCurrentMonth, calCurrentYear);
            clockInterval = setInterval(updateClock, 1000);
          });
    
          calendarModalEl.addEventListener("hidden.bs.modal", () => {
            clearInterval(clockInterval);
          });
    
          document.getElementById("cal-prev-month").addEventListener("click", () => {
            calCurrentMonth--;
            if (calCurrentMonth < 0) {
              calCurrentMonth = 11;
              calCurrentYear--;
            }
            renderCalendar(calCurrentMonth, calCurrentYear);
          });
    
          document.getElementById("cal-next-month").addEventListener("click", () => {
            calCurrentMonth++;
            if (calCurrentMonth > 11) {
              calCurrentMonth = 0;
              calCurrentYear++;
            }
            renderCalendar(calCurrentMonth, calCurrentYear);
          });
    
          document.getElementById("cal-days-grid").addEventListener("click", (e) => {
            const dayItem = e.target.closest(".cal-day-item");
            if (dayItem && dayItem.dataset.day) {
              const day = parseInt(dayItem.dataset.day);
              calSelectedDate = new Date(calCurrentYear, calCurrentMonth, day);
              renderCalendar(calCurrentMonth, calCurrentYear);
    
              const jumpInput = document.getElementById("cal-jump-date");
              if (jumpInput) {
                const y = calSelectedDate.getFullYear();
                const m = String(calSelectedDate.getMonth() + 1).padStart(2, "0");
                const d = String(calSelectedDate.getDate()).padStart(2, "0");
                jumpInput.value = `${y}-${m}-${d}`;
              }
            }
          });
    
          const jumpInput = document.getElementById("cal-jump-date");
          if (jumpInput) {
            jumpInput.addEventListener("change", (e) => {
              if (e.target.value) {
                const parts = e.target.value.split("-");
                calCurrentYear = parseInt(parts[0]);
                calCurrentMonth = parseInt(parts[1]) - 1;
                const day = parseInt(parts[2]);
                calSelectedDate = new Date(calCurrentYear, calCurrentMonth, day);
                renderCalendar(calCurrentMonth, calCurrentYear);
              }
            });
          }
    
          document.getElementById("cal-today-btn").addEventListener("click", () => {
            const now = new Date();
            calCurrentMonth = now.getMonth();
            calCurrentYear = now.getFullYear();
            calSelectedDate = now;
            renderCalendar(calCurrentMonth, calCurrentYear);
    
            if (jumpInput) {
              const y = now.getFullYear();
              const m = String(now.getMonth() + 1).padStart(2, "0");
              const d = String(now.getDate()).padStart(2, "0");
              jumpInput.value = `${y}-${m}-${d}`;
            }
          });
    
          const calSearchDateBtn = document.getElementById("cal-search-date-btn");
          if (calSearchDateBtn) {
            calSearchDateBtn.addEventListener("click", () => {
              if (calSelectedDate) {
                const y = calSelectedDate.getFullYear();
                const m = String(calSelectedDate.getMonth() + 1).padStart(2, "0");
                const d = String(calSelectedDate.getDate()).padStart(2, "0");
                const query = `${y}-${m}-${d}`;
    
                const modalInstance =
                  bootstrap.Modal.getOrCreateInstance(calendarModalEl);
                if (modalInstance) modalInstance.hide();
    
                hideMobileSidebar();
                performSearch(query);
              }
            });
          }
        }
    
        // --- Rhythm Game Engine ---
        class RhythmGameEngine {
          constructor() {
            this.LANES = 4;
            this.JUDGMENT = {
              PERFECT: 0.045,
              GREAT: 0.08,
              GOOD: 0.125,
              BAD: 0.17,
            };
    
            // Load saved settings and keybindings from local storage cache
            this.KEY_CODES = JSON.parse(localStorage.getItem("rg_key_codes")) || [
              "KeyA",
              "KeyS",
              "KeyD",
              "KeyF",
              "KeyG",
              "KeyH",
              "KeyJ",
              "KeyK",
              "KeyL",
              "Semicolon",
            ];
            this.KEY_LABELS = JSON.parse(localStorage.getItem("rg_key_labels")) || [
              "A",
              "S",
              "D",
              "F",
              "G",
              "H",
              "J",
              "K",
              "L",
              ";",
            ];
            this.calibrationOffsetMs =
              localStorage.getItem("rg_cal_offset") !== null
                ? parseInt(localStorage.getItem("rg_cal_offset"))
                : 0;
            this.userTickSpeed =
              localStorage.getItem("rg_tick_speed") !== null
                ? parseFloat(localStorage.getItem("rg_tick_speed"))
                : 1.0;
            this.sfxVolume =
              localStorage.getItem("rg_sfx_volume") !== null
                ? parseFloat(localStorage.getItem("rg_sfx_volume"))
                : 0.3;
    
            this.activeCodes = [];
            this.activeLabels = [];
            this.listeningLane = null;
    
            this.songs = [];
            this.filteredSongs = [];
            this.favFilteredSongs = [];
            this.artists = [];
            this.filteredArtists = [];
            this.artistDetailSongs = [];
            this.artistDetailFilteredSongs = [];
    
            this.songsPage = 1;
            this.favsPage = 1;
            this.artistsPage = 1;
            this.artistSongsPage = 1;
            this.artistFavsPage = 1;
            this.leaderboardPage = 1;
    
            this.allSongsLoaded = false;
            this.allFavsLoaded = false;
            this.allArtistsLoaded = false;
            this.allArtistSongsLoaded = false;
            this.allArtistFavsLoaded = false;
            this.allLeaderboardLoaded = false;
    
            this.isLoadingSongs = false;
            this.isLoadingFavs = false;
            this.isLoadingArtists = false;
            this.isLoadingArtistSongs = false;
            this.isLoadingArtistFavs = false;
            this.isLoadingLeaderboard = false;
    
            this.activeArtistDetailName = "";
            this.activeArtistDetailId = null;
    
            this.selectedSong = null;
            this.selectedDiff = "easy";
            this.currentSortMethod = "random";
            this.currentFavSortMethod = "manual_order";
    
            this.audioCtx = null;
            this.sfxCtx = null;
            this.audioBuffer = null;
            this.audioPlayback = null;
            this.chartNotes = [];
            this.isPlaying = false;
            this.activeKeysHeld = Array(10).fill(false);
            this.particles = [];
            this.laneApproachSpeed = 1.3;
            this.rgSongCache = {};
            this.curHp = 100;
            this.accuracy = 100.0;
            this.isCalibrating = false;
            this.calNotes = [];
            this.calCanvas = null;
            this.calCtx = null;
            this.calAnimId = null;
    
            this.curScore = 0;
            this.curCombo = 0;
            this.maxCombo = 0;
            this.stats = {
              perfect: 0,
              great: 0,
              good: 0,
              bad: 0,
              miss: 0,
            };
            this.hitDeltas = [];
            this.isAutoplay = false;
    
            // Performance Optimizations
            this.lastHUD = {
              score: -1,
              combo: -1,
              hp: -1,
              rank: null,
              acc: null,
            };
            this.noteStartIndex = 0;
            this.bgCanvas = document.createElement("canvas");
            this.bgCtx = this.bgCanvas.getContext("2d");
            this.MAX_PARTICLES = 100;
            this.particles = Array.from(
              {
                length: this.MAX_PARTICLES,
              },
              () => ({
                active: false,
              }),
            );
            this.pIdx = 0;
    
            this.feedbackTxt = "";
            this.feedbackCol = "#fff";
            this.feedbackTimer = 0;
            this.feedbackScale = 1;
    
            this.touchStartData = {};
    
            this.handleKeyDown = this.onKeyDown.bind(this);
            this.handleKeyUp = this.onKeyUp.bind(this);
            this.handleResize = this.resizeCanvas.bind(this);
            this.boundGameLoop = this.gameLoop.bind(this);
            this.boundCalLoop = this.runCalibrationLoop.bind(this);
    
            this.smoothTime = 0;
            this.lastReportedTime = 0;
            this.lastTimeUpdate = performance.now();
          }
    
          destroy() {
            // 1. Remove active global window listeners
            window.removeEventListener("keydown", this.handleKeyDown);
            window.removeEventListener("keyup", this.handleKeyUp);
            window.removeEventListener("resize", this.handleResize);
    
            if (this.startGameTimeout) clearTimeout(this.startGameTimeout);
    
            if (this.autoplayWakeLocked) {
              if (typeof noSleep !== "undefined") noSleep.disable();
              this.autoplayWakeLocked = false;
            }
    
            // 2. Shut down active audio playback safely
            if (this.audioPlayback) {
              this.audioPlayback.pause();
              this.audioPlayback.src = "";
              this.audioPlayback = null;
            }
    
            // 3. Kill background gameplay and calibration loops
            this.isPlaying = false;
            this.isCalibrating = false;
            if (this.calAnimId) {
              cancelAnimationFrame(this.calAnimId);
            }
    
            // 4. Release local calibration touch bindings
            const area = document.getElementById("rg-cal-test-area");
            if (area) {
              if (this.boundCalTouchStart)
                area.removeEventListener("touchstart", this.boundCalTouchStart);
              if (this.boundCalMouseDown)
              area.removeEventListener("mousedown", this.boundCalMouseDown);
            }

            // 5. Hide lingering UI dialogs to prevent them from showing after a reload or navigation
            const pauseDialog = document.getElementById("rg-dialog-pause");
            if (pauseDialog) pauseDialog.classList.add("rg-hidden");
            const playDialog = document.getElementById("rg-dialog-play");
            if (playDialog) playDialog.classList.add("rg-hidden");
            const chartDialog = document.getElementById("rg-dialog-chart-modal");
            if (chartDialog) chartDialog.classList.add("rg-hidden");

            // 6. Clean up main reference memory
            localRhythmGame = null;
          }
    
          initDOM() {
            this.screens = {
              hub: document.getElementById("rg-screen-hub"),
              loading: document.getElementById("rg-screen-loading"),
              game: document.getElementById("rg-screen-game"),
              result: document.getElementById("rg-screen-result"),
            };
            this.tabs = {
              songs: document.getElementById("rg-tab-songs"),
              offline: document.getElementById("rg-tab-offline"),
              artists: document.getElementById("rg-tab-artists"),
              artistDetail: document.getElementById("rg-tab-artist-detail"),
              favorites: document.getElementById("rg-tab-favorites"),
              leaderboard: document.getElementById("rg-tab-leaderboard"),
              settings: document.getElementById("rg-tab-settings"),
            };
            this.listSongsEl = document.getElementById("rg-list-songs");
            this.listFavsEl = document.getElementById("rg-list-favs");
            this.listOfflineEl = document.getElementById("rg-list-offline");
            this.allOfflineLoaded = false;
            this.isLoadingOffline = false;
            this.offlinePage = 1;
            this.allArtistFollowingLoaded = false;
            this.isLoadingArtistFollowing = false;
            this.artistFollowingPage = 1;
    
            setTimeout(() => {
              this.switchScreen("hub");
              if (!navigator.onLine) {
                const offlineTabBtn = document.querySelector(
                  '.rg-nav-item[data-target="offline"]',
                );
                if (offlineTabBtn) offlineTabBtn.click();
              } else {
                this.loadSongs();
              }
            }, 50);
    
            const navItems = document.querySelectorAll(".rg-nav-item");
            navItems.forEach((item) => {
              item.addEventListener("click", () => {
                navItems.forEach((n) => n.classList.remove("active"));
                item.classList.add("active");
                const target = item.getAttribute("data-target");
    
                if (target) {
                  // Cache active tab choice to survive page reloads
                  localStorage.setItem("rg_active_tab", target);
    
                  Object.values(this.tabs).forEach((t) => {
                    if (t) t.classList.add("rg-hidden");
                  });
                  if (this.tabs[target]) {
                    this.tabs[target].classList.remove("rg-hidden");
                  }
                  if (target === "artists") {
                    localStorage.removeItem("rg_active_artist");
                    this.loadArtists();
                  } else if (target === "favorites") {
                    localStorage.removeItem("rg_active_artist");
                    this.loadFavorites();
                  } else if (target === "offline") {
                    localStorage.removeItem("rg_active_artist");
                    this.loadOfflineSongs();
                  } else {
                    localStorage.removeItem("rg_active_artist");
                  }
                }
              });
            });
    
            const myProfileBtn = document.getElementById("rg-nav-my-profile");
            if (myProfileBtn) {
              myProfileBtn.addEventListener("click", () => {
                if (
                  typeof currentUser !== "undefined" &&
                  currentUser &&
                  currentUser.artist
                ) {
                  this.openArtistDetail(currentUser.artist);
                } else {
                  showToast("Please log in to view your profile.", "error");
                }
              });
            }
    
            // Artists Search & Sort (Null-safe)
            let searchArtistDebounce = null;
            const rgSearchArtists = document.getElementById("rg-search-artists");
            if (rgSearchArtists) {
              rgSearchArtists.addEventListener("input", (e) => {
                clearTimeout(searchArtistDebounce);
                searchArtistDebounce = setTimeout(() => {
                  this.loadArtists();
                }, 300);
              });
            }
            const rgSortArtists = document.getElementById("rg-sort-artists");
            if (rgSortArtists) {
              rgSortArtists.addEventListener("change", (e) => {
                this.loadArtists();
              });
            }
    
            // Offline Search & Sort
            let searchOfflineDebounce = null;
            const rgSearchOffline = document.getElementById("rg-search-offline");
            if (rgSearchOffline) {
              rgSearchOffline.addEventListener("input", (e) => {
                clearTimeout(searchOfflineDebounce);
                searchOfflineDebounce = setTimeout(() => {
                  this.loadOfflineSongs();
                }, 300);
              });
            }
            const rgSortOffline = document.getElementById("rg-sort-offline");
            if (rgSortOffline) {
              rgSortOffline.addEventListener("change", (e) => {
                this.loadOfflineSongs();
              });
            }
            if (this.listOfflineEl) {
              this.listOfflineEl.addEventListener("scroll", () => {
                if (
                  this.listOfflineEl.scrollTop + this.listOfflineEl.clientHeight >=
                  this.listOfflineEl.scrollHeight - 50
                ) {
                  if (!this.isLoadingOffline && !this.allOfflineLoaded) {
                    this.offlinePage++;
                    this.loadOfflineSongs(true);
                  }
                }
              });
            }
    
            // Chart Viewer logic
            const btnViewChart = document.getElementById("rg-btn-view-chart");
            const chartModal = document.getElementById("rg-dialog-chart-modal");
            const chartContent = document.getElementById("rg-chart-modal-content");
            const btnCloseChart = document.getElementById("rg-btn-close-chart");
            const btnDlChart = document.getElementById("rg-btn-dl-chart");
    
            if (btnViewChart && chartModal && chartContent) {
              btnViewChart.addEventListener("click", async () => {
                if (!this.selectedSong) return;
    
                chartModal.classList.remove("rg-hidden");
                chartContent.innerHTML =
                  '<div class="spinner-border text-danger mt-4" style="width: 2rem; height: 2rem; border-width: 0.25em;"></div><div class="text-secondary mt-2 small fw-bold text-uppercase">Compiling map...</div>';
    
                try {
                  const dbChart = await fetchData(
                    `?action=get_rhythm_chart&song_id=${this.selectedSong.id}&difficulty=${this.selectedDiff}`,
                    {},
                    true,
                  );
                  if (dbChart && dbChart.found && dbChart.notes) {
                    // Temporarily store state required for the local SVG generator method
                    const tempNotes = this.chartNotes;
                    const tempLanes = this.LANES;
                    const tempAudio = this.audioBuffer;
    
                    this.chartNotes = dbChart.notes;
                    this.LANES =
                      this.selectedDiff === "easy" || this.selectedDiff === "medium"
                        ? 4
                        : this.selectedDiff === "demon"
                          ? 10
                          : 6;
                    this.audioBuffer = {
                      duration: this.selectedSong.duration || 180,
                    };
    
                    const svgHtml = this.generateChartSVG();
                    chartContent.innerHTML = svgHtml;
    
                    // Restore actual live game state so we don't break playback
                    this.chartNotes = tempNotes;
                    this.LANES = tempLanes;
                    this.audioBuffer = tempAudio;
                  } else {
                    chartContent.innerHTML =
                      '<div class="text-danger mt-4 fw-bold">Failed to generate chart.</div>';
                  }
                } catch (err) {
                  chartContent.innerHTML =
                    '<div class="text-danger mt-4 fw-bold"><i class="bi bi-cloud-slash-fill me-1"></i> Offline or Network Error.</div>';
                }
              });
    
              if (btnCloseChart) {
                btnCloseChart.addEventListener("click", () =>
                  chartModal.classList.add("rg-hidden"),
                );
              }
    
              if (btnDlChart) {
                btnDlChart.addEventListener("click", () => {
                  const svgData = chartContent.innerHTML;
                  if (!svgData.includes("<svg"))
                    return showToast("No chart available to download.", "error");
                  const blob = new Blob([svgData], {
                    type: "image/svg+xml;charset=utf-8",
                  });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement("a");
                  a.href = url;
                  a.download = `chart_${this.selectedSong.id}_${this.selectedDiff}.svg`;
                  document.body.appendChild(a);
                  a.click();
                  document.body.removeChild(a);
                  URL.revokeObjectURL(url);
                });
              }
            }
    
            // Artist Songs Search & Sort (Null-safe)
            let searchArtistSongsDebounce = null;
            const rgSearchArtistSongs = document.getElementById(
              "rg-search-artist-songs",
            );
            if (rgSearchArtistSongs) {
              rgSearchArtistSongs.addEventListener("input", (e) => {
                clearTimeout(searchArtistSongsDebounce);
                searchArtistSongsDebounce = setTimeout(() => {
                  this.loadArtistSongs(this.activeArtistDetailName);
                }, 300);
              });
            }
            const rgSortArtistSongs = document.getElementById("rg-sort-artist-songs");
            if (rgSortArtistSongs) {
              rgSortArtistSongs.addEventListener("change", (e) => {
                this.loadArtistSongs(this.activeArtistDetailName);
              });
            }
    
            // Cancel Multi-Artist Dialog Click (Null-safe)
            const rgBtnArtistChoiceCancel = document.getElementById(
              "rg-btn-artist-choice-cancel",
            );
            if (rgBtnArtistChoiceCancel) {
              rgBtnArtistChoiceCancel.addEventListener("click", () => {
                const dialogChoice = document.getElementById(
                  "rg-dialog-artist-choice",
                );
                if (dialogChoice) dialogChoice.classList.add("rg-hidden");
              });
            }
    
            const keyBtns = document.querySelectorAll(".rg-key-btn");
            keyBtns.forEach((btn, idx) => {
              if (this.KEY_LABELS[idx]) btn.textContent = this.KEY_LABELS[idx];
              btn.addEventListener("click", () => {
                keyBtns.forEach((b) => b.classList.remove("listening"));
                this.listeningLane = parseInt(btn.getAttribute("data-lane"));
                btn.classList.add("listening");
              });
            });
    
            const offsetSlider = document.getElementById("rg-offset-slider");
            if (offsetSlider) {
              offsetSlider.value = this.calibrationOffsetMs;
              document.getElementById("rg-offset-display").textContent =
                `${this.calibrationOffsetMs >= 0 ? "+" : ""}${this.calibrationOffsetMs}ms`;
              offsetSlider.addEventListener("input", (e) => {
                this.calibrationOffsetMs = parseInt(e.target.value);
                document.getElementById("rg-offset-display").textContent =
                  `${this.calibrationOffsetMs >= 0 ? "+" : ""}${this.calibrationOffsetMs}ms`;
                localStorage.setItem("rg_cal_offset", this.calibrationOffsetMs);
              });
    
              document
                .getElementById("rg-offset-minus")
                ?.addEventListener("click", () => {
                  offsetSlider.value = Math.max(
                    parseInt(offsetSlider.min),
                    parseInt(offsetSlider.value) - parseInt(offsetSlider.step || 1),
                  );
                  offsetSlider.dispatchEvent(new Event("input"));
                });
              document
                .getElementById("rg-offset-plus")
                ?.addEventListener("click", () => {
                  offsetSlider.value = Math.min(
                    parseInt(offsetSlider.max),
                    parseInt(offsetSlider.value) + parseInt(offsetSlider.step || 1),
                  );
                  offsetSlider.dispatchEvent(new Event("input"));
                });
            }
    
            const speedSlider = document.getElementById("rg-speed-slider");
            if (speedSlider) {
              speedSlider.value = this.userTickSpeed;
              document.getElementById("rg-speed-display").textContent =
                `${this.userTickSpeed}x`;
              speedSlider.addEventListener("input", (e) => {
                this.userTickSpeed = parseFloat(e.target.value);
                this.userTickSpeed = Math.round(this.userTickSpeed * 10) / 10;
                document.getElementById("rg-speed-display").textContent =
                  `${this.userTickSpeed}x`;
                localStorage.setItem("rg_tick_speed", this.userTickSpeed);
              });
    
              document
                .getElementById("rg-speed-minus")
                ?.addEventListener("click", () => {
                  speedSlider.value = Math.max(
                    parseFloat(speedSlider.min),
                    parseFloat(speedSlider.value) -
                      parseFloat(speedSlider.step || 0.1),
                  );
                  speedSlider.dispatchEvent(new Event("input"));
                });
              document
                .getElementById("rg-speed-plus")
                ?.addEventListener("click", () => {
                  speedSlider.value = Math.min(
                    parseFloat(speedSlider.max),
                    parseFloat(speedSlider.value) +
                      parseFloat(speedSlider.step || 0.1),
                  );
                  speedSlider.dispatchEvent(new Event("input"));
                });
            }
    
            const sfxSlider = document.getElementById("rg-sfx-slider");
            if (sfxSlider) {
              sfxSlider.value = this.sfxVolume;
              document.getElementById("rg-sfx-display").textContent =
                Math.round(this.sfxVolume * 100) + "%";
              sfxSlider.addEventListener("input", (e) => {
                this.sfxVolume = parseFloat(e.target.value);
                this.sfxVolume = Math.round(this.sfxVolume * 100) / 100;
                document.getElementById("rg-sfx-display").textContent =
                  Math.round(this.sfxVolume * 100) + "%";
                localStorage.setItem("rg_sfx_volume", this.sfxVolume);
                if (this.sfxVolume > 0 && !this.sfxCtx) {
                  this.sfxCtx = new (
                    window.AudioContext || window.webkitAudioContext
                  )();
                }
                this.playHitSFX();
              });
    
              document
                .getElementById("rg-sfx-minus")
                ?.addEventListener("click", () => {
                  sfxSlider.value = Math.max(
                    parseFloat(sfxSlider.min),
                    parseFloat(sfxSlider.value) - parseFloat(sfxSlider.step || 0.05),
                  );
                  sfxSlider.dispatchEvent(new Event("input"));
                });
              document
                .getElementById("rg-sfx-plus")
                ?.addEventListener("click", () => {
                  sfxSlider.value = Math.min(
