                  localStorage.removeItem("rg_tick_speed");
                  localStorage.removeItem("rg_sfx_volume");
    
                  if (offsetSlider) {
                    offsetSlider.value = 0;
                    offsetSlider.dispatchEvent(new Event("input"));
                  }
                  if (speedSlider) {
                    speedSlider.value = 1.0;
                    speedSlider.dispatchEvent(new Event("input"));
