                  hard: "#fb923c",
                  expert: "#f43f5e",
                  master: "#a78bfa",
                  demon: "#7f1d1d",
                };
                const diffLabels = {
                  easy: "EZ",
                  medium: "ND",
                  hard: "HD",
                  expert: "EX",
                  master: "MS",
                  demon: "DM",
                };
    
                const cardsHtml = scores
