                window.rhythmLevelsMap = {
                  levels: {},
                };
              if (!window.rhythmLevelsMap.levels) window.rhythmLevelsMap.levels = {};
              window.rhythmLevelsMap.levels[song.id] = song.levels;
            }
    
            const levels =
              window.rhythmLevelsMap &&
